-- VYBR8 · Full database setup. Run ONCE on a new, empty Supabase project (SQL Editor → paste → Run).
-- Generated by scripts/build-setup.sh from supabase/migrations. Do not edit by hand.

-- ═════ 20260928000100_foundation.sql ═════
-- VYBR8 · Phase 1 · Foundation
-- Shared schema, enums and helper functions used by every later migration.

create extension if not exists citext with schema extensions;
create extension if not exists pgcrypto with schema extensions;

-- Security-definer helpers live here. This schema is NOT exposed through the Data API.
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to anon, authenticated, service_role;

-- ── Enums (closed sets only; growing taxonomies are rows, see DATABASE.md) ──
create type public.platform_role        as enum ('admin', 'moderator');
create type public.visibility           as enum ('public', 'friends', 'private');
create type public.friendship_status    as enum ('pending', 'accepted', 'declined', 'blocked');
create type public.business_kind        as enum (
  'restaurant', 'bar', 'cocktail_lounge', 'lounge', 'cigar_lounge', 'hookah_lounge',
  'cafe', 'bakery', 'food_truck', 'brewery', 'nightlife'
);
create type public.business_status      as enum ('pending', 'active', 'hidden');
create type public.business_member_role as enum ('owner', 'manager', 'staff');
create type public.claim_status         as enum ('pending', 'approved', 'rejected', 'withdrawn');

-- ── updated_at maintenance ──
create or replace function private.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ═════ 20260928000200_identity.sql ═════
-- VYBR8 · Phase 1 · Identity, platform roles, privacy, friendships

-- ── Tables ─────────────────────────────────────────────────────────────

create table public.profiles (
  id            uuid primary key references auth.users (id) on delete cascade,
  username      extensions.citext not null unique
                check (username::text ~ '^[A-Za-z0-9_.]{3,30}$'),
  display_name  text check (char_length(display_name) <= 60),
  avatar_url    text,
  bio           text check (char_length(bio) <= 280),
  home_city     text,
  home_region   text,
  is_demo       boolean not null default false,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create table public.user_settings (
  user_id             uuid primary key references public.profiles (id) on delete cascade,
  units               text not null default 'imperial' check (units in ('imperial', 'metric')),
  search_radius_km    numeric(5,1) not null default 15 check (search_radius_km between 0.5 and 500),
  big_back_mode       boolean not null default false,
  notification_prefs  jsonb not null default '{}'::jsonb,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);

create table public.privacy_settings (
  user_id              uuid primary key references public.profiles (id) on delete cascade,
  profile_visibility   public.visibility not null default 'public',
  ratings_visibility   public.visibility not null default 'public',
  saves_visibility     public.visibility not null default 'friends',
  taste_visibility     public.visibility not null default 'friends',
  activity_visibility  public.visibility not null default 'friends',
  dietary_visibility   public.visibility not null default 'private',
  -- Health data is private, full stop. Relaxing this requires a reviewed migration.
  health_visibility    public.visibility not null default 'private'
                       check (health_visibility = 'private'),
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

create table public.user_roles (
  user_id     uuid not null references public.profiles (id) on delete cascade,
  role        public.platform_role not null,
  granted_by  uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  primary key (user_id, role)
);

create table public.friendships (
  id            uuid primary key default gen_random_uuid(),
  requester_id  uuid not null references public.profiles (id) on delete cascade,
  addressee_id  uuid not null references public.profiles (id) on delete cascade,
  status        public.friendship_status not null default 'pending',
  blocked_by    uuid references public.profiles (id) on delete set null,
  responded_at  timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  check (requester_id <> addressee_id)
);
-- One relationship per pair, regardless of who asked first.
create unique index friendships_pair_key
  on public.friendships (least(requester_id, addressee_id), greatest(requester_id, addressee_id));
create index friendships_addressee_idx on public.friendships (addressee_id, status);

create trigger profiles_updated_at          before update on public.profiles          for each row execute function private.set_updated_at();
create trigger user_settings_updated_at     before update on public.user_settings     for each row execute function private.set_updated_at();
create trigger privacy_settings_updated_at  before update on public.privacy_settings  for each row execute function private.set_updated_at();
create trigger friendships_updated_at       before update on public.friendships       for each row execute function private.set_updated_at();

-- ── Helper functions (security definer, fixed search_path) ─────────────

create or replace function private.has_platform_role(p_role public.platform_role)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.user_roles
    where user_id = (select auth.uid()) and role = p_role
  );
$$;

create or replace function private.is_admin()
returns boolean
language sql stable security definer
set search_path = ''
as $$ select private.has_platform_role('admin'); $$;

create or replace function private.is_staff()
returns boolean
language sql stable security definer
set search_path = ''
as $$ select private.has_platform_role('admin') or private.has_platform_role('moderator'); $$;

create or replace function private.are_friends(a uuid, b uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select a is not null and b is not null and exists (
    select 1 from public.friendships f
    where f.status = 'accepted'
      and least(f.requester_id, f.addressee_id)    = least(a, b)
      and greatest(f.requester_id, f.addressee_id) = greatest(a, b)
  );
$$;

-- Can the current viewer see `owner_id`'s data on a given privacy surface?
-- Surfaces: profile, ratings, saves, taste, activity, dietary, health.
create or replace function private.can_view(owner_id uuid, surface text)
returns boolean
language plpgsql stable security definer
set search_path = ''
as $$
declare
  viewer uuid := (select auth.uid());
  vis    public.visibility;
begin
  if owner_id is null then return false; end if;
  if viewer = owner_id then return true; end if;

  select case surface
           when 'profile'  then p.profile_visibility
           when 'ratings'  then p.ratings_visibility
           when 'saves'    then p.saves_visibility
           when 'taste'    then p.taste_visibility
           when 'activity' then p.activity_visibility
           when 'dietary'  then p.dietary_visibility
           when 'health'   then p.health_visibility
         end
    into vis
    from public.privacy_settings p
   where p.user_id = owner_id;

  if vis is null then return false; end if;          -- unknown surface or no row: deny
  if surface = 'health' then return false; end if;    -- never shared, even with admins
  if private.is_staff() then return true; end if;     -- moderation needs visibility
  if vis = 'public' then return true; end if;
  if vis = 'friends' then return private.are_friends(owner_id, viewer); end if;
  return false;
end;
$$;

grant execute on all functions in schema private to anon, authenticated, service_role;

-- ── Sign-up: create profile, settings and privacy rows ─────────────────

create or replace function private.handle_new_user()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  wanted text := nullif(trim(new.raw_user_meta_data ->> 'username'), '');
  uname  text;
begin
  if wanted is not null
     and wanted ~ '^[A-Za-z0-9_.]{3,30}$'
     and not exists (select 1 from public.profiles where username = wanted::extensions.citext) then
    uname := wanted;
  else
    uname := 'vyber_' || left(replace(new.id::text, '-', ''), 12);
  end if;

  insert into public.profiles (id, username, display_name, is_demo)
  values (
    new.id,
    uname,
    left(coalesce(nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''), uname), 60),
    coalesce((new.raw_user_meta_data ->> 'is_demo')::boolean, false)
  );
  insert into public.user_settings (user_id) values (new.id);
  insert into public.privacy_settings (user_id) values (new.id);
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function private.handle_new_user();

-- ── Guards ─────────────────────────────────────────────────────────────

-- Users cannot flip their own demo flag.
create or replace function private.profiles_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and not private.is_admin()
     and new.is_demo is distinct from old.is_demo then
    raise exception 'is_demo can only be changed by an admin' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger profiles_guard before update on public.profiles
  for each row execute function private.profiles_guard();

-- Friendship state machine.
create or replace function private.friendships_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  me uuid := (select auth.uid());
begin
  if me is null then return new; end if;  -- service role / migrations

  if new.requester_id <> old.requester_id or new.addressee_id <> old.addressee_id
     or (new.blocked_by is distinct from old.blocked_by and new.status is not distinct from old.status) then
    raise exception 'friendship parties cannot change' using errcode = '42501';
  end if;

  if new.status is distinct from old.status then
    if new.status in ('accepted', 'declined') then
      if me <> old.addressee_id or old.status <> 'pending' then
        raise exception 'only the invited person can respond to a pending request' using errcode = '42501';
      end if;
    elsif new.status = 'blocked' then
      new.blocked_by := me;  -- either party may block
    elsif old.status = 'blocked' then
      raise exception 'remove the block instead of changing its status' using errcode = '42501';
    else
      raise exception 'invalid friendship transition % -> %', old.status, new.status using errcode = '42501';
    end if;
    new.responded_at := now();
  end if;
  return new;
end;
$$;
create trigger friendships_guard before update on public.friendships
  for each row execute function private.friendships_guard();

-- ── Row Level Security ─────────────────────────────────────────────────

alter table public.profiles          enable row level security;
alter table public.user_settings     enable row level security;
alter table public.privacy_settings  enable row level security;
alter table public.user_roles        enable row level security;
alter table public.friendships       enable row level security;

-- profiles
create policy "profiles: visible per privacy setting"
  on public.profiles for select to anon, authenticated
  using (private.can_view(id, 'profile'));
create policy "profiles: owner updates own"
  on public.profiles for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));
-- Inserts happen only through the sign-up trigger; deletes cascade from auth.users.

-- user_settings / privacy_settings: owner only
create policy "user_settings: owner reads"   on public.user_settings for select to authenticated using (user_id = (select auth.uid()));
create policy "user_settings: owner updates" on public.user_settings for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "privacy_settings: owner reads"   on public.privacy_settings for select to authenticated using (user_id = (select auth.uid()));
create policy "privacy_settings: owner updates" on public.privacy_settings for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- user_roles: users can see their own roles; admins can see all. No client writes.
create policy "user_roles: read own or admin"
  on public.user_roles for select to authenticated
  using (user_id = (select auth.uid()) or private.is_admin());

-- friendships
create policy "friendships: parties read"
  on public.friendships for select to authenticated
  using ((select auth.uid()) in (requester_id, addressee_id));
create policy "friendships: send request"
  on public.friendships for insert to authenticated
  with check (requester_id = (select auth.uid()) and status = 'pending');
create policy "friendships: parties update"
  on public.friendships for update to authenticated
  using ((select auth.uid()) in (requester_id, addressee_id))
  with check ((select auth.uid()) in (requester_id, addressee_id));
create policy "friendships: parties remove"
  on public.friendships for delete to authenticated
  using ((select auth.uid()) in (requester_id, addressee_id)
         and (status <> 'blocked' or blocked_by = (select auth.uid())));

-- ═════ 20260928000300_businesses.sql ═════
-- VYBR8 · Phase 1 · Businesses, locations, membership, claims, audit log

-- ── Tables ─────────────────────────────────────────────────────────────

create table public.businesses (
  id           uuid primary key default gen_random_uuid(),
  slug         extensions.citext not null unique check (slug::text ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) <= 80),
  name         text not null check (char_length(name) between 1 and 120),
  kind         public.business_kind not null,
  description  text check (char_length(description) <= 2000),
  price_level  smallint check (price_level between 1 and 4),
  website      text,
  phone        text,
  status       public.business_status not null default 'pending',
  is_claimed   boolean not null default false,
  is_demo      boolean not null default false,
  created_by   uuid references public.profiles (id) on delete set null,
  deleted_at   timestamptz,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index businesses_status_idx on public.businesses (status) where deleted_at is null;

create table public.business_locations (
  id             uuid primary key default gen_random_uuid(),
  business_id    uuid not null references public.businesses (id) on delete cascade,
  label          text,
  address_line1  text,
  address_line2  text,
  city           text not null,
  region         text not null,           -- state / province code, e.g. NC
  postal_code    text,
  country        text not null default 'US' check (char_length(country) = 2),
  latitude       numeric(9,6) check (latitude between -90 and 90),
  longitude      numeric(9,6) check (longitude between -180 and 180),
  timezone       text not null default 'America/New_York',
  is_primary     boolean not null default false,
  is_demo        boolean not null default false,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index business_locations_business_idx on public.business_locations (business_id);
create index business_locations_city_idx on public.business_locations (country, region, city);
create unique index business_locations_one_primary on public.business_locations (business_id) where is_primary;

create table public.business_members (
  business_id  uuid not null references public.businesses (id) on delete cascade,
  user_id      uuid not null references public.profiles (id) on delete cascade,
  role         public.business_member_role not null,
  invited_by   uuid references public.profiles (id) on delete set null,
  created_at   timestamptz not null default now(),
  primary key (business_id, user_id)
);
create index business_members_user_idx on public.business_members (user_id);

create table public.business_claims (
  id              uuid primary key default gen_random_uuid(),
  business_id     uuid not null references public.businesses (id) on delete cascade,
  claimant_id     uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  status          public.claim_status not null default 'pending',
  claimant_role   text check (char_length(claimant_role) <= 80),   -- "Owner", "General manager"
  evidence        jsonb not null default '{}'::jsonb,               -- private: storage paths, contact info
  decision_note   text,
  reviewed_by     uuid references public.profiles (id) on delete set null,
  reviewed_at     timestamptz,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create unique index business_claims_one_pending
  on public.business_claims (business_id, claimant_id) where status = 'pending';
create index business_claims_status_idx on public.business_claims (status, created_at);

create table public.audit_logs (
  id           bigint generated always as identity primary key,
  actor_id     uuid references public.profiles (id) on delete set null,
  action       text not null,
  entity_type  text not null,
  entity_id    uuid,
  metadata     jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now()
);
create index audit_logs_entity_idx on public.audit_logs (entity_type, entity_id, created_at desc);

create trigger businesses_updated_at          before update on public.businesses          for each row execute function private.set_updated_at();
create trigger business_locations_updated_at  before update on public.business_locations  for each row execute function private.set_updated_at();
create trigger business_claims_updated_at     before update on public.business_claims     for each row execute function private.set_updated_at();

-- ── Helpers ────────────────────────────────────────────────────────────

create or replace function private.business_role(p_business_id uuid)
returns public.business_member_role
language sql stable security definer
set search_path = ''
as $$
  select role from public.business_members
  where business_id = p_business_id and user_id = (select auth.uid());
$$;

create or replace function private.is_business_member(p_business_id uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$ select private.business_role(p_business_id) is not null; $$;

create or replace function private.can_edit_business(p_business_id uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$ select private.is_admin() or private.business_role(p_business_id) in ('owner', 'manager'); $$;

create or replace function private.business_is_claimable(p_business_id uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.businesses
    where id = p_business_id and status = 'active' and not is_claimed and deleted_at is null
  );
$$;

grant execute on all functions in schema private to anon, authenticated, service_role;

-- ── Guards: privileged columns ─────────────────────────────────────────

create or replace function private.businesses_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select auth.uid()) is null or private.is_admin() then return new; end if;
  if new.status     is distinct from old.status
  or new.is_claimed is distinct from old.is_claimed
  or new.is_demo    is distinct from old.is_demo
  or new.slug       is distinct from old.slug
  or new.deleted_at is distinct from old.deleted_at
  or new.created_by is distinct from old.created_by then
    raise exception 'status, claim, demo, slug and deletion fields are admin-only' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger businesses_guard before update on public.businesses
  for each row execute function private.businesses_guard();

create or replace function private.business_locations_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select auth.uid()) is null or private.is_admin() then return new; end if;
  if tg_op = 'UPDATE' and (new.business_id <> old.business_id or new.is_demo is distinct from old.is_demo) then
    raise exception 'locations cannot move between businesses or change demo status' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' and new.is_demo then
    raise exception 'only admins create demo records' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger business_locations_guard before insert or update on public.business_locations
  for each row execute function private.business_locations_guard();

-- Claimants may only withdraw their own pending claim. Decisions go through admin RPCs.
create or replace function private.business_claims_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select auth.uid()) is null or private.is_admin() then return new; end if;
  if old.status = 'pending' and new.status = 'withdrawn'
     and new.business_id = old.business_id and new.claimant_id = old.claimant_id
     and new.reviewed_by is not distinct from old.reviewed_by
     and new.decision_note is not distinct from old.decision_note then
    return new;
  end if;
  if new.status = old.status and old.status = 'pending'
     and new.business_id = old.business_id and new.claimant_id = old.claimant_id
     and new.reviewed_by is not distinct from old.reviewed_by
     and new.reviewed_at is not distinct from old.reviewed_at
     and new.decision_note is not distinct from old.decision_note then
    return new;  -- editing evidence / role while pending
  end if;
  raise exception 'claims can only be edited or withdrawn while pending' using errcode = '42501';
end;
$$;
create trigger business_claims_guard before update on public.business_claims
  for each row execute function private.business_claims_guard();

-- ── Row Level Security ─────────────────────────────────────────────────

alter table public.businesses          enable row level security;
alter table public.business_locations  enable row level security;
alter table public.business_members    enable row level security;
alter table public.business_claims     enable row level security;
alter table public.audit_logs          enable row level security;

-- businesses
create policy "businesses: public reads active"
  on public.businesses for select to anon, authenticated
  using ((status = 'active' and deleted_at is null)
         or private.is_business_member(id)
         or private.is_admin());
create policy "businesses: admins create"
  on public.businesses for insert to authenticated
  with check (private.is_admin());
create policy "businesses: owners and managers edit"
  on public.businesses for update to authenticated
  using (private.can_edit_business(id)) with check (private.can_edit_business(id));
create policy "businesses: admins delete"
  on public.businesses for delete to authenticated
  using (private.is_admin());

-- business_locations: visible when the parent business is visible
create policy "business_locations: follow parent visibility"
  on public.business_locations for select to anon, authenticated
  using (exists (select 1 from public.businesses b where b.id = business_id));
create policy "business_locations: editors insert"
  on public.business_locations for insert to authenticated
  with check (private.can_edit_business(business_id));
create policy "business_locations: editors update"
  on public.business_locations for update to authenticated
  using (private.can_edit_business(business_id)) with check (private.can_edit_business(business_id));
create policy "business_locations: editors delete"
  on public.business_locations for delete to authenticated
  using (private.can_edit_business(business_id));

-- business_members: team can see the team; owners manage non-owner roles; admins manage all
create policy "business_members: team and admins read"
  on public.business_members for select to authenticated
  using (user_id = (select auth.uid()) or private.is_business_member(business_id) or private.is_admin());
create policy "business_members: owners add non-owners"
  on public.business_members for insert to authenticated
  with check (private.is_admin()
              or (private.business_role(business_id) = 'owner' and role <> 'owner'));
create policy "business_members: owners change non-owners"
  on public.business_members for update to authenticated
  using (private.is_admin() or (private.business_role(business_id) = 'owner' and role <> 'owner'))
  with check (private.is_admin() or (private.business_role(business_id) = 'owner' and role <> 'owner'));
create policy "business_members: owners remove non-owners, members leave"
  on public.business_members for delete to authenticated
  using (private.is_admin()
         or (private.business_role(business_id) = 'owner' and role <> 'owner')
         or (user_id = (select auth.uid()) and role <> 'owner'));

-- business_claims
create policy "business_claims: claimant and admins read"
  on public.business_claims for select to authenticated
  using (claimant_id = (select auth.uid()) or private.is_admin());
create policy "business_claims: users file claims"
  on public.business_claims for insert to authenticated
  with check (claimant_id = (select auth.uid())
              and status = 'pending'
              and reviewed_by is null and reviewed_at is null and decision_note is null
              and private.business_is_claimable(business_id));
create policy "business_claims: claimant edits pending, admins all"
  on public.business_claims for update to authenticated
  using (claimant_id = (select auth.uid()) or private.is_admin())
  with check (claimant_id = (select auth.uid()) or private.is_admin());

-- audit_logs: admin read only. Rows are written by security-definer functions.
create policy "audit_logs: admins read"
  on public.audit_logs for select to authenticated
  using (private.is_admin());

-- ── Admin RPCs ─────────────────────────────────────────────────────────

create or replace function public.approve_business_claim(p_claim_id uuid, p_note text default null)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  c public.business_claims;
begin
  if not private.is_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;

  select * into c from public.business_claims where id = p_claim_id for update;
  if not found then raise exception 'claim not found' using errcode = 'P0002'; end if;
  if c.status <> 'pending' then raise exception 'claim is %', c.status using errcode = '22023'; end if;

  update public.business_claims
     set status = 'approved', decision_note = p_note, reviewed_by = auth.uid(), reviewed_at = now()
   where id = c.id;

  -- Other pending claims on the same business are closed.
  update public.business_claims
     set status = 'rejected', decision_note = 'Another claim for this business was approved',
         reviewed_by = auth.uid(), reviewed_at = now()
   where business_id = c.business_id and status = 'pending' and id <> c.id;

  insert into public.business_members (business_id, user_id, role, invited_by)
  values (c.business_id, c.claimant_id, 'owner', auth.uid())
  on conflict (business_id, user_id) do update set role = 'owner';

  update public.businesses set is_claimed = true where id = c.business_id;

  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'business_claim.approved', 'business', c.business_id,
          jsonb_build_object('claim_id', c.id, 'claimant_id', c.claimant_id));
end;
$$;

create or replace function public.reject_business_claim(p_claim_id uuid, p_note text)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  c public.business_claims;
begin
  if not private.is_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;
  if coalesce(trim(p_note), '') = '' then
    raise exception 'a reason is required' using errcode = '22023';
  end if;

  select * into c from public.business_claims where id = p_claim_id for update;
  if not found then raise exception 'claim not found' using errcode = 'P0002'; end if;
  if c.status <> 'pending' then raise exception 'claim is %', c.status using errcode = '22023'; end if;

  update public.business_claims
     set status = 'rejected', decision_note = p_note, reviewed_by = auth.uid(), reviewed_at = now()
   where id = c.id;

  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'business_claim.rejected', 'business', c.business_id,
          jsonb_build_object('claim_id', c.id, 'claimant_id', c.claimant_id));
end;
$$;

revoke execute on function public.approve_business_claim(uuid, text) from public, anon;
revoke execute on function public.reject_business_claim(uuid, text)  from public, anon;
grant  execute on function public.approve_business_claim(uuid, text) to authenticated;
grant  execute on function public.reject_business_claim(uuid, text)  to authenticated;

-- ═════ 20260929000100_team_creators.sql ═════
-- VYBR8 · Social layer 1/2 · VYBR8 Team, verified creators, follows
--
-- Creator types:
--   big_back      food creators
--   liquid_lover  drink creators (must attest they are 21+)
--   both

create type public.creator_type       as enum ('big_back', 'liquid_lover', 'both');
create type public.application_status as enum ('pending', 'approved', 'rejected', 'withdrawn');
create type public.creator_status     as enum ('verified', 'suspended');

-- ── VYBR8 Team (public roster, e.g. Founder) ───────────────────────────
-- Titles are display only. Powers come from user_roles (admin / moderator).
create table public.team_members (
  user_id     uuid primary key references public.profiles (id) on delete cascade,
  title       text not null check (char_length(title) between 1 and 60),
  bio         text check (char_length(bio) <= 280),
  position    smallint not null default 100,
  is_public   boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create trigger team_members_updated_at before update on public.team_members
  for each row execute function private.set_updated_at();

-- ── Follows (one-way; friendships stay two-way) ────────────────────────
create table public.follows (
  follower_id  uuid not null references public.profiles (id) on delete cascade,
  followee_id  uuid not null references public.profiles (id) on delete cascade,
  created_at   timestamptz not null default now(),
  primary key (follower_id, followee_id),
  check (follower_id <> followee_id)
);
create index follows_followee_idx on public.follows (followee_id);

-- ── Creator applications and verified creators ─────────────────────────
create table public.creator_applications (
  id                   uuid primary key default gen_random_uuid(),
  user_id              uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  creator_type         public.creator_type not null,
  city                 text check (char_length(city) <= 80),
  pitch                text not null check (char_length(pitch) between 20 and 1000),
  links                jsonb not null default '[]'::jsonb check (jsonb_typeof(links) = 'array' and jsonb_array_length(links) <= 5),
  is_21_plus_attested  boolean not null default false,
  status               public.application_status not null default 'pending',
  decision_note        text check (char_length(decision_note) <= 500),
  reviewed_by          uuid references public.profiles (id) on delete set null,
  reviewed_at          timestamptz,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  -- Liquid Lovers post about drinks, so they must confirm they are of legal drinking age.
  check (creator_type = 'big_back' or is_21_plus_attested)
);
create unique index creator_applications_one_pending on public.creator_applications (user_id) where status = 'pending';
create index creator_applications_queue_idx on public.creator_applications (status, created_at);
create trigger creator_applications_updated_at before update on public.creator_applications
  for each row execute function private.set_updated_at();

create table public.creator_profiles (
  user_id         uuid primary key references public.profiles (id) on delete cascade,
  creator_type    public.creator_type not null,
  status          public.creator_status not null default 'verified',
  application_id  uuid references public.creator_applications (id) on delete set null,
  verified_by     uuid references public.profiles (id) on delete set null,
  verified_at     timestamptz not null default now(),
  status_note     text,
  updated_at      timestamptz not null default now()
);
create index creator_profiles_status_idx on public.creator_profiles (status, creator_type);
create trigger creator_profiles_updated_at before update on public.creator_profiles
  for each row execute function private.set_updated_at();

-- ── Helpers ────────────────────────────────────────────────────────────
create or replace function private.is_blocked_between(a uuid, b uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.friendships f
    where f.status = 'blocked'
      and least(f.requester_id, f.addressee_id)    = least(a, b)
      and greatest(f.requester_id, f.addressee_id) = greatest(a, b)
  );
$$;

create or replace function private.is_verified_creator(p_user uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$ select exists (select 1 from public.creator_profiles where user_id = p_user and status = 'verified'); $$;

grant execute on all functions in schema private to anon, authenticated, service_role;

-- Applicants can edit or withdraw while pending. Decisions go through staff RPCs.
create or replace function private.creator_applications_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select auth.uid()) is null or private.is_staff() then return new; end if;
  if old.status = 'pending' and new.status in ('pending', 'withdrawn')
     and new.user_id = old.user_id
     and new.reviewed_by is not distinct from old.reviewed_by
     and new.reviewed_at is not distinct from old.reviewed_at
     and new.decision_note is not distinct from old.decision_note then
    return new;
  end if;
  raise exception 'applications can only be edited or withdrawn while pending' using errcode = '42501';
end;
$$;
create trigger creator_applications_guard before update on public.creator_applications
  for each row execute function private.creator_applications_guard();

-- ── RLS ────────────────────────────────────────────────────────────────
alter table public.team_members          enable row level security;
alter table public.follows               enable row level security;
alter table public.creator_applications  enable row level security;
alter table public.creator_profiles      enable row level security;

create policy "team_members: public roster"
  on public.team_members for select to anon, authenticated
  using (is_public or private.is_staff());
-- No write policies: the roster is managed with the secret key or SQL editor.

create policy "follows: visible when both profiles are visible"
  on public.follows for select to anon, authenticated
  using (private.can_view(follower_id, 'profile') and private.can_view(followee_id, 'profile'));
create policy "follows: follow visible, unblocked people"
  on public.follows for insert to authenticated
  with check (follower_id = (select auth.uid())
              and private.can_view(followee_id, 'profile')
              and not private.is_blocked_between(follower_id, followee_id));
create policy "follows: unfollow"
  on public.follows for delete to authenticated
  using (follower_id = (select auth.uid()));

create policy "creator_applications: applicant and staff read"
  on public.creator_applications for select to authenticated
  using (user_id = (select auth.uid()) or private.is_staff());
create policy "creator_applications: apply for yourself"
  on public.creator_applications for insert to authenticated
  with check (user_id = (select auth.uid()) and status = 'pending'
              and reviewed_by is null and reviewed_at is null and decision_note is null
              and not private.is_verified_creator(user_id));
create policy "creator_applications: applicant edits pending, staff all"
  on public.creator_applications for update to authenticated
  using (user_id = (select auth.uid()) or private.is_staff())
  with check (user_id = (select auth.uid()) or private.is_staff());

create policy "creator_profiles: verified creators are public"
  on public.creator_profiles for select to anon, authenticated
  using (status = 'verified' or user_id = (select auth.uid()) or private.is_staff());
-- No write policies: only the staff RPCs below change creator status.

-- ── Staff RPCs (VYBR8 Team: admins and moderators) ─────────────────────
create or replace function public.approve_creator_application(p_application_id uuid, p_note text default null)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  a public.creator_applications;
begin
  if not private.is_staff() then raise exception 'VYBR8 team only' using errcode = '42501'; end if;

  select * into a from public.creator_applications where id = p_application_id for update;
  if not found then raise exception 'application not found' using errcode = 'P0002'; end if;
  if a.status <> 'pending' then raise exception 'application is %', a.status using errcode = '22023'; end if;

  update public.creator_applications
     set status = 'approved', decision_note = p_note, reviewed_by = auth.uid(), reviewed_at = now()
   where id = a.id;

  insert into public.creator_profiles (user_id, creator_type, status, application_id, verified_by, verified_at)
  values (a.user_id, a.creator_type, 'verified', a.id, auth.uid(), now())
  on conflict (user_id) do update
    set creator_type = excluded.creator_type, status = 'verified', application_id = excluded.application_id,
        verified_by = excluded.verified_by, verified_at = excluded.verified_at, status_note = null;

  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'creator.verified', 'profile', a.user_id,
          jsonb_build_object('application_id', a.id, 'creator_type', a.creator_type));
end;
$$;

create or replace function public.reject_creator_application(p_application_id uuid, p_note text)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  a public.creator_applications;
begin
  if not private.is_staff() then raise exception 'VYBR8 team only' using errcode = '42501'; end if;
  if coalesce(trim(p_note), '') = '' then raise exception 'a reason is required' using errcode = '22023'; end if;

  select * into a from public.creator_applications where id = p_application_id for update;
  if not found then raise exception 'application not found' using errcode = 'P0002'; end if;
  if a.status <> 'pending' then raise exception 'application is %', a.status using errcode = '22023'; end if;

  update public.creator_applications
     set status = 'rejected', decision_note = p_note, reviewed_by = auth.uid(), reviewed_at = now()
   where id = a.id;

  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'creator.application_rejected', 'profile', a.user_id, jsonb_build_object('application_id', a.id));
end;
$$;

create or replace function public.set_creator_status(p_user_id uuid, p_status public.creator_status, p_note text default null)
returns void
language plpgsql security definer
set search_path = ''
as $$
begin
  if not private.is_staff() then raise exception 'VYBR8 team only' using errcode = '42501'; end if;
  update public.creator_profiles set status = p_status, status_note = p_note where user_id = p_user_id;
  if not found then raise exception 'not a creator' using errcode = 'P0002'; end if;
  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'creator.status_' || p_status, 'profile', p_user_id, jsonb_build_object('note', p_note));
end;
$$;

revoke execute on function public.approve_creator_application(uuid, text) from public, anon;
revoke execute on function public.reject_creator_application(uuid, text) from public, anon;
revoke execute on function public.set_creator_status(uuid, public.creator_status, text) from public, anon;
grant execute on function public.approve_creator_application(uuid, text) to authenticated;
grant execute on function public.reject_creator_application(uuid, text) to authenticated;
grant execute on function public.set_creator_status(uuid, public.creator_status, text) to authenticated;

-- ═════ 20260929000200_posts.sql ═════
-- VYBR8 · Social layer 2/2 · Plates, Pours and Spots (photo posts), vybes, comments, reports, photo storage
--
-- plate  a dish       pour  a drink       spot  the restaurant / bar / lounge itself

create type public.post_kind      as enum ('plate', 'pour', 'spot');
create type public.content_status as enum ('published', 'hidden', 'removed');
create type public.report_reason  as enum ('spam', 'inappropriate', 'harassment', 'misleading', 'underage_drinking', 'not_food_or_drink', 'other');
create type public.report_status  as enum ('open', 'actioned', 'dismissed');

-- ── Posts ──────────────────────────────────────────────────────────────
create table public.posts (
  id           uuid primary key default gen_random_uuid(),
  author_id    uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  kind         public.post_kind not null,
  business_id  uuid references public.businesses (id) on delete set null,
  item_name    text check (char_length(item_name) <= 120),     -- "Hot Honey Wings"; links to menu_items in Phase 3
  caption      text check (char_length(caption) <= 2200),
  rating       numeric(3,1) check (rating between 0 and 10),
  price_cents  integer check (price_cents between 0 and 10000000),
  visibility   public.visibility not null default 'public',
  status       public.content_status not null default 'published',
  status_note  text,
  is_demo      boolean not null default false,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  deleted_at   timestamptz
);
create index posts_author_idx   on public.posts (author_id, created_at desc) where deleted_at is null;
create index posts_business_idx on public.posts (business_id, created_at desc) where deleted_at is null and status = 'published';
create index posts_recent_idx   on public.posts (created_at desc) where deleted_at is null and status = 'published';
create trigger posts_updated_at before update on public.posts for each row execute function private.set_updated_at();

create table public.post_media (
  id            uuid primary key default gen_random_uuid(),
  post_id       uuid not null references public.posts (id) on delete cascade,
  storage_path  text not null unique
                check (storage_path ~ '^[0-9a-f-]{36}/[A-Za-z0-9._-]{1,120}$' or storage_path ~ '^demo/[A-Za-z0-9._-]{1,120}$'),
  position      smallint not null check (position between 0 and 9),
  width         integer check (width between 1 and 10000),
  height        integer check (height between 1 and 10000),
  alt_text      text check (char_length(alt_text) <= 300),
  created_at    timestamptz not null default now(),
  unique (post_id, position)
);

create table public.post_vybes (       -- likes
  post_id     uuid not null references public.posts (id) on delete cascade,
  user_id     uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  created_at  timestamptz not null default now(),
  primary key (post_id, user_id)
);
create index post_vybes_user_idx on public.post_vybes (user_id);

create table public.post_comments (
  id          uuid primary key default gen_random_uuid(),
  post_id     uuid not null references public.posts (id) on delete cascade,
  author_id   uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  body        text not null check (char_length(trim(body)) between 1 and 1000),
  status      public.content_status not null default 'published',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  deleted_at  timestamptz
);
create index post_comments_post_idx on public.post_comments (post_id, created_at);
create trigger post_comments_updated_at before update on public.post_comments for each row execute function private.set_updated_at();

create table public.reports (
  id           uuid primary key default gen_random_uuid(),
  reporter_id  uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  target_type  text not null check (target_type in ('post', 'comment', 'profile')),
  target_id    uuid not null,
  reason       public.report_reason not null,
  note         text check (char_length(note) <= 500),
  status       public.report_status not null default 'open',
  handled_by   uuid references public.profiles (id) on delete set null,
  handled_at   timestamptz,
  created_at   timestamptz not null default now()
);
create unique index reports_one_open_per_reporter on public.reports (reporter_id, target_type, target_id) where status = 'open';
create index reports_queue_idx on public.reports (status, created_at);

-- ── Helpers ────────────────────────────────────────────────────────────
create or replace function private.can_view_post(
  p_author uuid, p_visibility public.visibility, p_status public.content_status, p_deleted_at timestamptz
)
returns boolean
language plpgsql stable security definer
set search_path = ''
as $$
declare
  me uuid := (select auth.uid());
begin
  if private.is_staff() then return true; end if;
  -- Authors always see their own rows (the app filters out deleted ones). Postgres also
  -- requires an updated row to stay visible, which is what makes soft-delete work.
  if me is not null and me = p_author then return true; end if;
  if p_deleted_at is not null then return false; end if;
  if p_status <> 'published' then return false; end if;
  if me is not null and private.is_blocked_between(me, p_author) then return false; end if;
  if not private.can_view(p_author, 'profile') then return false; end if;
  return case p_visibility
           when 'public'  then true
           when 'friends' then private.are_friends(p_author, me)
           else false
         end;
end;
$$;

create or replace function private.post_is_visible(p_post_id uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select coalesce((select private.can_view_post(author_id, visibility, status, deleted_at)
                   from public.posts where id = p_post_id), false);
$$;

create or replace function private.is_post_author(p_post_id uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$ select exists (select 1 from public.posts where id = p_post_id and author_id = (select auth.uid())); $$;

grant execute on all functions in schema private to anon, authenticated, service_role;

-- ── Guards ─────────────────────────────────────────────────────────────
-- Authors edit words, rating and visibility, and can delete. Only staff moderate.
create or replace function private.posts_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select auth.uid()) is null or private.is_staff() then return new; end if;
  if new.author_id <> old.author_id
  or new.status is distinct from old.status
  or new.status_note is distinct from old.status_note
  or new.is_demo is distinct from old.is_demo
  or new.created_at is distinct from old.created_at
  or (old.deleted_at is not null and new.deleted_at is distinct from old.deleted_at) then
    raise exception 'that change is not allowed on a post' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger posts_guard before update on public.posts for each row execute function private.posts_guard();

create or replace function private.post_comments_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select auth.uid()) is null or private.is_staff() then return new; end if;
  if new.post_id <> old.post_id or new.author_id <> old.author_id
  or new.status is distinct from old.status or new.created_at is distinct from old.created_at
  or (old.deleted_at is not null and new.deleted_at is distinct from old.deleted_at) then
    raise exception 'that change is not allowed on a comment' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger post_comments_guard before update on public.post_comments for each row execute function private.post_comments_guard();

create or replace function private.post_media_limit()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select count(*) from public.post_media where post_id = new.post_id) >= 10 then
    raise exception 'a post can have at most 10 photos' using errcode = '23514';
  end if;
  return new;
end;
$$;
create trigger post_media_limit before insert on public.post_media for each row execute function private.post_media_limit();

-- ── RLS ────────────────────────────────────────────────────────────────
alter table public.posts          enable row level security;
alter table public.post_media     enable row level security;
alter table public.post_vybes     enable row level security;
alter table public.post_comments  enable row level security;
alter table public.reports        enable row level security;

create policy "posts: visible per author privacy and post visibility"
  on public.posts for select to anon, authenticated
  using (private.can_view_post(author_id, visibility, status, deleted_at));
create policy "posts: create your own"
  on public.posts for insert to authenticated
  with check (author_id = (select auth.uid()) and status = 'published' and not is_demo and deleted_at is null
              and (business_id is null or exists (select 1 from public.businesses b where b.id = business_id)));
create policy "posts: author edits, staff moderates"
  on public.posts for update to authenticated
  using (author_id = (select auth.uid()) or private.is_staff())
  with check (author_id = (select auth.uid()) or private.is_staff());

create policy "post_media: follows post visibility"
  on public.post_media for select to anon, authenticated
  using (private.post_is_visible(post_id));
create policy "post_media: author adds photos from own folder"
  on public.post_media for insert to authenticated
  with check (private.is_post_author(post_id)
              and split_part(storage_path, '/', 1) = (select auth.uid())::text);
create policy "post_media: author removes photos"
  on public.post_media for delete to authenticated
  using (private.is_post_author(post_id));

create policy "post_vybes: visible with the post"
  on public.post_vybes for select to anon, authenticated
  using (private.post_is_visible(post_id));
create policy "post_vybes: vybe a visible post"
  on public.post_vybes for insert to authenticated
  with check (user_id = (select auth.uid()) and private.post_is_visible(post_id));
create policy "post_vybes: remove your vybe"
  on public.post_vybes for delete to authenticated
  using (user_id = (select auth.uid()));

create policy "post_comments: visible with the post"
  on public.post_comments for select to anon, authenticated
  using (private.post_is_visible(post_id)
         and ((status = 'published' and deleted_at is null) or author_id = (select auth.uid()) or private.is_staff()));
create policy "post_comments: comment on a visible post"
  on public.post_comments for insert to authenticated
  with check (author_id = (select auth.uid()) and status = 'published' and deleted_at is null
              and private.post_is_visible(post_id)
              and not private.is_blocked_between((select auth.uid()), (select p.author_id from public.posts p where p.id = post_id)));
create policy "post_comments: author edits, staff moderates"
  on public.post_comments for update to authenticated
  using (author_id = (select auth.uid()) or private.is_staff())
  with check (author_id = (select auth.uid()) or private.is_staff());

create policy "reports: file a report"
  on public.reports for insert to authenticated
  with check (reporter_id = (select auth.uid()) and status = 'open' and handled_by is null and handled_at is null);
create policy "reports: reporter and staff read"
  on public.reports for select to authenticated
  using (reporter_id = (select auth.uid()) or private.is_staff());
create policy "reports: staff handle"
  on public.reports for update to authenticated
  using (private.is_staff()) with check (private.is_staff());

-- ── Staff moderation RPC (audited) ─────────────────────────────────────
create or replace function public.moderate_post(p_post_id uuid, p_status public.content_status, p_note text)
returns void
language plpgsql security definer
set search_path = ''
as $$
begin
  if not private.is_staff() then raise exception 'VYBR8 team only' using errcode = '42501'; end if;
  update public.posts set status = p_status, status_note = p_note where id = p_post_id;
  if not found then raise exception 'post not found' using errcode = 'P0002'; end if;
  update public.reports set status = 'actioned', handled_by = auth.uid(), handled_at = now()
   where target_type = 'post' and target_id = p_post_id and status = 'open' and p_status <> 'published';
  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'post.' || p_status, 'post', p_post_id, jsonb_build_object('note', p_note));
end;
$$;
revoke execute on function public.moderate_post(uuid, public.content_status, text) from public, anon;
grant execute on function public.moderate_post(uuid, public.content_status, text) to authenticated;

-- ── Feed view: counts without exposing who vybed ───────────────────────
-- security_invoker: the caller's RLS applies to every underlying table.
create view public.post_stats with (security_invoker = true) as
  select p.id as post_id,
         (select count(*) from public.post_vybes v where v.post_id = p.id)    as vybe_count,
         (select count(*) from public.post_comments c where c.post_id = p.id and c.deleted_at is null and c.status = 'published') as comment_count
  from public.posts p;

-- ── Photo storage ──────────────────────────────────────────────────────
-- Private bucket: photos are served through short-lived signed URLs, so
-- friends-only posts stay friends-only. Uploads go to "<user id>/<file>".
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('post-media', 'post-media', false, 10485760, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

create policy "post-media: upload to your own folder"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'post-media' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "post-media: read your own or visible posts' photos"
  on storage.objects for select to anon, authenticated
  using (bucket_id = 'post-media' and (
           (storage.foldername(name))[1] = (select auth.uid())::text
           or exists (select 1 from public.post_media m where m.storage_path = name and private.post_is_visible(m.post_id))
         ));
create policy "post-media: delete your own files"
  on storage.objects for delete to authenticated
  using (bucket_id = 'post-media' and (storage.foldername(name))[1] = (select auth.uid())::text);

-- ═════ 20260929000300_birthdays.sql ═════
-- VYBR8 · Birthdays: 21+ at sign-up, birthday alerts, and Birthday Perks
--
-- Birthdate is self-reported at sign-up. It is private to the user, set once,
-- and used for: the 21+ gate, birthday alerts, and showing which perks are usable now.

create type public.perk_type   as enum ('free_food', 'free_drink', 'discount', 'other');
create type public.perk_window as enum ('day', 'week', 'month');   -- on the day · birthday week (±3 days) · birthday month
create type public.perk_source as enum ('business', 'community', 'vybr8');
create type public.perk_status as enum ('pending', 'active', 'rejected', 'expired');

-- ── Birthdays (owner-only) ─────────────────────────────────────────────
create table public.user_birthdays (
  user_id     uuid primary key references public.profiles (id) on delete cascade,
  birthdate   date not null check (birthdate >= date '1900-01-01'),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create trigger user_birthdays_updated_at before update on public.user_birthdays
  for each row execute function private.set_updated_at();

-- Age in whole years on a given day.
create or replace function private.age_on(p_birthdate date, p_day date)
returns integer
language sql immutable
set search_path = ''
as $$ select extract(year from age(p_day, p_birthdate))::integer; $$;

-- Next birthday on or after p_from. Feb 29 birthdays are celebrated on Feb 28 in non-leap years.
create or replace function private.next_birthday(p_birthdate date, p_from date)
returns date
language plpgsql immutable
set search_path = ''
as $$
declare
  y integer := extract(year from p_from)::integer;
  m integer := extract(month from p_birthdate)::integer;
  d integer := extract(day from p_birthdate)::integer;
  candidate date;
begin
  for i in 0..1 loop
    if m = 2 and d = 29 and not ((y + i) % 4 = 0 and ((y + i) % 100 <> 0 or (y + i) % 400 = 0)) then
      candidate := make_date(y + i, 2, 28);
    else
      candidate := make_date(y + i, m, d);
    end if;
    if candidate >= p_from then return candidate; end if;
  end loop;
  return candidate;
end;
$$;

grant execute on all functions in schema private to anon, authenticated, service_role;

-- Must be 21+. Birthdate can be set once by the user; later changes go through the VYBR8 team.
create or replace function private.user_birthdays_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if private.age_on(new.birthdate, current_date) < 21 then
    raise exception 'VYBR8 is for adults 21 and over' using errcode = '23514';
  end if;
  if new.birthdate > current_date then
    raise exception 'birthdate cannot be in the future' using errcode = '23514';
  end if;
  if tg_op = 'UPDATE' and (select auth.uid()) is not null and not private.is_staff()
     and new.birthdate is distinct from old.birthdate then
    raise exception 'contact the VYBR8 team to change your birthday' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger user_birthdays_guard before insert or update on public.user_birthdays
  for each row execute function private.user_birthdays_guard();

alter table public.user_birthdays enable row level security;
create policy "user_birthdays: owner reads"
  on public.user_birthdays for select to authenticated using (user_id = (select auth.uid()));
create policy "user_birthdays: owner sets once"
  on public.user_birthdays for insert to authenticated with check (user_id = (select auth.uid()));
create policy "user_birthdays: owner or staff updates"
  on public.user_birthdays for update to authenticated
  using (user_id = (select auth.uid()) or private.is_staff())
  with check (user_id = (select auth.uid()) or private.is_staff());

-- ── Sign-up: now also records the birthday and enforces 21+ ────────────
-- Email sign-ups always send a birthdate (the form requires it). Sign-ups without one
-- (e.g. a future Google/Apple login) are sent to a "confirm your birthday" step before using the app.
create or replace function private.handle_new_user()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  wanted text := nullif(trim(new.raw_user_meta_data ->> 'username'), '');
  bday   date;
  uname  text;
begin
  begin
    bday := nullif(new.raw_user_meta_data ->> 'birthdate', '')::date;
  exception when others then
    raise exception 'invalid birthdate' using errcode = '22007';
  end;
  if bday is not null and private.age_on(bday, current_date) < 21 then
    raise exception 'VYBR8 is for adults 21 and over' using errcode = '23514';
  end if;

  if wanted is not null
     and wanted ~ '^[A-Za-z0-9_.]{3,30}$'
     and not exists (select 1 from public.profiles where username = wanted::extensions.citext) then
    uname := wanted;
  else
    uname := 'vyber_' || left(replace(new.id::text, '-', ''), 12);
  end if;

  insert into public.profiles (id, username, display_name, is_demo)
  values (
    new.id,
    uname,
    left(coalesce(nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''), uname), 60),
    coalesce((new.raw_user_meta_data ->> 'is_demo')::boolean, false)
  );
  insert into public.user_settings (user_id) values (new.id);
  insert into public.privacy_settings (user_id) values (new.id);
  if bday is not null then
    insert into public.user_birthdays (user_id, birthdate) values (new.id, bday);
  end if;
  return new;
end;
$$;

-- ── In-app notifications ───────────────────────────────────────────────
create table public.notifications (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references public.profiles (id) on delete cascade,
  kind        text not null check (kind ~ '^[a-z_.]{3,60}$'),
  title       text not null check (char_length(title) <= 120),
  body        text check (char_length(body) <= 500),
  link        text check (link ~ '^/'),
  dedupe_key  text,
  read_at     timestamptz,
  created_at  timestamptz not null default now()
);
create unique index notifications_dedupe on public.notifications (user_id, dedupe_key) where dedupe_key is not null;
create index notifications_inbox_idx on public.notifications (user_id, created_at desc);

create or replace function private.notifications_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select auth.uid()) is null then return new; end if;
  if new.user_id <> old.user_id or new.kind <> old.kind or new.title <> old.title
  or new.body is distinct from old.body or new.link is distinct from old.link
  or new.dedupe_key is distinct from old.dedupe_key or new.created_at <> old.created_at then
    raise exception 'only read status can change' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger notifications_guard before update on public.notifications
  for each row execute function private.notifications_guard();

alter table public.notifications enable row level security;
create policy "notifications: owner reads"   on public.notifications for select to authenticated using (user_id = (select auth.uid()));
create policy "notifications: owner marks read" on public.notifications for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "notifications: owner clears"  on public.notifications for delete to authenticated using (user_id = (select auth.uid()));
-- No insert policy: notifications are created by server jobs only.

-- ── Birthday Perks ─────────────────────────────────────────────────────
create table public.birthday_perks (
  id                 uuid primary key default gen_random_uuid(),
  business_id        uuid not null references public.businesses (id) on delete cascade,
  title              text not null check (char_length(title) between 3 and 120),     -- "Free dessert on your birthday"
  details            text check (char_length(details) <= 600),
  perk_type          public.perk_type not null,
  redeem_window      public.perk_window not null default 'day',
  requirements       text check (char_length(requirements) <= 300),                  -- "Show ID · dine-in only · rewards members"
  is_alcoholic       boolean not null default false,
  source             public.perk_source not null,
  status             public.perk_status not null default 'pending',
  submitted_by       uuid default auth.uid() references public.profiles (id) on delete set null,
  reviewed_by        uuid references public.profiles (id) on delete set null,
  last_confirmed_at  timestamptz,
  is_demo            boolean not null default false,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create index birthday_perks_active_idx on public.birthday_perks (status, perk_type) where status = 'active';
create index birthday_perks_business_idx on public.birthday_perks (business_id);
create trigger birthday_perks_updated_at before update on public.birthday_perks
  for each row execute function private.set_updated_at();

-- Community tips start pending and need VYBR8 review. Verified businesses publish their own perks directly.
create or replace function private.birthday_perks_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  editor boolean;
begin
  if (select auth.uid()) is null or private.is_staff() then return new; end if;
  editor := private.can_edit_business(new.business_id);
  if tg_op = 'INSERT' then
    new.submitted_by := (select auth.uid());
    if new.is_demo then raise exception 'only admins create demo records' using errcode = '42501'; end if;
    if editor then
      new.source := 'business';
      new.status := 'active';
      new.last_confirmed_at := now();
    else
      new.source := 'community';
      new.status := 'pending';
      new.last_confirmed_at := null;
    end if;
    new.reviewed_by := null;
    return new;
  end if;
  -- UPDATE by a business editor: content and status (e.g. expire it), not provenance.
  if new.business_id <> old.business_id or new.source <> old.source or new.is_demo <> old.is_demo
  or new.reviewed_by is distinct from old.reviewed_by or new.submitted_by is distinct from old.submitted_by
  or new.status not in ('active', 'expired') then
    raise exception 'that change is not allowed on a birthday perk' using errcode = '42501';
  end if;
  new.last_confirmed_at := now();
  return new;
end;
$$;
create trigger birthday_perks_guard before insert or update on public.birthday_perks
  for each row execute function private.birthday_perks_guard();

alter table public.birthday_perks enable row level security;
create policy "birthday_perks: active perks at visible places are public"
  on public.birthday_perks for select to anon, authenticated
  using ((status = 'active' and exists (select 1 from public.businesses b where b.id = business_id))
         or submitted_by = (select auth.uid())
         or private.can_edit_business(business_id)
         or private.is_staff());
create policy "birthday_perks: anyone signed in can suggest"
  on public.birthday_perks for insert to authenticated
  with check (exists (select 1 from public.businesses b where b.id = business_id));
create policy "birthday_perks: business editors and staff update"
  on public.birthday_perks for update to authenticated
  using (private.can_edit_business(business_id) or private.is_staff())
  with check (private.can_edit_business(business_id) or private.is_staff());
create policy "birthday_perks: business editors and staff delete"
  on public.birthday_perks for delete to authenticated
  using (private.can_edit_business(business_id) or private.is_staff());

create or replace function public.review_birthday_perk(p_perk_id uuid, p_approve boolean)
returns void
language plpgsql security definer
set search_path = ''
as $$
begin
  if not private.is_staff() then raise exception 'VYBR8 team only' using errcode = '42501'; end if;
  update public.birthday_perks
     set status = case when p_approve then 'active'::public.perk_status else 'rejected'::public.perk_status end,
         reviewed_by = auth.uid(),
         last_confirmed_at = case when p_approve then now() else last_confirmed_at end
   where id = p_perk_id and status = 'pending';
  if not found then raise exception 'no pending perk with that id' using errcode = 'P0002'; end if;
  insert into public.audit_logs (actor_id, action, entity_type, entity_id)
  values (auth.uid(), case when p_approve then 'birthday_perk.approved' else 'birthday_perk.rejected' end, 'birthday_perk', p_perk_id);
end;
$$;
revoke execute on function public.review_birthday_perk(uuid, boolean) from public, anon;
grant execute on function public.review_birthday_perk(uuid, boolean) to authenticated;

-- ── Daily birthday alerts ──────────────────────────────────────────────
-- Sends "birthday week is coming" 7 days out and "happy birthday" on the day.
-- Idempotent (dedupe keys), respects user_settings.notification_prefs->>'birthday' = 'false'.
create or replace function public.queue_birthday_notifications(p_today date default (now() at time zone 'America/New_York')::date)
returns integer
language plpgsql security definer
set search_path = ''
as $$
declare
  perks integer;
  n1 integer;
  n2 integer;
begin
  select count(*) into perks from public.birthday_perks p
    join public.businesses b on b.id = p.business_id
   where p.status = 'active' and b.status = 'active' and b.deleted_at is null;

  insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
  select ub.user_id, 'birthday.upcoming',
         'Your birthday is one week away',
         format('Plan it now: %s places near you have birthday perks, from free food to drinks and discounts.', perks),
         '/birthday',
         'birthday.upcoming.' || extract(year from p_today + 7)::text
    from public.user_birthdays ub
    join public.user_settings us on us.user_id = ub.user_id
   where private.next_birthday(ub.birthdate, p_today) = p_today + 7
     and coalesce(us.notification_prefs ->> 'birthday', 'true') <> 'false'
  on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;
  get diagnostics n1 = row_count;

  insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
  select ub.user_id, 'birthday.today',
         'Happy birthday from VYBR8!',
         format('Eat your vybe today. %s birthday perks are waiting for you.', perks),
         '/birthday',
         'birthday.today.' || extract(year from p_today)::text
    from public.user_birthdays ub
    join public.user_settings us on us.user_id = ub.user_id
   where private.next_birthday(ub.birthdate, p_today) = p_today
     and coalesce(us.notification_prefs ->> 'birthday', 'true') <> 'false'
  on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;
  get diagnostics n2 = row_count;

  return n1 + n2;
end;
$$;
revoke execute on function public.queue_birthday_notifications(date) from public, anon, authenticated;
grant execute on function public.queue_birthday_notifications(date) to service_role;

-- Run it every morning with pg_cron when available (it is on hosted Supabase).
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;
    perform cron.schedule('vybr8-birthday-alerts', '0 13 * * *', 'select public.queue_birthday_notifications()');
  else
    raise notice 'pg_cron not available: schedule public.queue_birthday_notifications() daily another way';
  end if;
end $$;

-- ═════ 20260929000400_age_rules.sql ═════
-- VYBR8 · Age rules v2
--
-- VYBR8 is open to everyone 13 and older (13 is the floor for social apps in the US, COPPA).
-- Alcohol is 21+:
--   • posting or viewing a Pour that contains alcohol
--   • Liquid Lover / Both creator verification
--   • viewing or suggesting drink (alcohol) birthday perks
-- Age comes from the private birthdate each user gives at sign-up.

-- ── Age helpers ────────────────────────────────────────────────────────
create or replace function private.user_is_21_plus(p_user uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select coalesce((select private.age_on(birthdate, current_date) >= 21
                   from public.user_birthdays where user_id = p_user), false);
$$;

create or replace function private.viewer_is_21_plus()
returns boolean
language sql stable security definer
set search_path = ''
as $$ select private.is_staff() or private.user_is_21_plus((select auth.uid())); $$;

grant execute on all functions in schema private to anon, authenticated, service_role;

-- ── Minimum age 13 (was 21) ────────────────────────────────────────────
create or replace function private.user_birthdays_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.birthdate > current_date then
    raise exception 'birthdate cannot be in the future' using errcode = '23514';
  end if;
  if private.age_on(new.birthdate, current_date) < 13 then
    raise exception 'VYBR8 is for people 13 and older' using errcode = '23514';
  end if;
  if tg_op = 'UPDATE' and (select auth.uid()) is not null and not private.is_staff()
     and new.birthdate is distinct from old.birthdate then
    raise exception 'contact the VYBR8 team to change your birthday' using errcode = '42501';
  end if;
  return new;
end;
$$;

create or replace function private.handle_new_user()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  wanted text := nullif(trim(new.raw_user_meta_data ->> 'username'), '');
  bday   date;
  uname  text;
begin
  begin
    bday := nullif(new.raw_user_meta_data ->> 'birthdate', '')::date;
  exception when others then
    raise exception 'invalid birthdate' using errcode = '22007';
  end;
  if bday is not null and private.age_on(bday, current_date) < 13 then
    raise exception 'VYBR8 is for people 13 and older' using errcode = '23514';
  end if;

  if wanted is not null
     and wanted ~ '^[A-Za-z0-9_.]{3,30}$'
     and not exists (select 1 from public.profiles where username = wanted::extensions.citext) then
    uname := wanted;
  else
    uname := 'vyber_' || left(replace(new.id::text, '-', ''), 12);
  end if;

  insert into public.profiles (id, username, display_name, is_demo)
  values (
    new.id,
    uname,
    left(coalesce(nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''), uname), 60),
    coalesce((new.raw_user_meta_data ->> 'is_demo')::boolean, false)
  );
  insert into public.user_settings (user_id) values (new.id);
  insert into public.privacy_settings (user_id) values (new.id);
  if bday is not null then
    insert into public.user_birthdays (user_id, birthdate) values (new.id, bday);
  end if;
  return new;
end;
$$;

-- ── Alcohol on posts ───────────────────────────────────────────────────
alter table public.posts add column is_alcoholic boolean not null default false;
alter table public.posts add constraint posts_alcohol_only_on_pours check (not is_alcoholic or kind = 'pour');
-- Existing drink posts were made when everyone was 21+; treat them as alcoholic to be safe.
update public.posts set is_alcoholic = true where kind = 'pour';

-- A post is visible only if the viewer may see alcohol when it contains alcohol.
create or replace function private.post_is_visible(p_post_id uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select coalesce((
    select private.can_view_post(author_id, visibility, status, deleted_at)
           and (not is_alcoholic or author_id = (select auth.uid()) or private.viewer_is_21_plus())
      from public.posts where id = p_post_id), false);
$$;

drop policy "posts: visible per author privacy and post visibility" on public.posts;
create policy "posts: visible per author privacy, post visibility and age"
  on public.posts for select to anon, authenticated
  using (private.can_view_post(author_id, visibility, status, deleted_at)
         and (not is_alcoholic or author_id = (select auth.uid()) or private.viewer_is_21_plus()));

drop policy "posts: create your own" on public.posts;
create policy "posts: create your own"
  on public.posts for insert to authenticated
  with check (author_id = (select auth.uid()) and status = 'published' and not is_demo and deleted_at is null
              and (not is_alcoholic or private.viewer_is_21_plus())
              and (business_id is null or exists (select 1 from public.businesses b where b.id = business_id)));

-- Under-21 authors can't flip an existing post to alcoholic.
create or replace function private.posts_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select auth.uid()) is null or private.is_staff() then return new; end if;
  if new.author_id <> old.author_id
  or new.status is distinct from old.status
  or new.status_note is distinct from old.status_note
  or new.is_demo is distinct from old.is_demo
  or new.created_at is distinct from old.created_at
  or (old.deleted_at is not null and new.deleted_at is distinct from old.deleted_at) then
    raise exception 'that change is not allowed on a post' using errcode = '42501';
  end if;
  if new.is_alcoholic and not old.is_alcoholic and not private.viewer_is_21_plus() then
    raise exception 'alcohol posts are 21+' using errcode = '42501';
  end if;
  return new;
end;
$$;

-- ── Liquid Lovers must actually be 21+ (not just say so) ───────────────
drop policy "creator_applications: apply for yourself" on public.creator_applications;
create policy "creator_applications: apply for yourself"
  on public.creator_applications for insert to authenticated
  with check (user_id = (select auth.uid()) and status = 'pending'
              and reviewed_by is null and reviewed_at is null and decision_note is null
              and not private.is_verified_creator(user_id)
              and (creator_type = 'big_back' or private.user_is_21_plus(user_id)));

create or replace function public.approve_creator_application(p_application_id uuid, p_note text default null)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  a public.creator_applications;
begin
  if not private.is_staff() then raise exception 'VYBR8 team only' using errcode = '42501'; end if;

  select * into a from public.creator_applications where id = p_application_id for update;
  if not found then raise exception 'application not found' using errcode = 'P0002'; end if;
  if a.status <> 'pending' then raise exception 'application is %', a.status using errcode = '22023'; end if;
  if a.creator_type <> 'big_back' and not private.user_is_21_plus(a.user_id) then
    raise exception 'Liquid Lovers must be 21 or older' using errcode = '23514';
  end if;

  update public.creator_applications
     set status = 'approved', decision_note = p_note, reviewed_by = auth.uid(), reviewed_at = now()
   where id = a.id;

  insert into public.creator_profiles (user_id, creator_type, status, application_id, verified_by, verified_at)
  values (a.user_id, a.creator_type, 'verified', a.id, auth.uid(), now())
  on conflict (user_id) do update
    set creator_type = excluded.creator_type, status = 'verified', application_id = excluded.application_id,
        verified_by = excluded.verified_by, verified_at = excluded.verified_at, status_note = null;

  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'creator.verified', 'profile', a.user_id,
          jsonb_build_object('application_id', a.id, 'creator_type', a.creator_type));
end;
$$;

-- ── Drink birthday perks are 21+ ───────────────────────────────────────
drop policy "birthday_perks: active perks at visible places are public" on public.birthday_perks;
create policy "birthday_perks: active perks at visible places are public"
  on public.birthday_perks for select to anon, authenticated
  using ((status = 'active' and exists (select 1 from public.businesses b where b.id = business_id)
          and (not is_alcoholic or private.viewer_is_21_plus()))
         or submitted_by = (select auth.uid())
         or private.can_edit_business(business_id)
         or private.is_staff());

drop policy "birthday_perks: anyone signed in can suggest" on public.birthday_perks;
create policy "birthday_perks: anyone signed in can suggest"
  on public.birthday_perks for insert to authenticated
  with check (exists (select 1 from public.businesses b where b.id = business_id)
              and (not is_alcoholic or private.viewer_is_21_plus()));

-- ═════ 20260930000100_cities_map.sql ═════
-- VYBR8 · Cities, venue hours, logos, and "what's your vybe" statuses for the Vybe Map

-- ── Launch cities ──────────────────────────────────────────────────────
create table public.cities (
  slug        text primary key check (slug ~ '^[a-z0-9-]{2,40}$'),
  name        text not null,
  region      text not null,
  timezone    text not null,
  center_lat  numeric(9,6) not null,
  center_lng  numeric(9,6) not null,
  -- Bounding box used to lay pins out on the Vybe Map.
  north       numeric(9,6) not null,
  south       numeric(9,6) not null,
  east        numeric(9,6) not null,
  west        numeric(9,6) not null,
  position    smallint not null default 100,
  is_active   boolean not null default true,
  check (north > south and east > west)
);

