  ('houston',   'Houston',        'TX', 'America/Chicago',      29.760400,  -95.369800, 29.950000,  29.580000,  -95.150000,  -95.650000, 4),
  ('phoenix',   'Phoenix',        'AZ', 'America/Phoenix',      33.448400, -112.074000, 33.650000,  33.300000, -111.900000, -112.300000, 5),
