alter table public.cities enable row level security;
create policy "cities: everyone reads" on public.cities for select to anon, authenticated using (true);

-- Locations belong to a launch city (text city/region stay for addresses).
alter table public.business_locations add column city_slug text references public.cities (slug);
create index business_locations_city_slug_idx on public.business_locations (city_slug);
update public.business_locations set city_slug = 'charlotte' where city = 'Charlotte' and region = 'NC';

-- Business logo (storage path or absolute https URL set by the business).
alter table public.businesses add column logo_url text check (logo_url is null or logo_url ~ '^(https://|/)');

-- The city a user is browsing.
alter table public.user_settings add column city_slug text references public.cities (slug);

-- ── Opening hours ──────────────────────────────────────────────────────
create table public.business_hours (
  id           uuid primary key default gen_random_uuid(),
  location_id  uuid not null references public.business_locations (id) on delete cascade,
  weekday      smallint not null check (weekday between 0 and 6),   -- 0 = Sunday
  opens_at     time not null,
  closes_at    time not null,                                       -- <= opens_at means past midnight
  created_at   timestamptz not null default now(),
  unique (location_id, weekday, opens_at)
);
create index business_hours_location_idx on public.business_hours (location_id);

alter table public.business_hours enable row level security;
create policy "business_hours: follow location visibility"
  on public.business_hours for select to anon, authenticated
  using (exists (select 1 from public.business_locations l where l.id = location_id));
create policy "business_hours: editors write"
  on public.business_hours for all to authenticated
  using (private.can_edit_business((select l.business_id from public.business_locations l where l.id = location_id)))
  with check (private.can_edit_business((select l.business_id from public.business_locations l where l.id = location_id)));

-- ── "What's your vybe?" status (friends only, expires) ─────────────────
create type public.vybe_intent as enum ('eat', 'drink', 'link_up');

create table public.vybe_statuses (
  user_id      uuid primary key references public.profiles (id) on delete cascade,
  intent       public.vybe_intent not null,
  city_slug    text not null references public.cities (slug),
  business_id  uuid references public.businesses (id) on delete set null,   -- optional "headed to"
  note         text check (char_length(note) <= 140),
  expires_at   timestamptz not null check (expires_at > created_at and expires_at <= created_at + interval '12 hours'),
  created_at   timestamptz not null default now()
);

alter table public.vybe_statuses enable row level security;
create policy "vybe_statuses: owner and friends read while active"
  on public.vybe_statuses for select to authenticated
  using (user_id = (select auth.uid())
         or (expires_at > now() and private.are_friends(user_id, (select auth.uid()))));
create policy "vybe_statuses: owner sets"
  on public.vybe_statuses for insert to authenticated
  with check (user_id = (select auth.uid()) and (business_id is null or exists (select 1 from public.businesses b where b.id = business_id)));
create policy "vybe_statuses: owner updates"
  on public.vybe_statuses for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "vybe_statuses: owner clears"
  on public.vybe_statuses for delete to authenticated
  using (user_id = (select auth.uid()));

-- ═════ 20260930000200_linkups.sql ═════
-- VYBR8 · Link Ups: meetups with up to 10 spots, guest invites for people without VYBR8,
-- and a group chat that disappears when the Link Up ends.

create type public.linkup_occasion   as enum ('girls_night', 'guys_night', 'dinner', 'drinks', 'brunch', 'happy_hour', 'birthday', 'date_night', 'game_night', 'meet_new_friends', 'other');
create type public.linkup_visibility as enum ('public', 'friends', 'invite_only');
create type public.linkup_join_mode  as enum ('open', 'request');
create type public.linkup_status     as enum ('active', 'cancelled');
create type public.member_status     as enum ('going', 'requested', 'invited', 'declined', 'left', 'removed');
create type public.invite_status     as enum ('pending', 'accepted', 'declined', 'revoked');

-- ── Tables ─────────────────────────────────────────────────────────────
create table public.linkups (
  id                   uuid primary key default gen_random_uuid(),
  host_id              uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  title                text not null check (char_length(trim(title)) between 3 and 80),
  occasion             public.linkup_occasion not null default 'other',
  description          text check (char_length(description) <= 1000),
  city_slug            text not null references public.cities (slug),
  business_id          uuid references public.businesses (id) on delete set null,
  meet_point           text check (char_length(meet_point) <= 120),     -- when not at a listed place
  starts_at            timestamptz not null,
  ends_at              timestamptz not null,
  capacity             smallint not null check (capacity between 2 and 10),  -- total spots, host included
  visibility           public.linkup_visibility not null default 'public',
  join_mode            public.linkup_join_mode not null default 'open',
  open_to_new_friends  boolean not null default false,
  is_alcoholic         boolean not null default false,                -- drinks involved: 21+
  status               public.linkup_status not null default 'active',
  is_demo              boolean not null default false,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  check (ends_at > starts_at and ends_at <= starts_at + interval '24 hours'),
  check (business_id is not null or meet_point is not null)
);
create index linkups_city_time_idx on public.linkups (city_slug, starts_at) where status = 'active';
create index linkups_host_idx on public.linkups (host_id);
create trigger linkups_updated_at before update on public.linkups for each row execute function private.set_updated_at();

create table public.linkup_members (
  linkup_id   uuid not null references public.linkups (id) on delete cascade,
  user_id     uuid not null references public.profiles (id) on delete cascade,
  status      public.member_status not null,
  is_host     boolean not null default false,
  invited_by  uuid references public.profiles (id) on delete set null,
  updated_at  timestamptz not null default now(),
  created_at  timestamptz not null default now(),
  primary key (linkup_id, user_id)
);
create index linkup_members_user_idx on public.linkup_members (user_id, status);

-- Guests: people without a VYBR8 account, invited by a private link.
create table public.linkup_invites (
  id             uuid primary key default gen_random_uuid(),
  linkup_id      uuid not null references public.linkups (id) on delete cascade,
  created_by     uuid not null references public.profiles (id) on delete cascade,
  token_hash     text not null unique,                 -- sha256 of the link token; the token itself is never stored
  label          text check (char_length(label) <= 60), -- "Aaliyah" (who the host meant it for)
  status         public.invite_status not null default 'pending',
  guest_name     text check (char_length(guest_name) between 1 and 40),
  guest_birthdate date,                                -- only kept to check age for the event
  accepted_at    timestamptz,
  created_at     timestamptz not null default now()
);
create index linkup_invites_linkup_idx on public.linkup_invites (linkup_id);

create table public.linkup_messages (
  id          uuid primary key default gen_random_uuid(),
  linkup_id   uuid not null references public.linkups (id) on delete cascade,
  user_id     uuid references public.profiles (id) on delete cascade,
  invite_id   uuid references public.linkup_invites (id) on delete cascade,
  body        text not null check (char_length(trim(body)) between 1 and 1000),
  created_at  timestamptz not null default now(),
  check ((user_id is null) <> (invite_id is null))
);
create index linkup_messages_linkup_idx on public.linkup_messages (linkup_id, created_at);

-- ── Helpers ────────────────────────────────────────────────────────────
create or replace function private.linkup_member_status(p_linkup uuid)
returns public.member_status
language sql stable security definer
set search_path = ''
as $$ select status from public.linkup_members where linkup_id = p_linkup and user_id = (select auth.uid()); $$;

create or replace function private.is_linkup_host(p_linkup uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$ select exists (select 1 from public.linkups where id = p_linkup and host_id = (select auth.uid())); $$;

create or replace function private.can_see_linkup(p_linkup uuid)
returns boolean
language plpgsql stable security definer
set search_path = ''
as $$
declare
  l public.linkups;
  me uuid := (select auth.uid());
  mine public.member_status;
begin
  select * into l from public.linkups where id = p_linkup;
  if not found then return false; end if;
  if private.is_staff() or l.host_id = me then return true; end if;
  mine := private.linkup_member_status(p_linkup);
  if mine in ('going', 'requested', 'invited') then return true; end if;
  if l.status <> 'active' or l.ends_at < now() then return false; end if;
  if l.is_alcoholic and not private.viewer_is_21_plus() then return false; end if;
  if me is not null and private.is_blocked_between(me, l.host_id) then return false; end if;
  return case l.visibility
           when 'public'  then true
           when 'friends' then private.are_friends(l.host_id, me)
           else false
         end;
end;
$$;

-- Spots taken = members going + guests who accepted.
create or replace function private.linkup_spots_taken(p_linkup uuid)
returns integer
language sql stable security definer
set search_path = ''
as $$
  select (select count(*) from public.linkup_members where linkup_id = p_linkup and status = 'going')::int
       + (select count(*) from public.linkup_invites where linkup_id = p_linkup and status = 'accepted')::int;
$$;

create or replace function private.can_chat(p_linkup uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.linkups l
    where l.id = p_linkup and l.status = 'active' and l.ends_at > now()
      and (l.host_id = (select auth.uid()) or private.linkup_member_status(p_linkup) = 'going')
  );
$$;

grant execute on all functions in schema private to anon, authenticated, service_role;

-- ── Guards ─────────────────────────────────────────────────────────────
create or replace function private.linkups_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    if (select auth.uid()) is not null and not private.is_staff() then
      if new.is_demo then raise exception 'only admins create demo records' using errcode = '42501'; end if;
      if new.starts_at < now() - interval '10 minutes' then raise exception 'a Link Up cannot start in the past' using errcode = '23514'; end if;
      if new.starts_at > now() + interval '90 days' then raise exception 'plan up to 90 days ahead' using errcode = '23514'; end if;
      if new.is_alcoholic and not private.viewer_is_21_plus() then raise exception 'drinks Link Ups are 21+' using errcode = '42501'; end if;
    end if;
    return new;
  end if;
  if (select auth.uid()) is null or private.is_staff() then return new; end if;
  if new.host_id <> old.host_id or new.is_demo <> old.is_demo or new.created_at <> old.created_at then
    raise exception 'that change is not allowed on a Link Up' using errcode = '42501';
  end if;
  if new.capacity < private.linkup_spots_taken(new.id) then
    raise exception 'more people are going than that' using errcode = '23514';
  end if;
  if new.is_alcoholic and not old.is_alcoholic and not private.viewer_is_21_plus() then
    raise exception 'drinks Link Ups are 21+' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger linkups_guard before insert or update on public.linkups for each row execute function private.linkups_guard();

-- The host is always the first member.
create or replace function private.linkups_add_host()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  insert into public.linkup_members (linkup_id, user_id, status, is_host) values (new.id, new.host_id, 'going', true);
  return new;
end;
$$;
create trigger linkups_add_host after insert on public.linkups for each row execute function private.linkups_add_host();

-- ── RLS ────────────────────────────────────────────────────────────────
alter table public.linkups          enable row level security;
alter table public.linkup_members   enable row level security;
alter table public.linkup_invites   enable row level security;
alter table public.linkup_messages  enable row level security;

create policy "linkups: visible per visibility, age and membership"
  on public.linkups for select to anon, authenticated
  using (private.can_see_linkup(id));
create policy "linkups: host creates"
  on public.linkups for insert to authenticated
  with check (host_id = (select auth.uid()) and status = 'active'
              and (business_id is null or exists (select 1 from public.businesses b where b.id = business_id)));
create policy "linkups: host edits"
  on public.linkups for update to authenticated
  using (host_id = (select auth.uid()) or private.is_staff())
  with check (host_id = (select auth.uid()) or private.is_staff());

-- Member lists: people in the Link Up see everyone; outsiders see only who is going.
create policy "linkup_members: visible with the Link Up"
  on public.linkup_members for select to authenticated
  using (private.can_see_linkup(linkup_id)
         and (status = 'going' or user_id = (select auth.uid()) or private.is_linkup_host(linkup_id)));
-- No direct writes: joining, leaving, approving and inviting go through the functions below.

create policy "linkup_invites: host reads"
  on public.linkup_invites for select to authenticated
  using (private.is_linkup_host(linkup_id) or private.is_staff());

create policy "linkup_messages: chat members read until it ends"
  on public.linkup_messages for select to authenticated
  using (private.can_chat(linkup_id));
create policy "linkup_messages: chat members post until it ends"
  on public.linkup_messages for insert to authenticated
  with check (user_id = (select auth.uid()) and invite_id is null and private.can_chat(linkup_id));

-- ── Member actions ─────────────────────────────────────────────────────
create or replace function public.join_linkup(p_linkup uuid)
returns public.member_status
language plpgsql security definer
set search_path = ''
as $$
declare
  me uuid := auth.uid();
  l public.linkups;
  current_status public.member_status;
  next_status public.member_status;
begin
  if me is null then raise exception 'sign in to join' using errcode = '42501'; end if;
  select * into l from public.linkups where id = p_linkup for update;
  if not found or not private.can_see_linkup(p_linkup) then raise exception 'Link Up not found' using errcode = 'P0002'; end if;
  if l.status <> 'active' or l.ends_at < now() then raise exception 'this Link Up is over' using errcode = '22023'; end if;
  if l.is_alcoholic and not private.viewer_is_21_plus() then raise exception 'drinks Link Ups are 21+' using errcode = '42501'; end if;
  select status into current_status from public.linkup_members where linkup_id = p_linkup and user_id = me;
  if current_status in ('going', 'requested') then return current_status; end if;
  if current_status = 'removed' then raise exception 'the host removed you from this Link Up' using errcode = '42501'; end if;

  -- Invited people and open Link Ups join straight away; others ask the host.
  next_status := case when current_status = 'invited' or l.join_mode = 'open' then 'going' else 'requested' end;
  if next_status = 'going' and private.linkup_spots_taken(p_linkup) >= l.capacity then
    raise exception 'this Link Up is full' using errcode = '23514';
  end if;

  insert into public.linkup_members (linkup_id, user_id, status)
  values (p_linkup, me, next_status)
  on conflict (linkup_id, user_id) do update set status = excluded.status, updated_at = now();

  insert into public.notifications (user_id, kind, title, body, link)
  select l.host_id,
         case when next_status = 'going' then 'linkup.joined' else 'linkup.requested' end,
         case when next_status = 'going' then 'Someone joined your Link Up' else 'New request for your Link Up' end,
         (select coalesce(display_name, username::text) from public.profiles where id = me) || ' · ' || l.title,
         '/vybe/' || l.id
  where l.host_id <> me;
  return next_status;
end;
$$;

create or replace function public.leave_linkup(p_linkup uuid)
returns void
language plpgsql security definer
set search_path = ''
as $$
begin
  if private.is_linkup_host(p_linkup) then raise exception 'hosts cancel the Link Up instead of leaving' using errcode = '22023'; end if;
  update public.linkup_members set status = case when status = 'invited' then 'declined'::public.member_status else 'left'::public.member_status end, updated_at = now()
   where linkup_id = p_linkup and user_id = auth.uid() and status in ('going', 'requested', 'invited');
end;
$$;

create or replace function public.respond_to_request(p_linkup uuid, p_user uuid, p_approve boolean)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  l public.linkups;
begin
  if not private.is_linkup_host(p_linkup) then raise exception 'host only' using errcode = '42501'; end if;
  select * into l from public.linkups where id = p_linkup for update;
  if p_approve and private.linkup_spots_taken(p_linkup) >= l.capacity then
    raise exception 'this Link Up is full' using errcode = '23514';
  end if;
  update public.linkup_members
     set status = case when p_approve then 'going'::public.member_status else 'declined'::public.member_status end, updated_at = now()
   where linkup_id = p_linkup and user_id = p_user and status = 'requested';
  if not found then raise exception 'no request from that person' using errcode = 'P0002'; end if;
  insert into public.notifications (user_id, kind, title, body, link)
  values (p_user, 'linkup.request_answered',
          case when p_approve then 'You''re in!' else 'Request not accepted' end,
          l.title, '/vybe/' || l.id);
end;
$$;

create or replace function public.remove_member(p_linkup uuid, p_user uuid)
returns void
language plpgsql security definer
set search_path = ''
as $$
begin
  if not private.is_linkup_host(p_linkup) then raise exception 'host only' using errcode = '42501'; end if;
  update public.linkup_members set status = 'removed', updated_at = now()
   where linkup_id = p_linkup and user_id = p_user and not is_host;
end;
$$;

-- Invite a VYBR8 member (friends only, to keep invites from being spammy).
create or replace function public.invite_to_linkup(p_linkup uuid, p_user uuid)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  l public.linkups;
  me uuid := auth.uid();
begin
  select * into l from public.linkups where id = p_linkup;
  if not found or not (l.host_id = me or private.linkup_member_status(p_linkup) = 'going') then
    raise exception 'only people in the Link Up can invite' using errcode = '42501';
  end if;
  if not private.are_friends(me, p_user) then raise exception 'you can invite friends on VYBR8, or send a guest link' using errcode = '42501'; end if;
  if l.is_alcoholic and not private.user_is_21_plus(p_user) then raise exception 'drinks Link Ups are 21+' using errcode = '42501'; end if;
  insert into public.linkup_members (linkup_id, user_id, status, invited_by)
  values (p_linkup, p_user, 'invited', me)
  on conflict (linkup_id, user_id) do update set status = 'invited', invited_by = me, updated_at = now()
    where public.linkup_members.status in ('declined', 'left');
  insert into public.notifications (user_id, kind, title, body, link)
  values (p_user, 'linkup.invited', 'You''re invited to a Link Up',
          (select coalesce(display_name, username::text) from public.profiles where id = me) || ' invited you: ' || l.title,
          '/vybe/' || l.id);
end;
$$;

-- ── Guest invites (no account needed) ──────────────────────────────────
-- Host creates a link. The plain token is returned once and never stored.
create or replace function public.create_guest_invite(p_linkup uuid, p_label text default null)
returns text
language plpgsql security definer
set search_path = ''
as $$
declare
  token text := encode(extensions.gen_random_bytes(24), 'hex');
begin
  if not private.is_linkup_host(p_linkup) then raise exception 'host only' using errcode = '42501'; end if;
  if (select count(*) from public.linkup_invites where linkup_id = p_linkup and status <> 'revoked') >= 20 then
    raise exception 'too many guest links for one Link Up' using errcode = '23514';
  end if;
  insert into public.linkup_invites (linkup_id, created_by, token_hash, label)
  values (p_linkup, auth.uid(), encode(sha256(convert_to(token, 'UTF8')), 'hex'), nullif(trim(p_label), ''));
  return token;
end;
$$;

create or replace function public.revoke_guest_invite(p_invite uuid)
returns void
language plpgsql security definer
set search_path = ''
as $$
begin
  update public.linkup_invites i set status = 'revoked'
   where i.id = p_invite and private.is_linkup_host(i.linkup_id);
  if not found then raise exception 'invite not found' using errcode = 'P0002'; end if;
end;
$$;

create or replace function private.invite_by_token(p_token text)
returns public.linkup_invites
language sql stable security definer
set search_path = ''
as $$
  select * from public.linkup_invites
  where token_hash = encode(sha256(convert_to(coalesce(p_token, ''), 'UTF8')), 'hex');
$$;

-- What a guest sees before and after accepting.
create or replace function public.guest_view_invite(p_token text)
returns jsonb
language plpgsql stable security definer
set search_path = ''
as $$
declare
  i public.linkup_invites := private.invite_by_token(p_token);
  l public.linkups;
begin
  if i.id is null or i.status = 'revoked' then return null; end if;
  select * into l from public.linkups where id = i.linkup_id;
  return jsonb_build_object(
    'invite_status', i.status,
    'guest_name', i.guest_name,
    'label', i.label,
    'title', l.title,
    'occasion', l.occasion,
    'description', l.description,
    'starts_at', l.starts_at,
    'ends_at', l.ends_at,
    'is_over', l.ends_at < now() or l.status <> 'active',
    'is_alcoholic', l.is_alcoholic,
    'capacity', l.capacity,
    'spots_taken', private.linkup_spots_taken(l.id),
    'city', (select name || ', ' || region from public.cities where slug = l.city_slug),
    'place', coalesce((select b.name from public.businesses b where b.id = l.business_id), l.meet_point),
    'address', (select concat_ws(', ', bl.address_line1, bl.city, bl.region) from public.business_locations bl
                where bl.business_id = l.business_id order by bl.is_primary desc limit 1),
    'host', (select coalesce(display_name, username::text) from public.profiles where id = l.host_id),
    'going', (select coalesce(jsonb_agg(coalesce(p.display_name, p.username::text)), '[]'::jsonb)
                from public.linkup_members m join public.profiles p on p.id = m.user_id
               where m.linkup_id = l.id and m.status = 'going')
             || (select coalesce(jsonb_agg(g.guest_name || ' (guest)'), '[]'::jsonb)
                   from public.linkup_invites g where g.linkup_id = l.id and g.status = 'accepted')
  );
end;
$$;

create or replace function public.guest_accept_invite(p_token text, p_name text, p_birthdate date)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  i public.linkup_invites := private.invite_by_token(p_token);
  l public.linkups;
begin
  if i.id is null or i.status = 'revoked' then raise exception 'this invite link is not valid' using errcode = 'P0002'; end if;
  if i.status = 'accepted' then return; end if;
  select * into l from public.linkups where id = i.linkup_id for update;
  if l.status <> 'active' or l.ends_at < now() then raise exception 'this Link Up is over' using errcode = '22023'; end if;
  if coalesce(trim(p_name), '') = '' then raise exception 'enter your name' using errcode = '22023'; end if;
  if p_birthdate is null or private.age_on(p_birthdate, current_date) < (case when l.is_alcoholic then 21 else 13 end) then
    raise exception '%', case when l.is_alcoholic then 'this Link Up is 21+' else 'VYBR8 is for people 13 and older' end using errcode = '23514';
  end if;
  if private.linkup_spots_taken(l.id) >= l.capacity then raise exception 'this Link Up is full' using errcode = '23514'; end if;
  update public.linkup_invites
     set status = 'accepted', guest_name = left(trim(p_name), 40), guest_birthdate = p_birthdate, accepted_at = now()
   where id = i.id;
  insert into public.notifications (user_id, kind, title, body, link)
  values (l.host_id, 'linkup.guest_accepted', 'A guest accepted your invite', left(trim(p_name), 40) || ' · ' || l.title, '/vybe/' || l.id);
end;
$$;

create or replace function public.guest_decline_invite(p_token text)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  i public.linkup_invites := private.invite_by_token(p_token);
begin
  if i.id is null or i.status = 'revoked' then raise exception 'this invite link is not valid' using errcode = 'P0002'; end if;
  update public.linkup_invites set status = 'declined' where id = i.id and status = 'pending';
end;
$$;

create or replace function public.guest_messages(p_token text)
returns table (id uuid, author text, is_guest boolean, is_me boolean, body text, created_at timestamptz)
language plpgsql stable security definer
set search_path = ''
as $$
declare
  i public.linkup_invites := private.invite_by_token(p_token);
begin
  if i.id is null or i.status <> 'accepted' then return; end if;
  if not exists (select 1 from public.linkups l where l.id = i.linkup_id and l.status = 'active' and l.ends_at > now()) then return; end if;
  return query
    select m.id,
           coalesce(p.display_name, p.username::text, g.guest_name),
           m.invite_id is not null,
           m.invite_id = i.id,
           m.body,
           m.created_at
      from public.linkup_messages m
      left join public.profiles p on p.id = m.user_id
      left join public.linkup_invites g on g.id = m.invite_id
     where m.linkup_id = i.linkup_id
     order by m.created_at
     limit 500;
end;
$$;

create or replace function public.guest_send_message(p_token text, p_body text)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  i public.linkup_invites := private.invite_by_token(p_token);
begin
  if i.id is null or i.status <> 'accepted' then raise exception 'accept the invite to chat' using errcode = '42501'; end if;
  if not exists (select 1 from public.linkups l where l.id = i.linkup_id and l.status = 'active' and l.ends_at > now()) then
    raise exception 'the chat has closed' using errcode = '22023';
  end if;
  insert into public.linkup_messages (linkup_id, invite_id, body) values (i.linkup_id, i.id, left(trim(p_body), 1000));
end;
$$;

-- Members' chat view with author names (guests included).
create or replace function public.linkup_chat(p_linkup uuid)
returns table (id uuid, author text, is_guest boolean, is_me boolean, body text, created_at timestamptz)
language sql stable security definer
set search_path = ''
as $$
  select m.id,
         coalesce(p.display_name, p.username::text, g.guest_name),
         m.invite_id is not null,
         m.user_id = (select auth.uid()),
         m.body,
         m.created_at
    from public.linkup_messages m
    left join public.profiles p on p.id = m.user_id
    left join public.linkup_invites g on g.id = m.invite_id
   where m.linkup_id = p_linkup and private.can_chat(p_linkup)
   order by m.created_at
   limit 500;
$$;

-- ── Chats disappear when the Link Up ends ──────────────────────────────
create or replace function public.purge_ended_linkup_chats()
returns integer
language plpgsql security definer
set search_path = ''
as $$
declare n integer;
begin
  delete from public.linkup_messages m using public.linkups l
   where l.id = m.linkup_id and (l.ends_at <= now() or l.status = 'cancelled');
  get diagnostics n = row_count;
  -- Guest birthdates are only needed while the invite is live.
  update public.linkup_invites i set guest_birthdate = null
    from public.linkups l where l.id = i.linkup_id and l.ends_at <= now() and i.guest_birthdate is not null;
  return n;
end;
$$;

-- Grants: guest functions are callable without an account; everything else needs sign-in.
revoke execute on function public.join_linkup(uuid), public.leave_linkup(uuid), public.respond_to_request(uuid, uuid, boolean),
  public.remove_member(uuid, uuid), public.invite_to_linkup(uuid, uuid), public.create_guest_invite(uuid, text),
  public.revoke_guest_invite(uuid), public.linkup_chat(uuid) from public, anon;
grant execute on function public.join_linkup(uuid), public.leave_linkup(uuid), public.respond_to_request(uuid, uuid, boolean),
  public.remove_member(uuid, uuid), public.invite_to_linkup(uuid, uuid), public.create_guest_invite(uuid, text),
  public.revoke_guest_invite(uuid), public.linkup_chat(uuid) to authenticated;
grant execute on function public.guest_view_invite(text), public.guest_accept_invite(text, text, date),
  public.guest_decline_invite(text), public.guest_messages(text), public.guest_send_message(text, text) to anon, authenticated;
revoke execute on function public.purge_ended_linkup_chats() from public, anon, authenticated;
grant execute on function public.purge_ended_linkup_chats() to service_role;

-- Live chat updates for members (Supabase Realtime respects RLS).
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table public.linkup_messages;
  end if;
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;
    perform cron.schedule('vybr8-purge-ended-chats', '*/10 * * * *', 'select public.purge_ended_linkup_chats()');
  end if;
end $$;

-- Spots taken for Link Ups the viewer can see (members + accepted guests).
create or replace function public.linkup_spots(p_ids uuid[])
returns table (linkup_id uuid, taken integer)
language sql stable security definer
set search_path = ''
as $$
  select l.id, private.linkup_spots_taken(l.id)
    from public.linkups l
   where l.id = any (p_ids) and private.can_see_linkup(l.id);
$$;
grant execute on function public.linkup_spots(uuid[]) to anon, authenticated;

-- ═════ 20260930000300_drink_kinds.sql ═════
-- VYBR8 · Non-alcohol drink spots (all ages): tea & matcha, juice & lemonade.
-- Coffee shops use the existing 'cafe' kind. Only alcohol content stays 21+.
alter type public.business_kind add value if not exists 'tea_shop';
alter type public.business_kind add value if not exists 'juice_bar';

-- ═════ 20260930000400_pour_early_access.sql ═════
-- VYBR8 · 21st-birthday early access to the Pours tab.
-- Starting 5 days before their 21st birthday, members can see alcohol posts, vybe them,
-- comment and post reviews, so they can plan where to go for their 21st.
-- Everything else about alcohol stays strictly 21+: Liquid Lover verification and drinks Link Ups.
-- Bars and lounges (the places themselves) are visible to everyone, like any map or search engine.

create or replace function private.user_has_pour_access(p_user uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select coalesce((select private.age_on(birthdate, current_date + 5) >= 21
                   from public.user_birthdays where user_id = p_user), false);
$$;

create or replace function private.viewer_has_pour_access()
returns boolean
language sql stable security definer
set search_path = ''
as $$ select private.is_staff() or private.user_has_pour_access((select auth.uid())); $$;

grant execute on function private.user_has_pour_access(uuid), private.viewer_has_pour_access() to anon, authenticated, service_role;

-- Seeing an alcohol post (and so its photos, vybes and comments, which follow the post).
create or replace function private.post_is_visible(p_post_id uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select coalesce((
    select private.can_view_post(author_id, visibility, status, deleted_at)
           and (not is_alcoholic or author_id = (select auth.uid()) or private.viewer_has_pour_access())
      from public.posts where id = p_post_id), false);
$$;

drop policy "posts: visible per author privacy, post visibility and age" on public.posts;
create policy "posts: visible per author privacy, post visibility and age"
  on public.posts for select to anon, authenticated
  using (private.can_view_post(author_id, visibility, status, deleted_at)
         and (not is_alcoholic or author_id = (select auth.uid()) or private.viewer_has_pour_access()));

-- Posting a pour review.
drop policy "posts: create your own" on public.posts;
create policy "posts: create your own"
  on public.posts for insert to authenticated
  with check (author_id = (select auth.uid()) and status = 'published' and not is_demo and deleted_at is null
              and (not is_alcoholic or private.viewer_has_pour_access())
              and (business_id is null or exists (select 1 from public.businesses b where b.id = business_id)));

create or replace function private.posts_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select auth.uid()) is null or private.is_staff() then return new; end if;
  if new.author_id <> old.author_id
  or new.status is distinct from old.status
  or new.status_note is distinct from old.status_note
  or new.is_demo is distinct from old.is_demo
  or new.created_at is distinct from old.created_at
  or (old.deleted_at is not null and new.deleted_at is distinct from old.deleted_at) then
    raise exception 'that change is not allowed on a post' using errcode = '42501';
  end if;
  if new.is_alcoholic and not old.is_alcoholic and not private.viewer_has_pour_access() then
    raise exception 'alcohol posts are 21+' using errcode = '42501';
  end if;
  return new;
end;
$$;

-- Drink birthday perks: visible early too, so people can plan their 21st.
drop policy "birthday_perks: active perks at visible places are public" on public.birthday_perks;
create policy "birthday_perks: active perks at visible places are public"
  on public.birthday_perks for select to anon, authenticated
  using ((status = 'active' and exists (select 1 from public.businesses b where b.id = business_id)
          and (not is_alcoholic or private.viewer_has_pour_access()))
         or submitted_by = (select auth.uid())
         or private.can_edit_business(business_id)
         or private.is_staff());

-- ═════ 20260930000500_linkup_21_on_event_day.sql ═════
-- VYBR8 · Drinks Link Ups: you must be 21 on the day of the event, not the day you RSVP.
-- Lets people plan their 21st birthday night ahead of time. Everything else about alcohol is unchanged.

-- The calendar day a Link Up starts, in its city's time zone.
create or replace function private.linkup_day(p_starts_at timestamptz, p_city text)
returns date
language sql stable security definer
set search_path = ''
as $$
  select (p_starts_at at time zone coalesce((select timezone from public.cities where slug = p_city), 'America/New_York'))::date;
$$;

create or replace function private.user_21_on(p_user uuid, p_day date)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select coalesce((select private.age_on(birthdate, p_day) >= 21 from public.user_birthdays where user_id = p_user), false);
$$;

create or replace function private.viewer_21_for_linkup(p_starts_at timestamptz, p_city text)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select private.is_staff() or private.user_21_on((select auth.uid()), private.linkup_day(p_starts_at, p_city));
$$;

grant execute on function private.linkup_day(timestamptz, text), private.user_21_on(uuid, date),
  private.viewer_21_for_linkup(timestamptz, text) to anon, authenticated, service_role;

create or replace function private.can_see_linkup(p_linkup uuid)
returns boolean
language plpgsql stable security definer
set search_path = ''
as $$
declare
  l public.linkups;
  me uuid := (select auth.uid());
  mine public.member_status;
begin
  select * into l from public.linkups where id = p_linkup;
  if not found then return false; end if;
  if private.is_staff() or l.host_id = me then return true; end if;
  mine := private.linkup_member_status(p_linkup);
  if mine in ('going', 'requested', 'invited') then return true; end if;
  if l.status <> 'active' or l.ends_at < now() then return false; end if;
  if l.is_alcoholic and not private.viewer_21_for_linkup(l.starts_at, l.city_slug) then return false; end if;
  if me is not null and private.is_blocked_between(me, l.host_id) then return false; end if;
  return case l.visibility
           when 'public'  then true
           when 'friends' then private.are_friends(l.host_id, me)
           else false
         end;
end;
$$;

create or replace function private.linkups_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    if (select auth.uid()) is not null and not private.is_staff() then
      if new.is_demo then raise exception 'only admins create demo records' using errcode = '42501'; end if;
      if new.starts_at < now() - interval '10 minutes' then raise exception 'a Link Up cannot start in the past' using errcode = '23514'; end if;
      if new.starts_at > now() + interval '90 days' then raise exception 'plan up to 90 days ahead' using errcode = '23514'; end if;
      if new.is_alcoholic and not private.viewer_21_for_linkup(new.starts_at, new.city_slug) then
        raise exception 'you can host a drinks Link Up that starts on or after your 21st birthday' using errcode = '42501';
      end if;
    end if;
    return new;
  end if;
  if (select auth.uid()) is null or private.is_staff() then return new; end if;
  if new.host_id <> old.host_id or new.is_demo <> old.is_demo or new.created_at <> old.created_at then
    raise exception 'that change is not allowed on a Link Up' using errcode = '42501';
  end if;
  if new.capacity < private.linkup_spots_taken(new.id) then
    raise exception 'more people are going than that' using errcode = '23514';
  end if;
  if new.is_alcoholic and (not old.is_alcoholic or new.starts_at <> old.starts_at or new.city_slug <> old.city_slug) then
    -- Everyone going must be 21 on the (new) event day.
    if exists (select 1 from public.linkup_members m where m.linkup_id = new.id and m.status in ('going', 'requested', 'invited')
                and not private.user_21_on(m.user_id, private.linkup_day(new.starts_at, new.city_slug)))
    or exists (select 1 from public.linkup_invites i where i.linkup_id = new.id and i.status = 'accepted'
                and private.age_on(i.guest_birthdate, private.linkup_day(new.starts_at, new.city_slug)) < 21) then
      raise exception 'everyone in a drinks Link Up must be 21 by the day it happens' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

create or replace function public.join_linkup(p_linkup uuid)
returns public.member_status
language plpgsql security definer
set search_path = ''
as $$
declare
  me uuid := auth.uid();
  l public.linkups;
  current_status public.member_status;
  next_status public.member_status;
begin
  if me is null then raise exception 'sign in to join' using errcode = '42501'; end if;
  select * into l from public.linkups where id = p_linkup for update;
  if not found or not private.can_see_linkup(p_linkup) then raise exception 'Link Up not found' using errcode = 'P0002'; end if;
  if l.status <> 'active' or l.ends_at < now() then raise exception 'this Link Up is over' using errcode = '22023'; end if;
  if l.is_alcoholic and not private.viewer_21_for_linkup(l.starts_at, l.city_slug) then raise exception 'drinks Link Ups are for people who are 21 by the day it happens' using errcode = '42501'; end if;
  select status into current_status from public.linkup_members where linkup_id = p_linkup and user_id = me;
  if current_status in ('going', 'requested') then return current_status; end if;
  if current_status = 'removed' then raise exception 'the host removed you from this Link Up' using errcode = '42501'; end if;

  -- Invited people and open Link Ups join straight away; others ask the host.
  next_status := case when current_status = 'invited' or l.join_mode = 'open' then 'going' else 'requested' end;
  if next_status = 'going' and private.linkup_spots_taken(p_linkup) >= l.capacity then
    raise exception 'this Link Up is full' using errcode = '23514';
  end if;

  insert into public.linkup_members (linkup_id, user_id, status)
  values (p_linkup, me, next_status)
  on conflict (linkup_id, user_id) do update set status = excluded.status, updated_at = now();

  insert into public.notifications (user_id, kind, title, body, link)
  select l.host_id,
         case when next_status = 'going' then 'linkup.joined' else 'linkup.requested' end,
         case when next_status = 'going' then 'Someone joined your Link Up' else 'New request for your Link Up' end,
         (select coalesce(display_name, username::text) from public.profiles where id = me) || ' · ' || l.title,
         '/vybe/' || l.id
  where l.host_id <> me;
  return next_status;
end;
$$;

create or replace function public.invite_to_linkup(p_linkup uuid, p_user uuid)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  l public.linkups;
  me uuid := auth.uid();
begin
  select * into l from public.linkups where id = p_linkup;
  if not found or not (l.host_id = me or private.linkup_member_status(p_linkup) = 'going') then
    raise exception 'only people in the Link Up can invite' using errcode = '42501';
  end if;
  if not private.are_friends(me, p_user) then raise exception 'you can invite friends on VYBR8, or send a guest link' using errcode = '42501'; end if;
  if l.is_alcoholic and not private.user_21_on(p_user, private.linkup_day(l.starts_at, l.city_slug)) then raise exception 'drinks Link Ups are for people who are 21 by the day it happens' using errcode = '42501'; end if;
  insert into public.linkup_members (linkup_id, user_id, status, invited_by)
  values (p_linkup, p_user, 'invited', me)
  on conflict (linkup_id, user_id) do update set status = 'invited', invited_by = me, updated_at = now()
    where public.linkup_members.status in ('declined', 'left');
  insert into public.notifications (user_id, kind, title, body, link)
  values (p_user, 'linkup.invited', 'You''re invited to a Link Up',
          (select coalesce(display_name, username::text) from public.profiles where id = me) || ' invited you: ' || l.title,
          '/vybe/' || l.id);
end;
$$;

create or replace function public.guest_accept_invite(p_token text, p_name text, p_birthdate date)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  i public.linkup_invites := private.invite_by_token(p_token);
  l public.linkups;
begin
  if i.id is null or i.status = 'revoked' then raise exception 'this invite link is not valid' using errcode = 'P0002'; end if;
  if i.status = 'accepted' then return; end if;
  select * into l from public.linkups where id = i.linkup_id for update;
  if l.status <> 'active' or l.ends_at < now() then raise exception 'this Link Up is over' using errcode = '22023'; end if;
  if coalesce(trim(p_name), '') = '' then raise exception 'enter your name' using errcode = '22023'; end if;
  if p_birthdate is null or (l.is_alcoholic and private.age_on(p_birthdate, private.linkup_day(l.starts_at, l.city_slug)) < 21)
     or private.age_on(p_birthdate, current_date) < 13 then
    raise exception '%', case when l.is_alcoholic then 'this Link Up is for people who are 21 by the day it happens' else 'VYBR8 is for people 13 and older' end using errcode = '23514';
  end if;
  if private.linkup_spots_taken(l.id) >= l.capacity then raise exception 'this Link Up is full' using errcode = '23514'; end if;
  update public.linkup_invites
     set status = 'accepted', guest_name = left(trim(p_name), 40), guest_birthdate = p_birthdate, accepted_at = now()
   where id = i.id;
  insert into public.notifications (user_id, kind, title, body, link)
  values (l.host_id, 'linkup.guest_accepted', 'A guest accepted your invite', left(trim(p_name), 40) || ' · ' || l.title, '/vybe/' || l.id);
end;
$$;

-- Hosts can always read their own Link Up (needed to read back a new row right after creating it).
drop policy "linkups: visible per visibility, age and membership" on public.linkups;
create policy "linkups: visible per visibility, age and membership"
  on public.linkups for select to anon, authenticated
  using (host_id = (select auth.uid()) or private.can_see_linkup(id));

-- ═════ 20261001000100_trust_safety.sql ═════
-- VYBR8 · Trust & safety
--  • Founder outranks the VYBR8 Team: the team can remove content; the founder can uphold or veto
--  • Creators prove their accounts (Instagram / TikTok / YouTube + a proof code in their bio)
--  • Profile photos (public avatars bucket); a photo is required to host or join a Link Up
--  • Public and meet-new-friends Link Ups are 18+ (they bring strangers together)
--  • Identity verification records (ID + selfie through a provider; VYBR8 never stores face data)

-- ── Founder ────────────────────────────────────────────────────────────
alter table public.team_members add column is_founder boolean not null default false;
create unique index team_members_one_founder on public.team_members (is_founder) where is_founder;

create or replace function private.is_founder()
returns boolean
language sql stable security definer
set search_path = ''
as $$ select exists (select 1 from public.team_members where user_id = (select auth.uid()) and is_founder); $$;

-- Only the founder (or the service role) can change who is on the team or who is founder.
create or replace function private.team_members_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select auth.uid()) is null or private.is_founder() then return coalesce(new, old); end if;
  if tg_op = 'UPDATE' and new.is_founder is not distinct from old.is_founder and new.user_id = (select auth.uid()) then
    return new;  -- team members may edit their own title/bio
  end if;
  raise exception 'only the founder manages the VYBR8 Team' using errcode = '42501';
end;
$$;
create trigger team_members_guard before insert or update or delete on public.team_members
  for each row execute function private.team_members_guard();

-- ── Age helper ─────────────────────────────────────────────────────────
create or replace function private.viewer_is_adult()
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select private.is_staff() or coalesce((select private.age_on(birthdate, current_date) >= 18
                                          from public.user_birthdays where user_id = (select auth.uid())), false);
$$;

-- ── Profile photos ─────────────────────────────────────────────────────
-- avatar_url holds a path in the public "avatars" bucket ("<user id>/<file>") or a bundled demo image.
update public.profiles set avatar_url = null where avatar_url is not null;
alter table public.profiles add constraint profiles_avatar_path check (
  avatar_url is null
  or (split_part(avatar_url, '/', 1) = id::text and avatar_url ~ '^[0-9a-f-]{36}/[A-Za-z0-9._-]{1,120}$')
  or avatar_url ~ '^/demo/avatars/[a-z0-9_-]{1,40}\.(svg|webp|png|jpg)$'
);

create or replace function private.has_profile_photo(p_user uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$ select coalesce((select avatar_url is not null from public.profiles where id = p_user), false); $$;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('avatars', 'avatars', true, 2097152, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

create policy "avatars: upload to your own folder"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "avatars: replace your own"
  on storage.objects for update to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "avatars: delete your own"
  on storage.objects for delete to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "avatars: public read"
  on storage.objects for select to anon, authenticated
  using (bucket_id = 'avatars');

-- ── Creator proof ──────────────────────────────────────────────────────
-- Applicants link at least one Instagram, TikTok or YouTube account and put their proof code in its bio
-- (or a recent post/caption) so the team can confirm they own it.
alter table public.creator_applications
  add column proof_code text not null default ('VYBR8-' || upper(substr(md5(gen_random_uuid()::text), 1, 6))),
  add column proof_confirmed_by uuid references public.profiles (id) on delete set null,
  add column proof_confirmed_at timestamptz;

create or replace function private.has_social_proof_link(p_links jsonb)
returns boolean
language sql immutable
set search_path = ''
as $$
  select exists (select 1 from jsonb_array_elements(coalesce(p_links, '[]'::jsonb)) l
                 where l->>'url' ~* '^https://(www\.|m\.)?(instagram\.com|tiktok\.com|youtube\.com|youtu\.be)/');
$$;

create or replace function private.creator_applications_proof_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' and (select auth.uid()) is not null and not private.is_staff() then
    if not private.has_social_proof_link(new.links) then
      raise exception 'link your Instagram, TikTok or YouTube so we can verify you' using errcode = '23514';
    end if;
    new.proof_confirmed_by := null; new.proof_confirmed_at := null;
  end if;
  return new;
end;
$$;
create trigger creator_applications_proof_guard before insert on public.creator_applications
  for each row execute function private.creator_applications_proof_guard();

-- Team confirms they saw the proof code on the applicant's account; approval requires it.
create or replace function public.confirm_creator_proof(p_application_id uuid)
returns void
language plpgsql security definer
set search_path = ''
as $$
begin
  if not private.is_staff() then raise exception 'VYBR8 team only' using errcode = '42501'; end if;
  update public.creator_applications set proof_confirmed_by = auth.uid(), proof_confirmed_at = now()
   where id = p_application_id and status = 'pending';
  if not found then raise exception 'application not found' using errcode = 'P0002'; end if;
  insert into public.audit_logs (actor_id, action, entity_type, entity_id) values (auth.uid(), 'creator.proof_confirmed', 'creator_application', p_application_id);
end;
$$;
revoke execute on function public.confirm_creator_proof(uuid) from public, anon;
grant execute on function public.confirm_creator_proof(uuid) to authenticated;

create or replace function private.creator_approval_needs_proof()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.status = 'approved' and old.status = 'pending' and new.proof_confirmed_at is null and not private.is_founder() then
    raise exception 'confirm the proof code on their Instagram, TikTok or YouTube first' using errcode = '23514';
  end if;
  return new;
end;
$$;
create trigger creator_approval_needs_proof before update on public.creator_applications
  for each row execute function private.creator_approval_needs_proof();

-- ── Moderation with founder override ───────────────────────────────────
create type public.moderation_target as enum ('post', 'comment', 'linkup', 'perk');
create type public.founder_decision  as enum ('upheld', 'vetoed');

create table public.moderation_actions (
  id               uuid primary key default gen_random_uuid(),
  target_type      public.moderation_target not null,
  target_id        uuid not null,
  reason           text not null check (char_length(trim(reason)) between 3 and 500),
  previous_status  text not null,
  taken_by         uuid references public.profiles (id) on delete set null,
  taken_at         timestamptz not null default now(),
  founder_decision public.founder_decision,
  founder_note     text check (char_length(founder_note) <= 500),
  decided_by       uuid references public.profiles (id) on delete set null,
  decided_at       timestamptz
);
create index moderation_actions_target_idx on public.moderation_actions (target_type, target_id, taken_at desc);
create index moderation_actions_open_idx on public.moderation_actions (taken_at desc) where founder_decision is null;
alter table public.moderation_actions enable row level security;
create policy "moderation_actions: team reads" on public.moderation_actions for select to authenticated using (private.is_staff());
-- No direct writes: use team_remove / founder_decide.

create or replace function private.moderation_status(p_type public.moderation_target, p_id uuid)
returns text
language sql stable security definer
set search_path = ''
as $$
  select case p_type
    when 'post'    then (select status::text from public.posts where id = p_id)
    when 'comment' then (select status::text from public.post_comments where id = p_id)
    when 'linkup'  then (select status::text from public.linkups where id = p_id)
    when 'perk'    then (select status::text from public.birthday_perks where id = p_id)
  end;
$$;

create or replace function private.set_moderation_status(p_type public.moderation_target, p_id uuid, p_status text)
returns void
language plpgsql security definer
set search_path = ''
as $$
begin
  case p_type
    when 'post'    then update public.posts set status = p_status::public.content_status where id = p_id;
    when 'comment' then update public.post_comments set status = p_status::public.content_status where id = p_id;
    when 'linkup'  then update public.linkups set status = p_status::public.linkup_status where id = p_id;
    when 'perk'    then update public.birthday_perks set status = p_status::public.perk_status where id = p_id;
  end case;
end;
$$;

-- Team (admins and moderators) remove content. If the founder already vetoed a removal of this
-- item, only the founder can remove it again: the founder's decision outranks the team.
create or replace function public.team_remove(p_type public.moderation_target, p_id uuid, p_reason text)
returns uuid
language plpgsql security definer
set search_path = ''
as $$
declare
  prev text := private.moderation_status(p_type, p_id);
  removed text := case p_type when 'linkup' then 'cancelled' when 'perk' then 'rejected' else 'removed' end;
  action_id uuid;
begin
  if not private.is_staff() then raise exception 'VYBR8 team only' using errcode = '42501'; end if;
  if prev is null then raise exception 'not found' using errcode = 'P0002'; end if;
  if prev = removed then raise exception 'already removed' using errcode = '22023'; end if;
  if not private.is_founder() and exists (
       select 1 from public.moderation_actions
        where target_type = p_type and target_id = p_id and founder_decision = 'vetoed') then
    raise exception 'the founder decided to keep this; ask the founder' using errcode = '42501';
  end if;
  perform private.set_moderation_status(p_type, p_id, removed);
  insert into public.moderation_actions (target_type, target_id, reason, previous_status, taken_by,
                                         founder_decision, decided_by, decided_at)
  values (p_type, p_id, trim(p_reason), prev, auth.uid(),
          case when private.is_founder() then 'upheld'::public.founder_decision end,
          case when private.is_founder() then auth.uid() end,
          case when private.is_founder() then now() end)
  returning id into action_id;
  update public.reports set status = 'actioned', handled_by = auth.uid(), handled_at = now()
   where target_type = p_type::text and target_id = p_id and status = 'open';
  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'moderation.remove', p_type::text, p_id, jsonb_build_object('reason', trim(p_reason), 'action_id', action_id));
  return action_id;
end;
$$;

-- Founder: uphold (double down) or veto (restore). Final.
create or replace function public.founder_decide(p_action uuid, p_decision public.founder_decision, p_note text default null)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  a public.moderation_actions;
begin
  if not private.is_founder() then raise exception 'founder only' using errcode = '42501'; end if;
  select * into a from public.moderation_actions where id = p_action for update;
  if not found then raise exception 'not found' using errcode = 'P0002'; end if;
  if p_decision = 'vetoed' then perform private.set_moderation_status(a.target_type, a.target_id, a.previous_status); end if;
  if p_decision = 'upheld' and a.founder_decision = 'vetoed' then
    perform private.set_moderation_status(a.target_type, a.target_id,
      case a.target_type when 'linkup' then 'cancelled' when 'perk' then 'rejected' else 'removed' end);
  end if;
  update public.moderation_actions
     set founder_decision = p_decision, founder_note = p_note, decided_by = auth.uid(), decided_at = now()
   where id = p_action;
  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'moderation.founder_' || p_decision, a.target_type::text, a.target_id, jsonb_build_object('action_id', p_action, 'note', p_note));
end;
$$;

revoke execute on function public.team_remove(public.moderation_target, uuid, text) from public, anon;
revoke execute on function public.founder_decide(uuid, public.founder_decision, text) from public, anon;
grant execute on function public.team_remove(public.moderation_target, uuid, text) to authenticated;
grant execute on function public.founder_decide(uuid, public.founder_decision, text) to authenticated;

-- ── Identity verification (ID + selfie through a provider) ─────────────
-- VYBR8 stores only the outcome. Face images and ID documents stay with the provider.
create type public.identity_status as enum ('unverified', 'pending', 'verified', 'failed', 'expired');
create table public.identity_verifications (
  user_id       uuid primary key references public.profiles (id) on delete cascade,
  provider      text not null check (char_length(provider) <= 40),
  provider_ref  text check (char_length(provider_ref) <= 200),
  status        public.identity_status not null default 'pending',
  verified_at   timestamptz,
  expires_at    timestamptz,
  updated_at    timestamptz not null default now()
);
alter table public.identity_verifications enable row level security;
create policy "identity_verifications: owner and team read"
  on public.identity_verifications for select to authenticated
  using (user_id = (select auth.uid()) or private.is_staff());
-- Written only by the provider webhook with the service role.

-- Public "ID verified" badge (no details).
create or replace function public.identity_verified(p_users uuid[])
returns table (user_id uuid)
language sql stable security definer
set search_path = ''
as $$
  select v.user_id from public.identity_verifications v
   where v.user_id = any (p_users) and v.status = 'verified' and (v.expires_at is null or v.expires_at > now());
$$;
grant execute on function public.identity_verified(uuid[]) to anon, authenticated;

grant execute on all functions in schema private to anon, authenticated, service_role;

-- ── Link Ups: photos, 18+ for public ones ──────────────────────────────
create or replace function private.can_see_linkup(p_linkup uuid)
returns boolean
language plpgsql stable security definer
set search_path = ''
as $$
declare
  l public.linkups;
  me uuid := (select auth.uid());
  mine public.member_status;
begin
  select * into l from public.linkups where id = p_linkup;
  if not found then return false; end if;
  if private.is_staff() or l.host_id = me then return true; end if;
  mine := private.linkup_member_status(p_linkup);
  if mine in ('going', 'requested', 'invited') then return true; end if;
  if l.status <> 'active' or l.ends_at < now() then return false; end if;
  if l.is_alcoholic and not private.viewer_21_for_linkup(l.starts_at, l.city_slug) then return false; end if;
  if me is not null and private.is_blocked_between(me, l.host_id) then return false; end if;
  -- Public and "meet new friends" Link Ups bring strangers together: 18+ only.
  if (l.visibility = 'public' or l.open_to_new_friends) and not private.viewer_is_adult() then return false; end if;
  return case l.visibility
           when 'public'  then true
           when 'friends' then private.are_friends(l.host_id, me)
           else false
         end;
end;
$$;

create or replace function private.linkups_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    if (select auth.uid()) is not null and not private.is_staff() then
      if new.is_demo then raise exception 'only admins create demo records' using errcode = '42501'; end if;
      if new.starts_at < now() - interval '10 minutes' then raise exception 'a Link Up cannot start in the past' using errcode = '23514'; end if;
      if new.starts_at > now() + interval '90 days' then raise exception 'plan up to 90 days ahead' using errcode = '23514'; end if;
      if not private.has_profile_photo((select auth.uid())) then
        raise exception 'add a profile photo before you host a Link Up' using errcode = '42501';
      end if;
      if (new.visibility = 'public' or new.open_to_new_friends) and not private.viewer_is_adult() then
        raise exception 'public and meet-new-friends Link Ups are for people 18 and older' using errcode = '42501';
      end if;
      if new.is_alcoholic and not private.viewer_21_for_linkup(new.starts_at, new.city_slug) then
        raise exception 'you can host a drinks Link Up that starts on or after your 21st birthday' using errcode = '42501';
      end if;
    end if;
    return new;
  end if;
  if (select auth.uid()) is null or private.is_staff() then return new; end if;
  if new.host_id <> old.host_id or new.is_demo <> old.is_demo or new.created_at <> old.created_at then
    raise exception 'that change is not allowed on a Link Up' using errcode = '42501';
  end if;
  if (new.visibility = 'public' or new.open_to_new_friends) and not (old.visibility = 'public' or old.open_to_new_friends)
     and not private.viewer_is_adult() then
    raise exception 'public and meet-new-friends Link Ups are for people 18 and older' using errcode = '42501';
  end if;
  if new.capacity < private.linkup_spots_taken(new.id) then
    raise exception 'more people are going than that' using errcode = '23514';
  end if;
  if new.is_alcoholic and (not old.is_alcoholic or new.starts_at <> old.starts_at or new.city_slug <> old.city_slug) then
    -- Everyone going must be 21 on the (new) event day.
    if exists (select 1 from public.linkup_members m where m.linkup_id = new.id and m.status in ('going', 'requested', 'invited')
                and not private.user_21_on(m.user_id, private.linkup_day(new.starts_at, new.city_slug)))
    or exists (select 1 from public.linkup_invites i where i.linkup_id = new.id and i.status = 'accepted'
                and private.age_on(i.guest_birthdate, private.linkup_day(new.starts_at, new.city_slug)) < 21) then
      raise exception 'everyone in a drinks Link Up must be 21 by the day it happens' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

create or replace function public.join_linkup(p_linkup uuid)
returns public.member_status
language plpgsql security definer
set search_path = ''
as $$
declare
  me uuid := auth.uid();
  l public.linkups;
  current_status public.member_status;
  next_status public.member_status;
begin
  if me is null then raise exception 'sign in to join' using errcode = '42501'; end if;
  select * into l from public.linkups where id = p_linkup for update;
  if not found or not private.can_see_linkup(p_linkup) then raise exception 'Link Up not found' using errcode = 'P0002'; end if;
  if l.status <> 'active' or l.ends_at < now() then raise exception 'this Link Up is over' using errcode = '22023'; end if;
  if not private.has_profile_photo(me) then raise exception 'add a profile photo so the group knows who is coming' using errcode = '42501'; end if;
  if (l.visibility = 'public' or l.open_to_new_friends) and not private.viewer_is_adult() then
    raise exception 'public and meet-new-friends Link Ups are for people 18 and older' using errcode = '42501';
  end if;
  if l.is_alcoholic and not private.viewer_21_for_linkup(l.starts_at, l.city_slug) then raise exception 'drinks Link Ups are for people who are 21 by the day it happens' using errcode = '42501'; end if;
  select status into current_status from public.linkup_members where linkup_id = p_linkup and user_id = me;
  if current_status in ('going', 'requested') then return current_status; end if;
  if current_status = 'removed' then raise exception 'the host removed you from this Link Up' using errcode = '42501'; end if;

  -- Invited people and open Link Ups join straight away; others ask the host.
  next_status := case when current_status = 'invited' or l.join_mode = 'open' then 'going' else 'requested' end;
  if next_status = 'going' and private.linkup_spots_taken(p_linkup) >= l.capacity then
    raise exception 'this Link Up is full' using errcode = '23514';
  end if;

  insert into public.linkup_members (linkup_id, user_id, status)
  values (p_linkup, me, next_status)
  on conflict (linkup_id, user_id) do update set status = excluded.status, updated_at = now();

  insert into public.notifications (user_id, kind, title, body, link)
  select l.host_id,
         case when next_status = 'going' then 'linkup.joined' else 'linkup.requested' end,
         case when next_status = 'going' then 'Someone joined your Link Up' else 'New request for your Link Up' end,
         (select coalesce(display_name, username::text) from public.profiles where id = me) || ' · ' || l.title,
         '/vybe/' || l.id
  where l.host_id <> me;
  return next_status;
end;
$$;

create or replace function public.guest_accept_invite(p_token text, p_name text, p_birthdate date)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  i public.linkup_invites := private.invite_by_token(p_token);
  l public.linkups;
begin
  if i.id is null or i.status = 'revoked' then raise exception 'this invite link is not valid' using errcode = 'P0002'; end if;
  if i.status = 'accepted' then return; end if;
  select * into l from public.linkups where id = i.linkup_id for update;
  if l.status <> 'active' or l.ends_at < now() then raise exception 'this Link Up is over' using errcode = '22023'; end if;
  if coalesce(trim(p_name), '') = '' then raise exception 'enter your name' using errcode = '22023'; end if;
  if p_birthdate is null or (l.is_alcoholic and private.age_on(p_birthdate, private.linkup_day(l.starts_at, l.city_slug)) < 21)
     or private.age_on(p_birthdate, current_date) < (case when l.visibility = 'public' or l.open_to_new_friends then 18 else 13 end) then
    raise exception '%', case when l.is_alcoholic then 'this Link Up is for people who are 21 by the day it happens' when l.visibility = 'public' or l.open_to_new_friends then 'this Link Up is for people 18 and older' else 'VYBR8 is for people 13 and older' end using errcode = '23514';
  end if;
  if private.linkup_spots_taken(l.id) >= l.capacity then raise exception 'this Link Up is full' using errcode = '23514'; end if;
  update public.linkup_invites
     set status = 'accepted', guest_name = left(trim(p_name), 40), guest_birthdate = p_birthdate, accepted_at = now()
   where id = i.id;
  insert into public.notifications (user_id, kind, title, body, link)
  values (l.host_id, 'linkup.guest_accepted', 'A guest accepted your invite', left(trim(p_name), 40) || ' · ' || l.title, '/vybe/' || l.id);
end;
$$;

-- ═════ 20261002000100_menus_intel.sql ═════
-- VYBR8 · Expansion 1/4 · Menus, item & place ratings, food intelligence (MAX-ready)
--
-- Menu items belong to any business (restaurants, bars, cafés, food trucks...). Their deeper
-- information (ingredients, preparation, recipe, nutrition) always carries its provenance and is
-- only read through public.item_deep_dive(), which checks the viewer's plan on the server.

-- ── Provenance levels ──────────────────────────────────────────────────
create type public.recipe_level as enum ('verified_recipe', 'verified_ingredients', 'preparation_info', 'vybr8_estimate', 'unknown');
create type public.nutrition_source as enum ('verified', 'restaurant_provided', 'database_provided', 'estimated', 'unknown');
create type public.item_category as enum ('food', 'drink');

-- ── Menu items ─────────────────────────────────────────────────────────
create table public.menu_items (
  id              uuid primary key default gen_random_uuid(),
  business_id     uuid not null references public.businesses (id) on delete cascade,
  name            text not null check (char_length(trim(name)) between 1 and 120),
  description     text check (char_length(description) <= 600),
  category        public.item_category not null default 'food',
  dish_type       text check (dish_type ~ '^[a-z0-9-]{2,40}$'),      -- chart bucket: wings, burger, birria-taco, margarita...
  section         text check (char_length(section) <= 60),           -- "Starters", "Cocktails"
  price_cents     integer check (price_cents between 0 and 1000000),
  is_alcoholic    boolean not null default false,
  is_available    boolean not null default true,
  sold_out_until  timestamptz,                                       -- food trucks: sold out for today
  position        smallint not null default 100,
  is_demo         boolean not null default false,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  check (category = 'drink' or not is_alcoholic)
);
create index menu_items_business_idx on public.menu_items (business_id, position);
create index menu_items_dish_type_idx on public.menu_items (dish_type) where dish_type is not null;
create index menu_items_name_idx on public.menu_items using gin (to_tsvector('simple', name));
create trigger menu_items_updated_at before update on public.menu_items for each row execute function private.set_updated_at();

alter table public.menu_items enable row level security;
create policy "menu_items: visible with the place (alcohol 21+)"
  on public.menu_items for select to anon, authenticated
  using (exists (select 1 from public.businesses b where b.id = business_id)
         and (not is_alcoholic or private.viewer_has_pour_access() or private.can_edit_business(business_id)));
create policy "menu_items: editors write"
  on public.menu_items for all to authenticated
  using (private.can_edit_business(business_id)) with check (private.can_edit_business(business_id) and not is_demo);

-- ── Ratings: individual items, and the place itself ────────────────────
create table public.item_ratings (
  id            uuid primary key default gen_random_uuid(),
  menu_item_id  uuid not null references public.menu_items (id) on delete cascade,
  user_id       uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  score         numeric(3,1) not null check (score between 0 and 10),
  note          text check (char_length(note) <= 500),
  status        public.content_status not null default 'published',
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (menu_item_id, user_id)
);
create index item_ratings_item_idx on public.item_ratings (menu_item_id) where status = 'published';
create trigger item_ratings_updated_at before update on public.item_ratings for each row execute function private.set_updated_at();

alter table public.item_ratings enable row level security;
create policy "item_ratings: visible with the item"
  on public.item_ratings for select to anon, authenticated
  using ((status = 'published' and exists (select 1 from public.menu_items m where m.id = menu_item_id))
         or user_id = (select auth.uid()) or private.is_staff());
-- Rating is free for everyone. Alcohol items follow the Pours rule.
create policy "item_ratings: rate a visible item"
  on public.item_ratings for insert to authenticated
  with check (user_id = (select auth.uid()) and status = 'published'
              and exists (select 1 from public.menu_items m where m.id = menu_item_id
                          and (not m.is_alcoholic or private.viewer_has_pour_access())));
create policy "item_ratings: change your own"
  on public.item_ratings for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()) and status = 'published');
create policy "item_ratings: delete your own"
  on public.item_ratings for delete to authenticated using (user_id = (select auth.uid()));

create table public.place_ratings (
  id            uuid primary key default gen_random_uuid(),
  business_id   uuid not null references public.businesses (id) on delete cascade,
  user_id       uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  overall       numeric(3,1) not null check (overall between 0 and 10),
  service_vybe  numeric(3,1) check (service_vybe between 0 and 10),
  value         numeric(3,1) check (value between 0 and 10),
  aesthetic     numeric(3,1) check (aesthetic between 0 and 10),
  note          text check (char_length(note) <= 1000),
  status        public.content_status not null default 'published',
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (business_id, user_id)
);
create index place_ratings_business_idx on public.place_ratings (business_id) where status = 'published';
create trigger place_ratings_updated_at before update on public.place_ratings for each row execute function private.set_updated_at();

alter table public.place_ratings enable row level security;
create policy "place_ratings: visible with the place"
  on public.place_ratings for select to anon, authenticated
  using ((status = 'published' and exists (select 1 from public.businesses b where b.id = business_id))
         or user_id = (select auth.uid()) or private.is_staff());
create policy "place_ratings: rate a place"
  on public.place_ratings for insert to authenticated
  with check (user_id = (select auth.uid()) and status = 'published'
              and exists (select 1 from public.businesses b where b.id = business_id)
              and not private.is_business_member(business_id));   -- no rating your own place
create policy "place_ratings: change your own"
  on public.place_ratings for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()) and status = 'published');
create policy "place_ratings: delete your own"
  on public.place_ratings for delete to authenticated using (user_id = (select auth.uid()));

-- Aggregates (respect the underlying RLS: invoker views).
create view public.menu_item_stats with (security_invoker = true) as
  select m.id as menu_item_id, m.business_id, m.dish_type, m.category,
         count(r.id)::int as rating_count, round(avg(r.score), 1) as avg_score
    from public.menu_items m
    left join public.item_ratings r on r.menu_item_id = m.id and r.status = 'published'
   group by m.id;

create view public.place_stats with (security_invoker = true) as
  select b.id as business_id, count(r.id)::int as rating_count,
         round(avg(r.overall), 1) as overall, round(avg(r.service_vybe), 1) as service_vybe,
         round(avg(r.value), 1) as value, round(avg(r.aesthetic), 1) as aesthetic
    from public.businesses b
    left join public.place_ratings r on r.business_id = b.id and r.status = 'published'
   group by b.id;

-- ── Food intelligence (MAX Deep Dive) ──────────────────────────────────
-- What the business/chef chose to disclose, and where each fact came from.
create table public.menu_item_intel (
  menu_item_id        uuid primary key references public.menu_items (id) on delete cascade,
  recipe_level        public.recipe_level not null default 'unknown',
  disclose_recipe     boolean not null default false,
  disclose_ingredients boolean not null default false,
  disclose_preparation boolean not null default false,
  disclose_allergens  boolean not null default false,
  disclose_nutrition  boolean not null default false,
  recipe_text         text check (char_length(recipe_text) <= 8000),
  preparation_steps   text[] check (coalesce(array_length(preparation_steps, 1), 0) <= 30),
  allergens           text[] check (coalesce(array_length(allergens, 1), 0) <= 20),
  kitchen_note        text check (char_length(kitchen_note) <= 600),     -- FROM THE KITCHEN
  source_note         text check (char_length(source_note) <= 300),      -- who supplied it
  estimate_text       text check (char_length(estimate_text) <= 2000),   -- VYBR8 ESTIMATE: labeled, never a claimed recipe
  updated_by          uuid references public.profiles (id) on delete set null,
  updated_at          timestamptz not null default now(),
  -- A "verified" level needs the matching disclosure.
  check (recipe_level <> 'verified_recipe' or (disclose_recipe and recipe_text is not null)),
  check (recipe_level <> 'verified_ingredients' or disclose_ingredients)
);

create table public.menu_item_ingredients (
  id            uuid primary key default gen_random_uuid(),
  menu_item_id  uuid not null references public.menu_items (id) on delete cascade,
  name          text not null check (char_length(trim(name)) between 1 and 80),
  detail        text check (char_length(detail) <= 120),
  position      smallint not null default 100,
  source        public.recipe_level not null default 'verified_ingredients'
);
create index menu_item_ingredients_item_idx on public.menu_item_ingredients (menu_item_id, position);

create table public.menu_item_nutrition (
  menu_item_id  uuid primary key references public.menu_items (id) on delete cascade,
  calories      integer check (calories between 0 and 10000),
  protein_g     numeric(6,1) check (protein_g >= 0),
  carbs_g       numeric(6,1) check (carbs_g >= 0),
  fat_g         numeric(6,1) check (fat_g >= 0),
  fiber_g       numeric(6,1) check (fiber_g >= 0),
  sodium_mg     integer check (sodium_mg >= 0),
  sugar_g       numeric(6,1) check (sugar_g >= 0),
  source        public.nutrition_source not null default 'unknown',
  source_note   text check (char_length(source_note) <= 200),
  updated_at    timestamptz not null default now()
);

alter table public.menu_item_intel enable row level security;
alter table public.menu_item_ingredients enable row level security;
alter table public.menu_item_nutrition enable row level security;
-- Direct reads only for the business's editors and the VYBR8 Team. Everyone else goes through item_deep_dive().
create policy "menu_item_intel: editors" on public.menu_item_intel for all to authenticated
  using (private.can_edit_business((select m.business_id from public.menu_items m where m.id = menu_item_id)) or private.is_staff())
  with check (private.can_edit_business((select m.business_id from public.menu_items m where m.id = menu_item_id)) or private.is_staff());
create policy "menu_item_ingredients: editors" on public.menu_item_ingredients for all to authenticated
  using (private.can_edit_business((select m.business_id from public.menu_items m where m.id = menu_item_id)) or private.is_staff())
  with check (private.can_edit_business((select m.business_id from public.menu_items m where m.id = menu_item_id)) or private.is_staff());
create policy "menu_item_nutrition: editors" on public.menu_item_nutrition for all to authenticated
  using (private.can_edit_business((select m.business_id from public.menu_items m where m.id = menu_item_id)) or private.is_staff())
  with check (private.can_edit_business((select m.business_id from public.menu_items m where m.id = menu_item_id)) or private.is_staff());

-- ── Personal nutrition (owner-only; wellness information, not medical advice) ──
create table public.nutrition_targets (
  user_id     uuid primary key references public.profiles (id) on delete cascade,
  goal        text check (goal in ('maintain', 'weight_management', 'muscle_gain', 'performance', 'custom')),
  calories    integer check (calories between 800 and 8000),
  protein_g   integer check (protein_g between 0 and 500),
  carbs_g     integer check (carbs_g between 0 and 1000),
  fat_g       integer check (fat_g between 0 and 400),
  fiber_g     integer check (fiber_g between 0 and 150),
  sodium_mg   integer check (sodium_mg between 0 and 10000),
  sugar_g     integer check (sugar_g between 0 and 500),
  updated_at  timestamptz not null default now()
);
create table public.food_logs (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  menu_item_id  uuid references public.menu_items (id) on delete set null,
  name          text not null check (char_length(trim(name)) between 1 and 120),
  portion       numeric(3,2) not null default 1 check (portion > 0 and portion <= 5),   -- 0.5 = split it
  calories      integer check (calories between 0 and 20000),
  protein_g     numeric(6,1), carbs_g numeric(6,1), fat_g numeric(6,1),
  sodium_mg     integer, sugar_g numeric(6,1), fiber_g numeric(6,1),
  nutrition_source public.nutrition_source not null default 'unknown',
  logged_at     timestamptz not null default now()
);
create index food_logs_user_day_idx on public.food_logs (user_id, logged_at desc);
alter table public.nutrition_targets enable row level security;
alter table public.food_logs enable row level security;
create policy "nutrition_targets: owner only" on public.nutrition_targets for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "food_logs: owner only" on public.food_logs for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- ═════ 20261002000200_plans_entitlements.sql ═════
-- VYBR8 · Expansion 2/4 · Plans and entitlements
--
-- One source of truth for "who can use what". The app asks the server (can_use / my_plan);
-- it never compares plan names in components. Payments (Stripe) will write subscriptions later;
-- until then the founder/admins can grant plans. Rating is always free.

create type public.plan_audience as enum ('consumer', 'business', 'chef');
create type public.subscription_status as enum ('active', 'trialing', 'past_due', 'canceled');
create type public.subscription_source as enum ('stripe', 'admin_grant', 'promo');

create table public.plans (
  code                text primary key check (code ~ '^[a-z0-9_]{2,40}$'),
  audience            public.plan_audience not null,
  name                text not null,
  tagline             text,
  price_monthly_cents integer check (price_monthly_cents >= 0),
  price_yearly_cents  integer check (price_yearly_cents >= 0),
  is_public           boolean not null default true,     -- Chef Pro stays hidden until pricing is approved
  rank                smallint not null default 0,       -- higher includes lower within an audience
  created_at          timestamptz not null default now()
);

create table public.plan_entitlements (
  plan_code    text not null references public.plans (code) on delete cascade,
  entitlement  text not null check (entitlement ~ '^[a-z0-9_]{2,60}$'),
  primary key (plan_code, entitlement)
);

alter table public.plans enable row level security;
alter table public.plan_entitlements enable row level security;
create policy "plans: public plans are public" on public.plans for select to anon, authenticated using (is_public or private.is_staff());
create policy "plan_entitlements: readable with the plan" on public.plan_entitlements for select to anon, authenticated
  using (exists (select 1 from public.plans p where p.code = plan_code and (p.is_public or private.is_staff())));

