-- ── Subscriptions ──────────────────────────────────────────────────────
create table public.user_subscriptions (
  id                   uuid primary key default gen_random_uuid(),
  user_id              uuid not null references public.profiles (id) on delete cascade,
  plan_code            text not null references public.plans (code),
  status               public.subscription_status not null default 'active',
  source               public.subscription_source not null,
  provider_ref         text,                 -- Stripe subscription id
  current_period_end   timestamptz,
  granted_by           uuid references public.profiles (id) on delete set null,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);
create index user_subscriptions_user_idx on public.user_subscriptions (user_id, status);

create table public.business_subscriptions (
  id                   uuid primary key default gen_random_uuid(),
  business_id          uuid not null references public.businesses (id) on delete cascade,
  plan_code            text not null references public.plans (code),
  status               public.subscription_status not null default 'active',
  source               public.subscription_source not null,
  provider_ref         text,
  current_period_end   timestamptz,
  granted_by           uuid references public.profiles (id) on delete set null,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);
create index business_subscriptions_business_idx on public.business_subscriptions (business_id, status);

alter table public.user_subscriptions enable row level security;
alter table public.business_subscriptions enable row level security;
create policy "user_subscriptions: owner and admins read" on public.user_subscriptions for select to authenticated
  using (user_id = (select auth.uid()) or private.is_admin());
create policy "business_subscriptions: business team and admins read" on public.business_subscriptions for select to authenticated
  using (private.is_business_member(business_id) or private.is_admin());
-- Writes: payment webhook (service role) or grant_plan() below.

-- ── Plan resolution ────────────────────────────────────────────────────
create or replace function private.user_plan(p_user uuid)
returns text
language sql stable security definer
set search_path = ''
as $$
  select coalesce((
    select s.plan_code from public.user_subscriptions s join public.plans p on p.code = s.plan_code
     where s.user_id = p_user and p.audience = 'consumer' and s.status in ('active', 'trialing')
       and (s.current_period_end is null or s.current_period_end > now())
     order by p.rank desc limit 1), 'free');
$$;

create or replace function private.user_can(p_user uuid, p_entitlement text)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (select 1 from public.plan_entitlements where plan_code = private.user_plan(p_user) and entitlement = p_entitlement);
$$;

-- The VYBR8 Team can use everything (to support members and test features).
create or replace function private.viewer_can(p_entitlement text)
returns boolean
language sql stable security definer
set search_path = ''
as $$ select private.is_staff() or ((select auth.uid()) is not null and private.user_can((select auth.uid()), p_entitlement)); $$;

create or replace function private.business_plan(p_business uuid)
returns text
language sql stable security definer
set search_path = ''
as $$
  select coalesce((
    select s.plan_code from public.business_subscriptions s join public.plans p on p.code = s.plan_code
     where s.business_id = p_business and p.audience = 'business' and s.status in ('active', 'trialing')
       and (s.current_period_end is null or s.current_period_end > now())
     order by p.rank desc limit 1), 'business_free');
$$;

create or replace function private.business_can(p_business uuid, p_entitlement text)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select private.is_admin() or (private.is_business_member(p_business)
    and exists (select 1 from public.plan_entitlements where plan_code = private.business_plan(p_business) and entitlement = p_entitlement));
$$;

grant execute on all functions in schema private to anon, authenticated, service_role;

-- What the app reads: the viewer's plan and entitlements.
create or replace function public.my_plan()
returns jsonb
language sql stable security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'plan', case when (select auth.uid()) is null then 'free' else private.user_plan((select auth.uid())) end,
    'entitlements', coalesce((select jsonb_agg(entitlement order by entitlement) from public.plan_entitlements
                               where plan_code = case when (select auth.uid()) is null then 'free' else private.user_plan((select auth.uid())) end), '[]'::jsonb),
    'staff', private.is_staff());
$$;
grant execute on function public.my_plan() to anon, authenticated;

create or replace function public.business_plan_info(p_business uuid)
returns jsonb
language plpgsql stable security definer
set search_path = ''
as $$
begin
  if not (private.is_business_member(p_business) or private.is_admin()) then raise exception 'not your business' using errcode = '42501'; end if;
  return jsonb_build_object('plan', private.business_plan(p_business),
    'entitlements', coalesce((select jsonb_agg(entitlement order by entitlement) from public.plan_entitlements
                               where plan_code = private.business_plan(p_business)), '[]'::jsonb));
end;
$$;
revoke execute on function public.business_plan_info(uuid) from public, anon;
grant execute on function public.business_plan_info(uuid) to authenticated;

-- Until payments are live: the founder/admins grant plans (comps, testers, early partners). Audited.
create or replace function public.grant_plan(p_user uuid, p_plan text, p_days integer default null)
returns void
language plpgsql security definer
set search_path = ''
as $$
begin
  if not private.is_admin() then raise exception 'admins only' using errcode = '42501'; end if;
  if not exists (select 1 from public.plans where code = p_plan and audience = 'consumer') then raise exception 'unknown plan' using errcode = '22023'; end if;
  update public.user_subscriptions set status = 'canceled', updated_at = now()
   where user_id = p_user and source = 'admin_grant' and status = 'active';
  if p_plan <> 'free' then
    insert into public.user_subscriptions (user_id, plan_code, source, current_period_end, granted_by)
    values (p_user, p_plan, 'admin_grant', case when p_days is null then null else now() + make_interval(days => p_days) end, auth.uid());
  end if;
  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'plan.granted', 'profile', p_user, jsonb_build_object('plan', p_plan, 'days', p_days));
end;
$$;
revoke execute on function public.grant_plan(uuid, text, integer) from public, anon;
grant execute on function public.grant_plan(uuid, text, integer) to authenticated;

-- ── Promotions (paid placement; never changes scores or organic rank) ──
create type public.promotion_placement as enum
  ('promoted_venue', 'promoted_dish', 'promoted_cocktail', 'promoted_food_truck', 'promoted_chef', 'promoted_catering', 'sponsored_special');
create type public.promotion_status as enum ('draft', 'pending_review', 'active', 'paused', 'ended', 'rejected');

create table public.promotion_campaigns (
  id            uuid primary key default gen_random_uuid(),
  business_id   uuid references public.businesses (id) on delete cascade,
  chef_id       uuid,                                   -- FK added with chef_profiles
  menu_item_id  uuid references public.menu_items (id) on delete set null,
  placement     public.promotion_placement not null,
  surface       text check (surface in ('near_you', 'food_trucks_today', 'lunch_near_you', 'this_weekend', 'trending_trucks', 'explore', 'chefs')),
  label         text not null default 'Promoted' check (label in ('Promoted', 'Sponsored')),   -- always shown
  headline      text check (char_length(headline) <= 80),
  city_slug     text references public.cities (slug),
  status        public.promotion_status not null default 'draft',
  starts_at     timestamptz,
  ends_at       timestamptz,
  created_by    uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at    timestamptz not null default now(),
  check (business_id is not null or chef_id is not null),
  check (ends_at is null or starts_at is null or ends_at > starts_at)
);
alter table public.promotion_campaigns enable row level security;
create policy "promotion_campaigns: active ones are public"
  on public.promotion_campaigns for select to anon, authenticated
  using ((status = 'active' and (starts_at is null or starts_at <= now()) and (ends_at is null or ends_at > now()))
         or (business_id is not null and private.is_business_member(business_id)) or private.is_staff());
-- Businesses draft campaigns (needs Growth); only the VYBR8 Team can activate one (after payment and review).
create policy "promotion_campaigns: businesses draft"
  on public.promotion_campaigns for insert to authenticated
  with check (business_id is not null and private.business_can(business_id, 'campaign_tools') and status in ('draft', 'pending_review'));
create policy "promotion_campaigns: businesses edit drafts, team manages"
  on public.promotion_campaigns for update to authenticated
  using ((business_id is not null and private.can_edit_business(business_id) and status in ('draft', 'pending_review')) or private.is_staff())
  with check ((business_id is not null and private.can_edit_business(business_id) and status in ('draft', 'pending_review', 'paused')) or private.is_staff());

-- ═════ 20261002000300_chefs.sql ═════
-- VYBR8 · Expansion 3/4 · Chefs (restaurant chefs, private chefs, caterers, meal prep, pop-ups, food-truck chefs)
--
-- A chef is a person with a professional profile, not a business. A chef profile can be linked to a
-- user (chefs can also be consumers, business owners or food-truck operators) or created by the
-- VYBR8 Team and claimed later. Workplaces and dish credits are never inferred: each one records
-- who said so (chef, business, VYBR8 Team or a trusted provider) and whether it's current.

create type public.chef_service as enum
  ('private_chef', 'catering', 'meal_prep', 'pop_ups', 'classes', 'consulting', 'events', 'restaurant_chef', 'food_truck');
create type public.chef_verification as enum ('unverified', 'pending', 'verified');
create type public.relationship_source as enum ('self_reported', 'business_confirmed', 'admin_verified', 'provider');
create type public.chef_attribution as enum ('creator', 'executive_chef', 'head_chef', 'featured_chef', 'collaborator');
create type public.chef_price_type as enum ('starting', 'per_person', 'hourly', 'package', 'custom_quote');

create table public.chef_profiles (
  id                  uuid primary key default gen_random_uuid(),
  user_id             uuid unique references public.profiles (id) on delete set null,   -- null = not claimed yet
  slug                extensions.citext not null unique check (slug::text ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) <= 80),
  professional_name   text not null check (char_length(trim(professional_name)) between 2 and 80),
  headline            text check (char_length(headline) <= 80),          -- "Executive Chef", "Private Chef & Caterer"
  bio                 text check (char_length(bio) <= 2000),
  photo_url           text check (photo_url is null or photo_url ~ '^(https://|/)'),
  cover_url           text check (cover_url is null or cover_url ~ '^(https://|/)'),
  city_slug           text references public.cities (slug),
  service_area        text check (char_length(service_area) <= 160),     -- "Charlotte + 30 miles, Rock Hill"
  years_experience    smallint check (years_experience between 0 and 70),
  culinary_background text check (char_length(culinary_background) <= 600),
  website             text check (website is null or website ~ '^https://'),
  booking_url         text check (booking_url is null or booking_url ~ '^https://'),
  contact_email       text check (contact_email is null or contact_email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  socials             jsonb not null default '[]'::jsonb check (jsonb_typeof(socials) = 'array' and jsonb_array_length(socials) <= 6),
  accepting_clients   boolean not null default false,
  available_events    boolean not null default false,
  available_catering  boolean not null default false,
  available_private_dining boolean not null default false,
  available_meal_prep boolean not null default false,
  restaurant_only     boolean not null default false,
  -- Pricing is always "from" / "estimate": the chef confirms a real quote.
  starting_price_cents   integer check (starting_price_cents >= 0),
  per_person_cents       integer check (per_person_cents >= 0),
  hourly_cents           integer check (hourly_cents >= 0),
  custom_quote           boolean not null default true,
  min_guests          smallint check (min_guests >= 1),
  max_guests          smallint check (max_guests >= 1),
  verification        public.chef_verification not null default 'unverified',
  is_listed           boolean not null default true,
  is_demo             boolean not null default false,
  created_by          uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create index chef_profiles_city_idx on public.chef_profiles (city_slug) where is_listed;
create trigger chef_profiles_updated_at before update on public.chef_profiles for each row execute function private.set_updated_at();

create or replace function private.can_edit_chef(p_chef uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$ select private.is_staff() or exists (select 1 from public.chef_profiles where id = p_chef and user_id = (select auth.uid())); $$;

-- Chefs can't verify themselves or change who owns the profile.
create or replace function private.chef_profiles_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select auth.uid()) is null or private.is_staff() then return new; end if;
  if tg_op = 'INSERT' then
    if new.user_id is distinct from (select auth.uid()) then raise exception 'create your own chef profile' using errcode = '42501'; end if;
    if new.verification <> 'unverified' or new.is_demo then raise exception 'not allowed' using errcode = '42501'; end if;
    return new;
  end if;
  if new.user_id is distinct from old.user_id or new.verification <> old.verification and new.verification <> 'pending'
     or new.is_demo <> old.is_demo or new.created_by is distinct from old.created_by then
    raise exception 'that change is made by the VYBR8 Team' using errcode = '42501';
  end if;
  if new.verification = 'pending' and old.verification = 'verified' then new.verification := 'verified'; end if;
  return new;
end;
$$;
create trigger chef_profiles_guard before insert or update on public.chef_profiles for each row execute function private.chef_profiles_guard();

create table public.chef_specialties (
  chef_id    uuid not null references public.chef_profiles (id) on delete cascade,
  cuisine    text not null check (char_length(trim(cuisine)) between 2 and 40),
  is_dietary boolean not null default false,        -- vegan, halal, gluten-free...
  primary key (chef_id, cuisine)
);
create table public.chef_services (
  chef_id  uuid not null references public.chef_profiles (id) on delete cascade,
  service  public.chef_service not null,
  primary key (chef_id, service)
);
create table public.chef_service_areas (
  chef_id    uuid not null references public.chef_profiles (id) on delete cascade,
  city_slug  text not null references public.cities (slug),
  primary key (chef_id, city_slug)
);

create table public.chef_business_relationships (
  id                  uuid primary key default gen_random_uuid(),
  chef_id             uuid not null references public.chef_profiles (id) on delete cascade,
  business_id         uuid not null references public.businesses (id) on delete cascade,
  role                text not null check (char_length(trim(role)) between 2 and 60),   -- Executive Chef, Sous Chef, Owner
  start_date          date,
  end_date            date,
  verification_status public.relationship_source not null default 'self_reported',
  created_by          uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at          timestamptz not null default now(),
  check (end_date is null or start_date is null or end_date >= start_date)
);
create index chef_business_relationships_chef_idx on public.chef_business_relationships (chef_id);
create index chef_business_relationships_business_idx on public.chef_business_relationships (business_id);

-- "Current" is computed, never stored: an end date in the past means former.
create or replace function public.chef_relationship_is_current(r public.chef_business_relationships)
returns boolean language sql stable set search_path = '' as $$ select r.end_date is null or r.end_date >= current_date; $$;

create table public.chef_menu_item_attributions (
  id                  uuid primary key default gen_random_uuid(),
  chef_id             uuid not null references public.chef_profiles (id) on delete cascade,
  menu_item_id        uuid not null references public.menu_items (id) on delete cascade,
  attribution_type    public.chef_attribution not null,
  verification_status public.relationship_source not null default 'self_reported',
  start_date          date,
  end_date            date,
  created_at          timestamptz not null default now(),
  unique (chef_id, menu_item_id, attribution_type)
);

create table public.chef_portfolio_items (
  id          uuid primary key default gen_random_uuid(),
  chef_id     uuid not null references public.chef_profiles (id) on delete cascade,
  image_url   text not null check (image_url ~ '^(https://|/)'),
  caption     text check (char_length(caption) <= 200),
  position    smallint not null default 100,
  created_at  timestamptz not null default now()
);

create table public.chef_service_packages (
  id           uuid primary key default gen_random_uuid(),
  chef_id      uuid not null references public.chef_profiles (id) on delete cascade,
  name         text not null check (char_length(trim(name)) between 2 and 80),
  description  text check (char_length(description) <= 600),
  price_type   public.chef_price_type not null,
  price_cents  integer check (price_cents >= 0),
  min_guests   smallint, max_guests smallint,
  position     smallint not null default 100,
  check (price_type = 'custom_quote' or price_cents is not null)
);

create table public.chef_availability (
  chef_id  uuid not null references public.chef_profiles (id) on delete cascade,
  day      date not null,
  status   text not null check (status in ('available', 'limited', 'booked')),
  note     text check (char_length(note) <= 120),
  primary key (chef_id, day)
);

create table public.chef_verifications (
  id           uuid primary key default gen_random_uuid(),
  chef_id      uuid not null references public.chef_profiles (id) on delete cascade,
  method       text not null check (method in ('business_confirmation', 'license_or_certificate', 'social_proof', 'in_person', 'provider')),
  evidence     text check (char_length(evidence) <= 1000),
  status       public.application_status not null default 'pending',
  reviewed_by  uuid references public.profiles (id) on delete set null,
  reviewed_at  timestamptz,
  created_at   timestamptz not null default now()
);

-- Chef-service reviews: separate from food ratings. Only for chef services (private dining, catering...).
create table public.chef_reviews (
  id                uuid primary key default gen_random_uuid(),
  chef_id           uuid not null references public.chef_profiles (id) on delete cascade,
  reviewer_id       uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  service           public.chef_service not null,
  food_quality      smallint not null check (food_quality between 1 and 10),
  professionalism   smallint check (professionalism between 1 and 10),
  communication     smallint check (communication between 1 and 10),
  presentation      smallint check (presentation between 1 and 10),
  timeliness        smallint check (timeliness between 1 and 10),
  value             smallint check (value between 1 and 10),
  would_book_again  boolean,
  body              text check (char_length(body) <= 1000),
  event_date        date,
  status            public.content_status not null default 'published',
  created_at        timestamptz not null default now(),
  unique (chef_id, reviewer_id, event_date),
  check (service <> 'restaurant_chef')   -- restaurant experiences are rated on the place and its dishes
);

alter table public.promotion_campaigns add constraint promotion_campaigns_chef_fk foreign key (chef_id) references public.chef_profiles (id) on delete cascade;

-- ── RLS ────────────────────────────────────────────────────────────────
alter table public.chef_profiles enable row level security;
alter table public.chef_specialties enable row level security;
alter table public.chef_services enable row level security;
alter table public.chef_service_areas enable row level security;
alter table public.chef_business_relationships enable row level security;
alter table public.chef_menu_item_attributions enable row level security;
alter table public.chef_portfolio_items enable row level security;
alter table public.chef_service_packages enable row level security;
alter table public.chef_availability enable row level security;
alter table public.chef_verifications enable row level security;
alter table public.chef_reviews enable row level security;

create policy "chef_profiles: listed profiles are public" on public.chef_profiles for select to anon, authenticated
  using (is_listed or user_id = (select auth.uid()) or private.is_staff());
create policy "chef_profiles: chefs create their own" on public.chef_profiles for insert to authenticated
  with check (user_id = (select auth.uid()) or private.is_staff());
create policy "chef_profiles: chef and team edit" on public.chef_profiles for update to authenticated
  using (private.can_edit_chef(id)) with check (private.can_edit_chef(id));
create policy "chef_profiles: team deletes" on public.chef_profiles for delete to authenticated using (private.is_staff());

-- Child tables: public read with a listed profile, chef/team write.
create policy "chef_specialties: read" on public.chef_specialties for select to anon, authenticated using (exists (select 1 from public.chef_profiles c where c.id = chef_id));
create policy "chef_specialties: write" on public.chef_specialties for all to authenticated using (private.can_edit_chef(chef_id)) with check (private.can_edit_chef(chef_id));
create policy "chef_services: read" on public.chef_services for select to anon, authenticated using (exists (select 1 from public.chef_profiles c where c.id = chef_id));
create policy "chef_services: write" on public.chef_services for all to authenticated using (private.can_edit_chef(chef_id)) with check (private.can_edit_chef(chef_id));
create policy "chef_service_areas: read" on public.chef_service_areas for select to anon, authenticated using (exists (select 1 from public.chef_profiles c where c.id = chef_id));
create policy "chef_service_areas: write" on public.chef_service_areas for all to authenticated using (private.can_edit_chef(chef_id)) with check (private.can_edit_chef(chef_id));
create policy "chef_portfolio_items: read" on public.chef_portfolio_items for select to anon, authenticated using (exists (select 1 from public.chef_profiles c where c.id = chef_id));
create policy "chef_portfolio_items: write" on public.chef_portfolio_items for all to authenticated using (private.can_edit_chef(chef_id)) with check (private.can_edit_chef(chef_id));
create policy "chef_service_packages: read" on public.chef_service_packages for select to anon, authenticated using (exists (select 1 from public.chef_profiles c where c.id = chef_id));
create policy "chef_service_packages: write" on public.chef_service_packages for all to authenticated using (private.can_edit_chef(chef_id)) with check (private.can_edit_chef(chef_id));
create policy "chef_availability: read" on public.chef_availability for select to anon, authenticated using (exists (select 1 from public.chef_profiles c where c.id = chef_id));
create policy "chef_availability: write" on public.chef_availability for all to authenticated using (private.can_edit_chef(chef_id)) with check (private.can_edit_chef(chef_id));

-- Workplaces: public. A chef may self-report (shown as "self-reported"); only the business or the team can confirm.
create policy "chef_business_relationships: read" on public.chef_business_relationships for select to anon, authenticated
  using (exists (select 1 from public.chef_profiles c where c.id = chef_id));
create policy "chef_business_relationships: chef self-reports, business or team confirms" on public.chef_business_relationships for insert to authenticated
  with check ((private.can_edit_chef(chef_id) and verification_status = 'self_reported')
              or (private.can_edit_business(business_id) and verification_status = 'business_confirmed')
              or private.is_staff());
create policy "chef_business_relationships: chef, business or team update" on public.chef_business_relationships for update to authenticated
  using (private.can_edit_chef(chef_id) or private.can_edit_business(business_id))
  with check (private.is_staff()
              or (private.can_edit_business(business_id) and verification_status in ('self_reported', 'business_confirmed'))
              or (private.can_edit_chef(chef_id) and verification_status = 'self_reported'));
create policy "chef_business_relationships: chef, business or team delete" on public.chef_business_relationships for delete to authenticated
  using (private.can_edit_chef(chef_id) or private.can_edit_business(business_id));

-- Dish credits: only the business (or the team) can credit a chef with a dish. Chefs can't claim dishes alone.
create policy "chef_menu_item_attributions: read" on public.chef_menu_item_attributions for select to anon, authenticated
  using (exists (select 1 from public.menu_items m where m.id = menu_item_id) and exists (select 1 from public.chef_profiles c where c.id = chef_id));
create policy "chef_menu_item_attributions: business or team credits" on public.chef_menu_item_attributions for all to authenticated
  using (private.is_staff() or private.can_edit_business((select m.business_id from public.menu_items m where m.id = menu_item_id)))
  with check ((private.is_staff() and verification_status in ('admin_verified', 'provider', 'business_confirmed'))
              or (private.can_edit_business((select m.business_id from public.menu_items m where m.id = menu_item_id)) and verification_status = 'business_confirmed'));

create policy "chef_verifications: chef and team read" on public.chef_verifications for select to authenticated using (private.can_edit_chef(chef_id));
create policy "chef_verifications: chef requests" on public.chef_verifications for insert to authenticated
  with check (private.can_edit_chef(chef_id) and status = 'pending' and reviewed_by is null);
create policy "chef_verifications: team reviews" on public.chef_verifications for update to authenticated using (private.is_staff()) with check (private.is_staff());

create policy "chef_reviews: published reviews are public" on public.chef_reviews for select to anon, authenticated
  using ((status = 'published' and exists (select 1 from public.chef_profiles c where c.id = chef_id)) or reviewer_id = (select auth.uid()) or private.is_staff());
create policy "chef_reviews: members review, not their own profile" on public.chef_reviews for insert to authenticated
  with check (reviewer_id = (select auth.uid()) and status = 'published'
              and not exists (select 1 from public.chef_profiles c where c.id = chef_id and c.user_id = (select auth.uid())));
create policy "chef_reviews: edit your own, team moderates" on public.chef_reviews for update to authenticated
  using (reviewer_id = (select auth.uid()) or private.is_staff())
  with check ((reviewer_id = (select auth.uid()) and status = 'published') or private.is_staff());
create policy "chef_reviews: delete your own" on public.chef_reviews for delete to authenticated using (reviewer_id = (select auth.uid()));

-- Reports can target chef reviews and place ratings too.
alter table public.reports drop constraint if exists reports_target_type_check;
alter table public.reports add constraint reports_target_type_check check (target_type in ('post', 'comment', 'profile', 'chef_review', 'place_rating', 'item_rating', 'chef_profile'));

-- Review summary. Chef rankings only show with enough reviews (see app: MIN_CHEF_REVIEWS).
create view public.chef_review_stats with (security_invoker = true) as
  select c.id as chef_id, count(r.id)::int as review_count,
         round(avg(r.food_quality), 1) as food_quality, round(avg(r.professionalism), 1) as professionalism,
         round(avg(r.communication), 1) as communication, round(avg(r.presentation), 1) as presentation,
         round(avg(r.timeliness), 1) as timeliness, round(avg(r.value), 1) as value,
         round(100.0 * avg(case when r.would_book_again then 1 when r.would_book_again = false then 0 end))::int as would_book_again_pct
    from public.chef_profiles c
    left join public.chef_reviews r on r.chef_id = c.id and r.status = 'published'
   group by c.id;

-- ── MAX Deep Dive: one server-side door to food intelligence ───────────
-- Returns only what the viewer's plan allows AND what the business chose to disclose, each with its source.
create or replace function public.item_deep_dive(p_item uuid)
returns jsonb
language plpgsql stable security definer
set search_path = ''
as $$
declare
  m public.menu_items;
  i public.menu_item_intel;
  n public.menu_item_nutrition;
  can_max boolean := private.viewer_can('deep_dive');
  can_plus boolean := private.viewer_can('advanced_nutrition');
  editor boolean;
  show_nutrition boolean;
  locked text[] := '{}';
begin
  select * into m from public.menu_items where id = p_item;
  if not found or not exists (select 1 from public.businesses b where b.id = m.business_id) then return null; end if;
  editor := coalesce(private.can_edit_business(m.business_id), false);
  if m.is_alcoholic and not (private.viewer_has_pour_access() or editor) then return null; end if;
  select * into i from public.menu_item_intel where menu_item_id = p_item;
  select * into n from public.menu_item_nutrition where menu_item_id = p_item;
  can_max := can_max or editor;
  can_plus := can_plus or can_max;

  -- Business-sourced nutrition needs their OK; VYBR8 estimates and database values are always labeled and shown.
  show_nutrition := n.menu_item_id is not null and (n.source in ('estimated', 'database_provided', 'unknown') or coalesce(i.disclose_nutrition, false));
  if not can_plus then locked := array_append(locked, 'detailed_nutrition'); end if;
  if not can_max then locked := locked || array['whats_in_it', 'how_its_made', 'from_the_kitchen', 'recipe', 'chef', 'vybe_check', 'better_swap']; end if;

  return jsonb_build_object(
    'item', jsonb_build_object('id', m.id, 'name', m.name, 'description', m.description, 'price_cents', m.price_cents,
                               'category', m.category, 'dish_type', m.dish_type, 'is_alcoholic', m.is_alcoholic,
                               'business', (select jsonb_build_object('id', b.id, 'slug', b.slug, 'name', b.name, 'kind', b.kind) from public.businesses b where b.id = m.business_id)),
    'score', (select jsonb_build_object('avg', s.avg_score, 'count', s.rating_count) from public.menu_item_stats s where s.menu_item_id = m.id),
    'recipe_level', coalesce(i.recipe_level, 'unknown'),
    'nutrition', case when not show_nutrition then null
                      when can_plus then jsonb_build_object('calories', n.calories, 'protein_g', n.protein_g, 'carbs_g', n.carbs_g, 'fat_g', n.fat_g,
                                                            'fiber_g', n.fiber_g, 'sodium_mg', n.sodium_mg, 'sugar_g', n.sugar_g, 'source', n.source, 'source_note', n.source_note)
                      else jsonb_build_object('calories', n.calories, 'source', n.source, 'source_note', n.source_note) end,
    'ingredients', case when can_max and coalesce(i.disclose_ingredients, false) then
                     (select coalesce(jsonb_agg(jsonb_build_object('name', g.name, 'detail', g.detail, 'source', g.source) order by g.position), '[]'::jsonb)
                        from public.menu_item_ingredients g where g.menu_item_id = m.id) end,
    'preparation', case when can_max and coalesce(i.disclose_preparation, false) then to_jsonb(i.preparation_steps) end,
    'recipe', case when can_max and i.recipe_level = 'verified_recipe' and i.disclose_recipe then i.recipe_text end,
    'allergens', case when coalesce(i.disclose_allergens, false) then to_jsonb(i.allergens) end,   -- allergens are safety info: free
    'kitchen_note', case when can_max then i.kitchen_note end,
    'estimate', case when can_max then i.estimate_text end,
    'source_note', i.source_note,
    'chefs', case when can_max then
               (select coalesce(jsonb_agg(jsonb_build_object('slug', c.slug, 'name', c.professional_name, 'type', a.attribution_type, 'source', a.verification_status)), '[]'::jsonb)
                  from public.chef_menu_item_attributions a join public.chef_profiles c on c.id = a.chef_id
                 where a.menu_item_id = m.id and c.is_listed and (a.end_date is null or a.end_date >= current_date)) end,
    'locked', to_jsonb(locked),
    'plan', case when can_max then 'max' when can_plus then 'plus' else 'free' end
  );
end;
$$;
grant execute on function public.item_deep_dive(uuid) to anon, authenticated;

-- Better Swap candidates: similar items nearby, with nutrition only where it's actually known.
create or replace function public.item_swaps(p_item uuid, p_limit integer default 6)
returns table (id uuid, name text, business_slug text, business_name text, price_cents integer, calories integer, nutrition_source public.nutrition_source, avg_score numeric, same_place boolean)
language plpgsql stable security definer
set search_path = ''
as $$
declare
  m public.menu_items;
  v_city text;
begin
  if not private.viewer_can('better_swap') then return; end if;
  select * into m from public.menu_items where menu_items.id = p_item;
  if not found then return; end if;
  select l.city_slug into v_city from public.business_locations l where l.business_id = m.business_id order by l.is_primary desc limit 1;
  return query
    select x.id, x.name, b.slug::text, b.name, x.price_cents,
           case when nn.source in ('verified', 'restaurant_provided') and not coalesce(ii.disclose_nutrition, false) then null else nn.calories end,
           coalesce(nn.source, 'unknown'::public.nutrition_source), s.avg_score, x.business_id = m.business_id
      from public.menu_items x
      join public.businesses b on b.id = x.business_id
      left join public.menu_item_nutrition nn on nn.menu_item_id = x.id
      left join public.menu_item_intel ii on ii.menu_item_id = x.id
      left join public.menu_item_stats s on s.menu_item_id = x.id
     where x.id <> m.id and x.category = m.category and x.is_available
       and (not x.is_alcoholic or private.viewer_has_pour_access())
       and (x.dish_type = m.dish_type or x.section = m.section and x.business_id = m.business_id
            or x.name ilike '%' || split_part(m.name, ' ', array_length(string_to_array(m.name, ' '), 1)) || '%')
       and (x.business_id = m.business_id or exists (select 1 from public.business_locations l where l.business_id = x.business_id and l.city_slug = v_city))
     order by (x.business_id = m.business_id) desc, s.avg_score desc nulls last
     limit least(p_limit, 12);
end;
$$;
grant execute on function public.item_swaps(uuid, integer) to authenticated;

grant execute on all functions in schema private to anon, authenticated, service_role;

-- ═════ 20261002000400_food_trucks.sql ═════
-- VYBR8 · Expansion 4/4 · Food trucks
--
-- A food truck is a business (kind 'food_truck') so it shares menus, item ratings, place ratings,
-- claims and dashboards. What's different: it moves. Every location has a time window and a source,
-- and a manually reported "WE'RE HERE" always expires.

create type public.truck_stop_status as enum ('scheduled', 'open', 'delayed', 'cancelled', 'sold_out', 'closed');
create type public.location_source as enum ('operator', 'vybr8_team', 'community', 'provider');

create table public.food_truck_profiles (
  business_id        uuid primary key references public.businesses (id) on delete cascade,
  cuisine            text check (char_length(cuisine) <= 60),
  truck_photo_url    text check (truck_photo_url is null or truck_photo_url ~ '^(https://|/)'),
  ordering_url       text check (ordering_url is null or ordering_url ~ '^https://'),
  socials            jsonb not null default '[]'::jsonb check (jsonb_typeof(socials) = 'array' and jsonb_array_length(socials) <= 6),
  catering_available boolean not null default false,
  home_city_slug     text references public.cities (slug),
  updated_at         timestamptz not null default now()
);

create table public.food_truck_schedules (
  id             uuid primary key default gen_random_uuid(),
  business_id    uuid not null references public.businesses (id) on delete cascade,
  location_name  text not null check (char_length(trim(location_name)) between 2 and 80),
  address        text check (char_length(address) <= 160),
  latitude       numeric(9,6) check (latitude between -90 and 90),
  longitude      numeric(9,6) check (longitude between -180 and 180),
  city_slug      text references public.cities (slug),
  start_at       timestamptz not null,
  end_at         timestamptz not null,
  event_name     text check (char_length(event_name) <= 80),     -- "Friday Night Market" (food_truck_events live here)
  status         public.truck_stop_status not null default 'scheduled',
  source         public.location_source not null default 'operator',
  verified_at    timestamptz,
  created_by     uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  check (end_at > start_at and end_at <= start_at + interval '18 hours')
);
create index food_truck_schedules_when_idx on public.food_truck_schedules (city_slug, start_at);
create index food_truck_schedules_truck_idx on public.food_truck_schedules (business_id, start_at);
create trigger food_truck_schedules_updated_at before update on public.food_truck_schedules for each row execute function private.set_updated_at();

-- "WE'RE HERE": a live pin set by a verified operator. Max 8 hours, then it disappears on its own.
create table public.food_truck_live_status (
  business_id  uuid primary key references public.businesses (id) on delete cascade,
  latitude     numeric(9,6) not null check (latitude between -90 and 90),
  longitude    numeric(9,6) not null check (longitude between -180 and 180),
  city_slug    text references public.cities (slug),
  note         text check (char_length(note) <= 120),
  started_at   timestamptz not null default now(),
  expires_at   timestamptz not null,
  set_by       uuid default auth.uid() references public.profiles (id) on delete set null,
  check (expires_at > started_at and expires_at <= started_at + interval '8 hours')
);

create table public.food_truck_follows (
  user_id      uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  business_id  uuid not null references public.businesses (id) on delete cascade,
  notify       boolean not null default true,     -- "Notify me" when a new stop is posted
  created_at   timestamptz not null default now(),
  primary key (user_id, business_id)
);

-- Only trucks get truck features.
create or replace function private.is_food_truck(p_business uuid)
returns boolean language sql stable security definer set search_path = ''
as $$ select exists (select 1 from public.businesses where id = p_business and kind = 'food_truck'); $$;

alter table public.food_truck_profiles enable row level security;
alter table public.food_truck_schedules enable row level security;
alter table public.food_truck_live_status enable row level security;
alter table public.food_truck_follows enable row level security;

create policy "food_truck_profiles: public" on public.food_truck_profiles for select to anon, authenticated
  using (exists (select 1 from public.businesses b where b.id = business_id));
create policy "food_truck_profiles: operators write" on public.food_truck_profiles for all to authenticated
  using (private.can_edit_business(business_id)) with check (private.can_edit_business(business_id) and private.is_food_truck(business_id));

create policy "food_truck_schedules: public" on public.food_truck_schedules for select to anon, authenticated
  using (exists (select 1 from public.businesses b where b.id = business_id));
create policy "food_truck_schedules: operators write" on public.food_truck_schedules for all to authenticated
  using (private.can_edit_business(business_id) or private.is_staff())
  with check ((private.can_edit_business(business_id) and source = 'operator' or private.is_staff()) and private.is_food_truck(business_id));

create policy "food_truck_live_status: public while live" on public.food_truck_live_status for select to anon, authenticated
  using (expires_at > now() and exists (select 1 from public.businesses b where b.id = business_id));
create policy "food_truck_live_status: operators set" on public.food_truck_live_status for all to authenticated
  using (private.can_edit_business(business_id))
  with check (private.can_edit_business(business_id) and private.is_food_truck(business_id));

create policy "food_truck_follows: own" on public.food_truck_follows for select to authenticated using (user_id = (select auth.uid()));
create policy "food_truck_follows: follow" on public.food_truck_follows for insert to authenticated
  with check (user_id = (select auth.uid()) and private.is_food_truck(business_id));
create policy "food_truck_follows: change" on public.food_truck_follows for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "food_truck_follows: unfollow" on public.food_truck_follows for delete to authenticated using (user_id = (select auth.uid()));

-- Follower counts for operators and profile pages (numbers only, never who).
create or replace function public.food_truck_follower_count(p_business uuid)
returns integer language sql stable security definer set search_path = ''
as $$ select count(*)::int from public.food_truck_follows where business_id = p_business; $$;
grant execute on function public.food_truck_follower_count(uuid) to anon, authenticated;

-- food_truck_notifications: a new or re-opened stop notifies followers who asked (in-app alerts).
create or replace function private.food_truck_notify_followers()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  truck text;
begin
  if new.status in ('cancelled', 'closed') or new.end_at < now() then return new; end if;
  if tg_op = 'UPDATE' and old.status = new.status and old.start_at = new.start_at and old.location_name = new.location_name then return new; end if;
  select name into truck from public.businesses where id = new.business_id;
  insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
  select f.user_id, 'truck.stop',
         case when new.status = 'open' then truck || ' is open' when new.status = 'delayed' then truck || ' is running late' else truck || ' posted a stop' end,
         new.location_name || coalesce(' · ' || new.event_name, ''),
         '/food-trucks/' || (select slug from public.businesses where id = new.business_id),
         'truck.stop:' || new.id || ':' || new.status
    from public.food_truck_follows f
   where f.business_id = new.business_id and f.notify
  on conflict do nothing;
  return new;
end;
$$;
create trigger food_truck_schedules_notify after insert or update on public.food_truck_schedules
  for each row execute function private.food_truck_notify_followers();

-- What's where, right now or soon, in a city. A scheduled future stop is never shown as "here now".
create or replace function public.food_trucks_in_city(p_city text, p_from timestamptz default now(), p_to timestamptz default now() + interval '7 days')
returns table (business_id uuid, slug text, name text, cuisine text, stop_id uuid, location_name text, address text, event_name text,
               latitude numeric, longitude numeric, start_at timestamptz, end_at timestamptz, status public.truck_stop_status,
               is_live boolean, live_note text, live_until timestamptz)
language sql stable security definer
set search_path = ''
as $$
  with live as (
    select * from public.food_truck_live_status where expires_at > now() and (city_slug = p_city or city_slug is null)
  )
  select b.id, b.slug::text, b.name, p.cuisine, s.id, s.location_name, s.address, s.event_name,
         coalesce(lv.latitude, s.latitude), coalesce(lv.longitude, s.longitude), s.start_at, s.end_at, s.status,
         lv.business_id is not null and (s.id is null or (s.start_at <= now() and s.end_at > now())), lv.note, lv.expires_at
    from public.businesses b
    left join public.food_truck_profiles p on p.business_id = b.id
    left join live lv on lv.business_id = b.id
    left join lateral (
      select * from public.food_truck_schedules x
       where x.business_id = b.id and x.end_at > p_from and x.start_at < p_to and x.status <> 'cancelled'
         and (x.city_slug = p_city or x.city_slug is null)
       order by x.start_at limit 1) s on true
   where b.kind = 'food_truck' and b.status = 'active' and b.deleted_at is null
     and (s.id is not null or lv.business_id is not null or p.home_city_slug = p_city);
$$;
grant execute on function public.food_trucks_in_city(text, timestamptz, timestamptz) to anon, authenticated;

-- ═════ 20261003000100_groups_family.sql ═════
-- VYBR8 · Groups: Family, Dating, Friends, Organizations, For The Kids (FTK)
--
-- • Anyone can make several groups. People are invited and must accept (no one is added to a
--   "family" or "dating" group without saying yes).
-- • Parents/guardians can add kid profiles (no app account needed). Kid profiles hold only a first
--   name, optional birthday, and food tastes, and are visible only to their guardians and the
--   groups the guardian puts them in.
-- • When a kid is 13+, a guardian makes a one-time transfer code. The kid signs up and enters it:
--   the profile becomes theirs, their tastes move over, and they stay in the family.
-- • Groups plan outings (date nights, family dinners) with menu picks per person.

create type public.group_kind as enum ('family', 'dating', 'friends', 'organization', 'ftk');
create type public.group_role as enum ('owner', 'admin', 'member');
create type public.group_member_status as enum ('invited', 'active');
create type public.group_relationship as enum
  ('partner', 'girlfriend', 'boyfriend', 'wife', 'husband', 'spouse', 'fiance', 'parent', 'child', 'sibling', 'grandparent',
   'cousin', 'aunt_uncle', 'relative', 'friend', 'coworker', 'teammate', 'member', 'other');

-- ── Kid profiles (dependents) ──────────────────────────────────────────
create table public.dependents (
  id           uuid primary key default gen_random_uuid(),
  first_name   text not null check (char_length(trim(first_name)) between 1 and 40),
  birthdate    date check (birthdate <= current_date),
  created_by   uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  claimed_by   uuid unique references public.profiles (id) on delete set null,   -- set when the kid takes over their profile
  claimed_at   timestamptz,
  is_demo      boolean not null default false,
  created_at   timestamptz not null default now()
);

create table public.dependent_guardians (
  dependent_id  uuid not null references public.dependents (id) on delete cascade,
  user_id       uuid not null references public.profiles (id) on delete cascade,
  created_at    timestamptz not null default now(),
  primary key (dependent_id, user_id)
);

create or replace function private.is_guardian(p_dependent uuid)
returns boolean language sql stable security definer set search_path = ''
as $$ select exists (select 1 from public.dependent_guardians where dependent_id = p_dependent and user_id = (select auth.uid())); $$;

create or replace function private.guardian_count(p_dependent uuid)
returns integer language sql stable security definer set search_path = ''
as $$ select count(*)::int from public.dependent_guardians where dependent_id = p_dependent; $$;

-- The creator becomes the first guardian.
create or replace function private.dependents_add_guardian()
returns trigger language plpgsql security definer set search_path = ''
as $$ begin insert into public.dependent_guardians (dependent_id, user_id) values (new.id, new.created_by); return new; end; $$;
create trigger dependents_add_guardian after insert on public.dependents for each row execute function private.dependents_add_guardian();

-- ── Groups ─────────────────────────────────────────────────────────────
create table public.groups (
  id           uuid primary key default gen_random_uuid(),
  owner_id     uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  name         text not null check (char_length(trim(name)) between 2 and 60),
  kind         public.group_kind not null,
  description  text check (char_length(description) <= 280),
  city_slug    text references public.cities (slug),
  is_demo      boolean not null default false,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create trigger groups_updated_at before update on public.groups for each row execute function private.set_updated_at();

create table public.group_members (
  id            uuid primary key default gen_random_uuid(),
  group_id      uuid not null references public.groups (id) on delete cascade,
  user_id       uuid references public.profiles (id) on delete cascade,
  dependent_id  uuid references public.dependents (id) on delete cascade,
  role          public.group_role not null default 'member',
  status        public.group_member_status not null default 'invited',
  relationship  public.group_relationship not null default 'member',
  invited_by    uuid references public.profiles (id) on delete set null,
  created_at    timestamptz not null default now(),
  check ((user_id is null) <> (dependent_id is null)),
  check (dependent_id is null or (status = 'active' and role = 'member'))
);
create unique index group_members_user_idx on public.group_members (group_id, user_id) where user_id is not null;
create unique index group_members_dependent_idx on public.group_members (group_id, dependent_id) where dependent_id is not null;
create index group_members_by_user on public.group_members (user_id) where user_id is not null;

create or replace function private.group_role_of(p_group uuid)
returns public.group_role language sql stable security definer set search_path = ''
as $$ select role from public.group_members where group_id = p_group and user_id = (select auth.uid()) and status = 'active'; $$;

create or replace function private.is_group_member(p_group uuid)
returns boolean language sql stable security definer set search_path = ''
as $$ select private.group_role_of(p_group) is not null; $$;

create or replace function private.can_manage_group(p_group uuid)
returns boolean language sql stable security definer set search_path = ''
as $$ select coalesce(private.group_role_of(p_group) in ('owner', 'admin'), false); $$;

-- Groups I share with someone (used to share tastes for planning).
create or replace function private.shares_group_with_user(p_user uuid)
returns boolean language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.group_members a join public.group_members b on b.group_id = a.group_id
                  where a.user_id = (select auth.uid()) and a.status = 'active' and b.user_id = p_user and b.status = 'active');
$$;
create or replace function private.shares_group_with_dependent(p_dependent uuid)
returns boolean language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.group_members a join public.group_members b on b.group_id = a.group_id
                  where a.user_id = (select auth.uid()) and a.status = 'active' and b.dependent_id = p_dependent);
$$;

create or replace function private.user_is_adult(p_user uuid)
returns boolean language sql stable security definer set search_path = ''
as $$ select coalesce((select private.age_on(birthdate, current_date) >= 18 from public.user_birthdays where user_id = p_user), false); $$;

-- The owner joins as the first member.
create or replace function private.groups_add_owner()
returns trigger language plpgsql security definer set search_path = ''
as $$
begin
  insert into public.group_members (group_id, user_id, role, status, relationship, invited_by)
  values (new.id, new.owner_id, 'owner', 'active', case new.kind when 'dating' then 'partner' when 'family' then 'relative' when 'friends' then 'friend' else 'member' end::public.group_relationship, new.owner_id);
  return new;
end;
$$;
create trigger groups_add_owner after insert on public.groups for each row execute function private.groups_add_owner();

create or replace function private.groups_guard()
returns trigger language plpgsql set search_path = ''
as $$
begin
  if (select auth.uid()) is null then return new; end if;
  if tg_op = 'INSERT' then
    if new.is_demo then raise exception 'not allowed' using errcode = '42501'; end if;
    if new.kind = 'dating' and not private.user_is_adult(new.owner_id) then
      raise exception 'dating groups are for people 18 and older' using errcode = '42501';
    end if;
    if (select count(*) from public.groups where owner_id = new.owner_id) >= 25 then
      raise exception 'you can own up to 25 groups' using errcode = '23514';
    end if;
    return new;
  end if;
  if new.owner_id <> old.owner_id or new.kind <> old.kind or new.is_demo <> old.is_demo then
    raise exception 'that change is not allowed' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger groups_guard before insert or update on public.groups for each row execute function private.groups_guard();

-- Size limits and safety rules on membership.
create or replace function private.group_members_guard()
returns trigger language plpgsql set search_path = ''
as $$
declare
  g public.groups;
  n integer;
begin
  select * into g from public.groups where id = new.group_id;
  select count(*) into n from public.group_members where group_id = new.group_id and id <> new.id;
  if n >= (case g.kind when 'dating' then 2 when 'family' then 30 when 'friends' then 50 when 'ftk' then 50 else 200 end) then
    raise exception 'this group is full' using errcode = '23514';
  end if;
  if g.kind = 'dating' and (new.dependent_id is not null or (new.user_id is not null and not private.user_is_adult(new.user_id))) then
    raise exception 'dating groups are for two people 18 and older' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger group_members_guard before insert on public.group_members for each row execute function private.group_members_guard();

-- ── Tastes (for planning and suggestions) ──────────────────────────────
create table public.taste_profiles (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid unique references public.profiles (id) on delete cascade,
  dependent_id  uuid unique references public.dependents (id) on delete cascade,
  likes         text[] not null default '{}' check (array_length(likes, 1) is null or array_length(likes, 1) <= 30),
  dislikes      text[] not null default '{}' check (array_length(dislikes, 1) is null or array_length(dislikes, 1) <= 30),
  allergies     text[] not null default '{}' check (array_length(allergies, 1) is null or array_length(allergies, 1) <= 15),
  dietary       text[] not null default '{}' check (array_length(dietary, 1) is null or array_length(dietary, 1) <= 10),
  spice         smallint check (spice between 0 and 4),       -- 0 none … 4 very hot
  kids_menu     boolean not null default false,
  notes         text check (char_length(notes) <= 280),
  updated_at    timestamptz not null default now(),
  check ((user_id is null) <> (dependent_id is null))
);

-- ── Plans (date nights, family dinners) with menu picks ────────────────
create table public.group_plans (
  id            uuid primary key default gen_random_uuid(),
  group_id      uuid not null references public.groups (id) on delete cascade,
  title         text not null check (char_length(trim(title)) between 2 and 80),
  planned_for   timestamptz,
  business_id   uuid references public.businesses (id) on delete set null,
  notes         text check (char_length(notes) <= 500),
  status        text not null default 'planned' check (status in ('idea', 'planned', 'done', 'cancelled')),
  created_by    uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at    timestamptz not null default now()
);
create index group_plans_group_idx on public.group_plans (group_id, planned_for);

create table public.group_plan_picks (
  id            uuid primary key default gen_random_uuid(),
  plan_id       uuid not null references public.group_plans (id) on delete cascade,
  member_id     uuid not null references public.group_members (id) on delete cascade,   -- who it's for (adult or kid)
  menu_item_id  uuid not null references public.menu_items (id) on delete cascade,
  note          text check (char_length(note) <= 140),
  added_by      uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at    timestamptz not null default now(),
  unique (plan_id, member_id, menu_item_id)
);

-- ── Transfer codes (kid takes over their profile at 13+) ───────────────
create table public.dependent_transfers (
  id            uuid primary key default gen_random_uuid(),
  dependent_id  uuid not null references public.dependents (id) on delete cascade,
  token_hash    text not null unique,
  created_by    uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  expires_at    timestamptz not null default now() + interval '30 days',
  redeemed_by   uuid references public.profiles (id) on delete set null,
  redeemed_at   timestamptz,
  created_at    timestamptz not null default now()
);

-- ── RLS ────────────────────────────────────────────────────────────────
alter table public.dependents enable row level security;
alter table public.dependent_guardians enable row level security;
alter table public.groups enable row level security;
alter table public.group_members enable row level security;
alter table public.taste_profiles enable row level security;
alter table public.group_plans enable row level security;
alter table public.group_plan_picks enable row level security;
alter table public.dependent_transfers enable row level security;

-- Kid profiles: guardians, the kid once they've claimed it, and people in a group with them.
create policy "dependents: guardians, claimed kid and shared groups read" on public.dependents for select to authenticated
  using (private.is_guardian(id) or claimed_by = (select auth.uid()) or private.shares_group_with_dependent(id));
create policy "dependents: parents add kids" on public.dependents for insert to authenticated
  with check (created_by = (select auth.uid()) and claimed_by is null and not is_demo);
create policy "dependents: guardians edit until the kid takes over" on public.dependents for update to authenticated
  using (private.is_guardian(id) and claimed_by is null)
  with check (private.is_guardian(id) and claimed_by is null);
create policy "dependents: guardians remove until the kid takes over" on public.dependents for delete to authenticated
  using (private.is_guardian(id) and claimed_by is null);

create policy "dependent_guardians: guardians read" on public.dependent_guardians for select to authenticated
  using (private.is_guardian(dependent_id) or user_id = (select auth.uid()));
-- A guardian can add a co-parent (who must be in a family group with them).
create policy "dependent_guardians: guardians add co-parents" on public.dependent_guardians for insert to authenticated
  with check (private.is_guardian(dependent_id) and private.shares_group_with_user(user_id)
              and not exists (select 1 from public.dependents d where d.id = dependent_id and d.claimed_by is not null));
create policy "dependent_guardians: step back" on public.dependent_guardians for delete to authenticated
  using (user_id = (select auth.uid()) and private.guardian_count(dependent_id) > 1);

create policy "groups: members and invitees read" on public.groups for select to authenticated
  using (owner_id = (select auth.uid()) or exists (select 1 from public.group_members m where m.group_id = groups.id and m.user_id = (select auth.uid())));
create policy "groups: anyone creates" on public.groups for insert to authenticated with check (owner_id = (select auth.uid()));
create policy "groups: owner and admins edit" on public.groups for update to authenticated
  using (private.can_manage_group(id)) with check (private.can_manage_group(id));
create policy "groups: owner deletes" on public.groups for delete to authenticated using (owner_id = (select auth.uid()));

create policy "group_members: members see the group; invitees see their invite" on public.group_members for select to authenticated
  using (private.is_group_member(group_id) or user_id = (select auth.uid()));
-- Owners/admins invite people (status invited; they must accept) and add kids they're a guardian of.
create policy "group_members: invite or add your kid" on public.group_members for insert to authenticated
  with check (private.can_manage_group(group_id) and role <> 'owner' and invited_by = (select auth.uid())
              and ((user_id is not null and status = 'invited' and not private.is_blocked_between((select auth.uid()), user_id))
                   or (dependent_id is not null and private.is_guardian(dependent_id))));
-- Invitees accept for themselves; owners/admins change relationship labels or promote members.
create policy "group_members: accept, relabel, promote" on public.group_members for update to authenticated
  using (user_id = (select auth.uid()) or private.can_manage_group(group_id))
  with check (user_id = (select auth.uid()) or private.can_manage_group(group_id));
create policy "group_members: leave, decline or remove" on public.group_members for delete to authenticated
  using ((user_id = (select auth.uid()) and role <> 'owner') or (private.can_manage_group(group_id) and role <> 'owner')
         or (dependent_id is not null and private.is_guardian(dependent_id)));

-- Members can't promote themselves or flip someone else's invite to active.
create or replace function private.group_members_update_guard()
returns trigger language plpgsql set search_path = ''
as $$
begin
  if (select auth.uid()) is null then return new; end if;
  if new.group_id <> old.group_id or new.user_id is distinct from old.user_id or new.dependent_id is distinct from old.dependent_id then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if new.status <> old.status and (old.user_id is distinct from (select auth.uid()) or new.status <> 'active') then
    raise exception 'only the invited person can accept' using errcode = '42501';
  end if;
  if new.role <> old.role and (old.role = 'owner' or new.role = 'owner' or private.group_role_of(new.group_id) <> 'owner') then
    raise exception 'only the owner changes roles' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger group_members_update_guard before update on public.group_members for each row execute function private.group_members_update_guard();

-- Tastes: your own; kids' by their guardians; shared with people in your groups for planning.
create policy "taste_profiles: own, kids and group members read" on public.taste_profiles for select to authenticated
  using (user_id = (select auth.uid())
         or (user_id is not null and private.shares_group_with_user(user_id))
         or (dependent_id is not null and (private.is_guardian(dependent_id) or private.shares_group_with_dependent(dependent_id))));
create policy "taste_profiles: own or your kid's" on public.taste_profiles for insert to authenticated
  with check (user_id = (select auth.uid())
              or (dependent_id is not null and private.is_guardian(dependent_id) and not exists (select 1 from public.dependents d where d.id = dependent_id and d.claimed_by is not null)));
create policy "taste_profiles: edit own or your kid's" on public.taste_profiles for update to authenticated
  using (user_id = (select auth.uid()) or (dependent_id is not null and private.is_guardian(dependent_id)
         and not exists (select 1 from public.dependents d where d.id = dependent_id and d.claimed_by is not null)))
  with check (user_id = (select auth.uid()) or (dependent_id is not null and private.is_guardian(dependent_id)));

create policy "group_plans: members" on public.group_plans for select to authenticated using (private.is_group_member(group_id));
create policy "group_plans: members plan" on public.group_plans for insert to authenticated
  with check (private.is_group_member(group_id) and created_by = (select auth.uid()));
create policy "group_plans: members update" on public.group_plans for update to authenticated
  using (private.is_group_member(group_id)) with check (private.is_group_member(group_id));
create policy "group_plans: creator or managers delete" on public.group_plans for delete to authenticated
  using (created_by = (select auth.uid()) or private.can_manage_group(group_id));

create policy "group_plan_picks: members" on public.group_plan_picks for select to authenticated
  using (exists (select 1 from public.group_plans p where p.id = plan_id and private.is_group_member(p.group_id)));
create policy "group_plan_picks: members pick for anyone in the group" on public.group_plan_picks for insert to authenticated
  with check (added_by = (select auth.uid())
              and exists (select 1 from public.group_plans p join public.group_members m on m.group_id = p.group_id
                           where p.id = plan_id and m.id = member_id and private.is_group_member(p.group_id))
              -- no alcohol picks for kids or anyone under 21 on the plan's day
              and not exists (select 1 from public.menu_items i join public.group_members m on m.id = member_id
                               where i.id = menu_item_id and i.is_alcoholic
                                 and (m.dependent_id is not null or not private.user_21_on(m.user_id, current_date))));
create policy "group_plan_picks: members remove" on public.group_plan_picks for delete to authenticated
  using (exists (select 1 from public.group_plans p where p.id = plan_id and private.is_group_member(p.group_id)));

create policy "dependent_transfers: guardians read" on public.dependent_transfers for select to authenticated
  using (private.is_guardian(dependent_id));
-- Created and redeemed only through the functions below.

-- ── Transfer: kid takes over at 13+ and stays in the family ────────────
create or replace function public.create_dependent_transfer(p_dependent uuid)
returns text
language plpgsql security definer
set search_path = ''
as $$
declare
  token text := encode(extensions.gen_random_bytes(18), 'hex');
begin
  if not private.is_guardian(p_dependent) then raise exception 'guardians only' using errcode = '42501'; end if;
  if exists (select 1 from public.dependents where id = p_dependent and claimed_by is not null) then
    raise exception 'this profile already belongs to them' using errcode = '22023';
  end if;
  delete from public.dependent_transfers where dependent_id = p_dependent and redeemed_at is null;
  insert into public.dependent_transfers (dependent_id, token_hash, created_by)
  values (p_dependent, encode(sha256(convert_to(token, 'UTF8')), 'hex'), auth.uid());
  return token;
end;
$$;

create or replace function public.redeem_dependent_transfer(p_token text)
returns uuid
language plpgsql security definer
set search_path = ''
as $$
declare
  me uuid := auth.uid();
  t public.dependent_transfers;
  d public.dependents;
begin
  if me is null then raise exception 'sign in first' using errcode = '42501'; end if;
  select * into t from public.dependent_transfers
   where token_hash = encode(sha256(convert_to(coalesce(p_token, ''), 'UTF8')), 'hex') for update;
  if not found or t.redeemed_at is not null or t.expires_at < now() then raise exception 'this code is not valid' using errcode = 'P0002'; end if;
  select * into d from public.dependents where id = t.dependent_id for update;
  if d.claimed_by is not null then raise exception 'this profile already belongs to someone' using errcode = '22023'; end if;
  if exists (select 1 from public.dependent_guardians where dependent_id = d.id and user_id = me) then
    raise exception 'a parent can''t take over their kid''s profile' using errcode = '42501';
  end if;
  if coalesce((select private.age_on(birthdate, current_date) from public.user_birthdays where user_id = me), 0) < 13 then
    raise exception 'you need to be 13 or older' using errcode = '42501';
  end if;

  update public.dependents set claimed_by = me, claimed_at = now() where id = d.id;
  update public.dependent_transfers set redeemed_by = me, redeemed_at = now() where id = t.id;

  -- Stay in every group: kid rows become their own account's rows.
  insert into public.group_members (group_id, user_id, role, status, relationship, invited_by)
  select m.group_id, me, 'member', 'active', m.relationship, m.invited_by
    from public.group_members m join public.groups g on g.id = m.group_id
   where m.dependent_id = d.id and g.kind <> 'dating'
  on conflict do nothing;
  update public.group_plan_picks p set member_id = nm.id
    from public.group_members om, public.group_members nm
   where p.member_id = om.id and om.dependent_id = d.id and nm.group_id = om.group_id and nm.user_id = me;
  delete from public.group_members where dependent_id = d.id;

  -- Their tastes come with them (unless they already set their own).
  if exists (select 1 from public.taste_profiles where user_id = me) then
    delete from public.taste_profiles where dependent_id = d.id;
  else
    update public.taste_profiles set dependent_id = null, user_id = me, updated_at = now() where dependent_id = d.id;
  end if;

  insert into public.notifications (user_id, kind, title, body, link)
  select g.user_id, 'family.transfer', d.first_name || ' has their own VYBR8 now',
         'Their profile moved to their account. They''re still in your family.', '/groups'
    from public.dependent_guardians g where g.dependent_id = d.id;
  return d.id;
end;
$$;

revoke execute on function public.create_dependent_transfer(uuid) from public, anon;
revoke execute on function public.redeem_dependent_transfer(text) from public, anon;
grant execute on function public.create_dependent_transfer(uuid) to authenticated;
grant execute on function public.redeem_dependent_transfer(text) to authenticated;

-- Invite notifications.
create or replace function private.group_invite_notify()
returns trigger language plpgsql security definer set search_path = ''
as $$
begin
  if new.user_id is not null and new.status = 'invited' then
    insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
    select new.user_id, 'group.invite', 'You''re invited to a group',
           coalesce((select coalesce(display_name, username::text) from public.profiles where id = new.invited_by), 'Someone') || ' invited you to ' || g.name,
           '/groups', 'group.invite:' || new.id
      from public.groups g where g.id = new.group_id
    on conflict do nothing;
  end if;
  return new;
end;
$$;
create trigger group_members_invite_notify after insert on public.group_members for each row execute function private.group_invite_notify();

grant execute on all functions in schema private to anon, authenticated, service_role;

-- ═════ 20261004000100_places_claims.sql ═════
-- VYBR8 · Places, franchises and claims
--
-- • Anyone signed in can add a place. It waits for a quick VYBR8 Team check before it goes public.
-- • Every physical location is its own listing with its own ratings, menu and claim. Franchise locations
--   share a brand but are told apart by branch name and street address ("Chick-fil-A · South Blvd").
-- • Owners claim their location by proving it's theirs. Chefs claim their chef profile the same way.
--   An approved claim gives the place the "VYBR8 Approved" badge.
-- • Places pulled from Google or Foursquare later keep their provider id here, so imports never duplicate.

-- ── Brands (franchise groups) ─────────────────────────────────────────
create table public.brands (
  id          uuid primary key default gen_random_uuid(),
  slug        extensions.citext not null unique check (slug::text ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) <= 80),
  name        text not null check (char_length(trim(name)) between 1 and 120),
  logo_url    text check (logo_url is null or logo_url ~ '^(https://|/)'),
  website     text check (website is null or website ~ '^https://'),
  created_at  timestamptz not null default now()
);
alter table public.brands enable row level security;
create policy "brands: public" on public.brands for select to anon, authenticated using (true);
create policy "brands: team writes" on public.brands for all to authenticated using (private.is_staff()) with check (private.is_staff());

alter table public.businesses
  add column brand_id    uuid references public.brands (id) on delete set null,
  add column branch_name text check (branch_name is null or char_length(trim(branch_name)) between 1 and 80),
  add column source      text not null default 'vybr8' check (source in ('vybr8', 'community', 'owner', 'google', 'foursquare')),
  add column approved_at timestamptz;   -- set when an owner's claim is approved: the VYBR8 Approved badge
create index businesses_brand_idx on public.businesses (brand_id) where brand_id is not null;
update public.businesses set approved_at = updated_at where is_claimed and approved_at is null;

-- Provider ids (Google place_id, Foursquare fsq_id) so a place is only ever listed once.
create table public.place_external_ids (
  provider     text not null check (provider in ('google', 'foursquare', 'mapbox')),
  external_id  text not null check (char_length(external_id) between 1 and 300),
  business_id  uuid not null references public.businesses (id) on delete cascade,
  location_id  uuid references public.business_locations (id) on delete cascade,
  created_at   timestamptz not null default now(),
  primary key (provider, external_id)
);
create index place_external_ids_business_idx on public.place_external_ids (business_id);
alter table public.place_external_ids enable row level security;
create policy "place_external_ids: follow the place" on public.place_external_ids for select to anon, authenticated
  using (exists (select 1 from public.businesses b where b.id = business_id));
create policy "place_external_ids: team writes" on public.place_external_ids for all to authenticated
  using (private.is_staff()) with check (private.is_staff());

-- People who added a place can see it while it waits for review.
create policy "businesses: submitters see their pending places" on public.businesses for select to authenticated
  using (created_by = (select auth.uid()) and deleted_at is null);

-- Privileged columns. Admins change anything; the team (moderators) can publish places and link brands.
create or replace function private.businesses_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select auth.uid()) is null or private.is_admin() then return new; end if;
  if new.is_claimed  is distinct from old.is_claimed
  or new.is_demo     is distinct from old.is_demo
  or new.slug        is distinct from old.slug
  or new.deleted_at  is distinct from old.deleted_at
  or new.created_by  is distinct from old.created_by
  or new.source      is distinct from old.source
  or new.approved_at is distinct from old.approved_at then
    raise exception 'claim, approval, demo, slug, source and deletion fields are admin-only' using errcode = '42501';
  end if;
  if (new.status is distinct from old.status or new.brand_id is distinct from old.brand_id) and not private.is_staff() then
    raise exception 'publishing a place and linking brands is done by the VYBR8 Team' using errcode = '42501';
  end if;
  return new;
end;
$$;

-- ── Text helpers ──────────────────────────────────────────────────────
create or replace function private.slugify(p text)
returns text language sql immutable set search_path = ''
as $$ select left(trim(both '-' from regexp_replace(lower(coalesce(p, '')), '[^a-z0-9]+', '-', 'g')), 70); $$;

-- "The Ember & Oak!" → "emberoak"
create or replace function private.norm_name(p text)
returns text language sql immutable set search_path = ''
as $$ select regexp_replace(regexp_replace(lower(coalesce(p, '')), '^the\s+', ''), '[^a-z0-9]', '', 'g'); $$;

-- "1200 South Boulevard, Suite 4" → "1200southblvd"  (suite/unit dropped, common words shortened)
create or replace function private.norm_address(p text)
returns text language sql immutable set search_path = ''
as $$
  select regexp_replace(
           regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(
             lower(split_part(coalesce(p, ''), ',', 1)),
             '(\m(suite|ste|unit|apt)\M|#)\s*\S+', '', 'g'),
             '\mstreet\M', 'st', 'g'), '\mavenue\M', 'ave', 'g'), '\mboulevard\M', 'blvd', 'g'), '\mroad\M', 'rd', 'g'),
             '\mdrive\M', 'dr', 'g'), '\mparkway\M', 'pkwy', 'g'), '\mhighway\M', 'hwy', 'g'),
           '[^a-z0-9]', '', 'g');
$$;

-- "1200 South Blvd" → "South Blvd" (the branch name when the owner doesn't give one)
create or replace function private.street_name(p text)
returns text language sql immutable set search_path = ''
as $$ select nullif(trim(regexp_replace(split_part(coalesce(p, ''), ',', 1), '^\s*[0-9][0-9A-Za-z-]*\s+', '')), ''); $$;

-- Meters between two points.
create or replace function private.meters_between(lat1 numeric, lng1 numeric, lat2 numeric, lng2 numeric)
returns double precision language sql immutable set search_path = ''
as $$
  select 6371000 * 2 * asin(sqrt(
    power(sin(radians((lat2 - lat1)::float8) / 2), 2)
    + cos(radians(lat1::float8)) * cos(radians(lat2::float8)) * power(sin(radians((lng2 - lng1)::float8) / 2), 2)));
$$;

create or replace function private.unique_business_slug(p_base text)
returns text language plpgsql stable set search_path = ''
as $$
declare
  base text := coalesce(nullif(private.slugify(p_base), ''), 'place');
  candidate text := base;
  n int := 1;
begin
  while exists (select 1 from public.businesses where slug = candidate::extensions.citext) loop
    n := n + 1;
    candidate := left(base, 70) || '-' || n;
  end loop;
  return candidate;
end;
$$;

grant execute on all functions in schema private to anon, authenticated, service_role;

-- ── Is this place already on VYBR8? ───────────────────────────────────
-- Same city + same name (or one name inside the other) + same street address or within 150 m.
-- Different addresses are different locations, so franchise spots never collide.
create or replace function public.find_existing_place(p_name text, p_city_slug text, p_address text, p_lat numeric default null, p_lng numeric default null)
returns table (slug text, name text, branch_name text, address text, status public.business_status)
language sql stable security definer
set search_path = ''
as $$
  select b.slug::text, b.name, b.branch_name, l.address_line1, b.status
    from public.businesses b
    join public.business_locations l on l.business_id = b.id
   where l.city_slug = p_city_slug
     and b.deleted_at is null
     and (b.status = 'active' or b.created_by = (select auth.uid()) or private.is_staff())
     and length(private.norm_name(p_name)) >= 2
     and (private.norm_name(b.name) = private.norm_name(p_name)
          or (length(private.norm_name(p_name)) >= 4 and private.norm_name(b.name) like '%' || private.norm_name(p_name) || '%')
          or (length(private.norm_name(b.name)) >= 4 and private.norm_name(p_name) like '%' || private.norm_name(b.name) || '%'))
     and ((l.address_line1 is not null and private.norm_address(l.address_line1) = private.norm_address(p_address))
          or (p_lat is not null and p_lng is not null and l.latitude is not null
              and private.meters_between(l.latitude, l.longitude, p_lat, p_lng) < 150))
   limit 5;
$$;
grant execute on function public.find_existing_place(text, text, text, numeric, numeric) to authenticated;

-- ── Add a place ───────────────────────────────────────────────────────
create or replace function public.submit_place(
  p_name        text,
  p_kind        public.business_kind,
  p_city_slug   text,
  p_address     text,
  p_branch      text default null,
  p_postal      text default null,
  p_lat         numeric default null,
  p_lng         numeric default null,
  p_website     text default null,
  p_i_own_it    boolean default false,
  p_provider    text default null,
  p_external_id text default null
)
returns jsonb
language plpgsql security definer
set search_path = ''
as $$
declare
  uid uuid := auth.uid();
  c public.cities;
  dup record;
  existing uuid;
  branch text;
  brand uuid;
  new_slug text;
  biz uuid;
  loc uuid;
begin
  if uid is null then raise exception 'sign in to add a place' using errcode = '42501'; end if;
  p_name := trim(coalesce(p_name, ''));
  p_address := trim(coalesce(p_address, ''));
  if char_length(p_name) not between 2 and 120 then raise exception 'Give the place its name.' using errcode = '22023'; end if;
  if char_length(p_address) not between 5 and 160 or p_address !~ '[0-9]' then
    raise exception 'Add the street address (number and street), so each location is its own listing.' using errcode = '22023';
  end if;
  if p_kind = 'food_truck' then raise exception 'Food trucks are added from the food truck page.' using errcode = '22023'; end if;
  if p_website is not null and p_website !~ '^https://' then raise exception 'Website must start with https://' using errcode = '22023'; end if;
  if (p_lat is null) <> (p_lng is null) then raise exception 'Location needs both latitude and longitude.' using errcode = '22023'; end if;

  select * into c from public.cities where slug = p_city_slug and is_active;
  if not found then raise exception 'Pick one of the VYBR8 cities.' using errcode = '22023'; end if;
  if p_lat is not null and (p_lat not between c.south - 0.35 and c.north + 0.35 or p_lng not between c.west - 0.35 and c.east + 0.35) then
    raise exception 'That pin is outside %.', c.name using errcode = '22023';
  end if;

  if p_provider is not null and p_external_id is not null then
    select business_id into existing from public.place_external_ids where provider = p_provider and external_id = p_external_id;
    if existing is not null then
      return jsonb_build_object('status', 'duplicate', 'slug', (select slug::text from public.businesses where id = existing));
    end if;
  end if;

  select * into dup from public.find_existing_place(p_name, p_city_slug, p_address, p_lat, p_lng) limit 1;
  if found then
    return jsonb_build_object('status', 'duplicate', 'slug', dup.slug, 'name', dup.name, 'address', dup.address);
  end if;

  if (select count(*) from public.businesses where created_by = uid and created_at > now() - interval '1 day') >= 10 then
    raise exception 'You''ve added 10 places today. Thanks! Try again tomorrow.' using errcode = '22023';
  end if;

  branch := coalesce(nullif(trim(p_branch), ''), private.street_name(p_address));
  new_slug := private.unique_business_slug(p_name || ' ' || coalesce(branch, '') || ' ' || c.slug);

  -- Franchise: if this name already belongs to a brand, the new location joins it.
  select id into brand from public.brands where private.norm_name(name) = private.norm_name(p_name) limit 1;

  insert into public.businesses (slug, name, kind, website, status, source, branch_name, brand_id, created_by)
  values (new_slug::extensions.citext, p_name, p_kind, p_website, 'pending', case when p_i_own_it then 'owner' else 'community' end, branch, brand, uid)
  returning id into biz;

  insert into public.business_locations (business_id, label, address_line1, city, region, postal_code, latitude, longitude, timezone, city_slug, is_primary)
  values (biz, branch, p_address, split_part(c.name, ',', 1), c.region, nullif(trim(p_postal), ''), p_lat, p_lng, c.timezone, c.slug, true)
  returning id into loc;

  if p_provider is not null and p_external_id is not null then
    insert into public.place_external_ids (provider, external_id, business_id, location_id) values (p_provider, p_external_id, biz, loc);
  end if;

  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values (uid, 'place.submitted', 'business', biz, jsonb_build_object('city', c.slug, 'owner', p_i_own_it));

  return jsonb_build_object('status', 'created', 'slug', new_slug, 'id', biz);
end;
$$;
grant execute on function public.submit_place(text, public.business_kind, text, text, text, text, numeric, numeric, text, boolean, text, text) to authenticated;

-- ── Team review of new places ─────────────────────────────────────────
create or replace function public.review_place(p_business uuid, p_approve boolean, p_note text default null)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  b public.businesses;
begin
  if not private.is_staff() then raise exception 'VYBR8 Team only' using errcode = '42501'; end if;
  select * into b from public.businesses where id = p_business for update;
  if not found then raise exception 'place not found' using errcode = 'P0002'; end if;
  if b.status <> 'pending' then raise exception 'place is already %', b.status using errcode = '22023'; end if;

  update public.businesses set status = case when p_approve then 'active' else 'hidden' end::public.business_status where id = b.id;

  if b.created_by is not null then
    insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
    values (b.created_by, 'place.reviewed',
            case when p_approve then b.name || ' is live on VYBR8' else b.name || ' wasn''t added' end,
            case when p_approve then 'Thanks for adding it. Post the first plate!' else coalesce(p_note, 'We couldn''t confirm this place.') end,
            '/venue/' || b.slug, 'place.reviewed:' || b.id)
    on conflict do nothing;
  end if;

  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values (auth.uid(), case when p_approve then 'place.approved' else 'place.rejected' end, 'business', b.id, jsonb_build_object('note', p_note));
end;
$$;
grant execute on function public.review_place(uuid, boolean, text) to authenticated;

-- Team links a location to its franchise brand (creating the brand the first time).
create or replace function public.set_place_brand(p_business uuid, p_brand_name text)
returns text
language plpgsql security definer
set search_path = ''
as $$
declare
  br uuid;
begin
  if not private.is_staff() then raise exception 'VYBR8 Team only' using errcode = '42501'; end if;
  if coalesce(trim(p_brand_name), '') = '' then
    update public.businesses set brand_id = null where id = p_business;
    return null;
  end if;
  select id into br from public.brands where private.norm_name(name) = private.norm_name(p_brand_name) limit 1;
  if br is null then
    insert into public.brands (slug, name)
    values (coalesce(nullif(private.slugify(p_brand_name), ''), 'brand-' || left(gen_random_uuid()::text, 8))::extensions.citext, trim(p_brand_name))
    on conflict (slug) do update set name = public.brands.name
    returning id into br;
  end if;
  update public.businesses set brand_id = br where id = p_business;
  return (select slug::text from public.brands where id = br);
end;
$$;
grant execute on function public.set_place_brand(uuid, text) to authenticated;

-- ── Claiming a place ──────────────────────────────────────────────────
alter table public.business_claims
  add column proof_method  text check (proof_method in ('business_email', 'business_phone', 'document', 'google_profile', 'social')),
  add column proof_code    text,
  add column contact_email text check (contact_email is null or contact_email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  add column contact_phone text check (contact_phone is null or char_length(contact_phone) between 7 and 30),
  add column document_path text check (document_path is null or char_length(document_path) <= 300);

-- Claimable: live and unclaimed, or a place you just added yourself (so owners can add + claim in one go).
create or replace function private.business_is_claimable(p_business_id uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.businesses
    where id = p_business_id and not is_claimed and deleted_at is null
      and (status = 'active' or (status = 'pending' and created_by = (select auth.uid())))
  );
$$;

-- Private proof documents (business license, food permit, utility bill). Only the claimant and admins can open them.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('claim-docs', 'claim-docs', false, 5242880, array['image/jpeg', 'image/png', 'image/webp', 'application/pdf'])
on conflict (id) do nothing;
create policy "claim-docs: upload to your own folder" on storage.objects for insert to authenticated
  with check (bucket_id = 'claim-docs' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "claim-docs: you and admins read" on storage.objects for select to authenticated
  using (bucket_id = 'claim-docs' and ((storage.foldername(name))[1] = (select auth.uid())::text or private.is_admin()));

create or replace function private.proof_code()
returns text language sql volatile set search_path = ''
as $$ select 'VYBR8-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6)); $$;

create or replace function private.email_domain_matches(p_email text, p_website text)
returns boolean language sql immutable set search_path = ''
as $$
  select p_email is not null and p_website is not null
     and lower(split_part(p_email, '@', 2)) = regexp_replace(lower(split_part(regexp_replace(p_website, '^https?://', ''), '/', 1)), '^www\.', '');
$$;

create or replace function public.start_business_claim(
  p_business uuid, p_role text, p_method text, p_email text default null, p_phone text default null,
  p_document_path text default null, p_note text default null)
returns jsonb
language plpgsql security definer
set search_path = ''
as $$
declare
  uid uuid := auth.uid();
  b public.businesses;
  code text := private.proof_code();
  claim uuid;
  matches boolean;
begin
  if uid is null then raise exception 'sign in to claim a place' using errcode = '42501'; end if;
  if not private.business_is_claimable(p_business) then raise exception 'This place can''t be claimed right now.' using errcode = '22023'; end if;
  if p_method not in ('business_email', 'business_phone', 'document', 'google_profile', 'social') then raise exception 'Pick how you''ll prove it.' using errcode = '22023'; end if;
  if coalesce(trim(p_role), '') = '' then raise exception 'Tell us your role (owner, general manager…).' using errcode = '22023'; end if;
  if p_method = 'business_email' and coalesce(p_email, '') = '' then raise exception 'Add the business email we should write to.' using errcode = '22023'; end if;
  if p_method = 'business_phone' and coalesce(p_phone, '') = '' then raise exception 'Add the business phone number we should call.' using errcode = '22023'; end if;
  if p_method = 'document' and coalesce(p_document_path, '') = '' then raise exception 'Upload a document that shows the business name and address.' using errcode = '22023'; end if;
  if p_document_path is not null and split_part(p_document_path, '/', 1) <> uid::text then raise exception 'not your upload' using errcode = '42501'; end if;
  if exists (select 1 from public.business_claims where business_id = p_business and claimant_id = uid and status = 'pending') then
    raise exception 'Your claim for this place is already waiting for review.' using errcode = '22023';
  end if;

  select * into b from public.businesses where id = p_business;
  matches := private.email_domain_matches(p_email, b.website);

  insert into public.business_claims (business_id, claimant_id, claimant_role, proof_method, proof_code, contact_email, contact_phone, document_path, evidence)
  values (p_business, uid, left(trim(p_role), 80), p_method, code, nullif(trim(p_email), ''), nullif(trim(p_phone), ''), p_document_path,
          jsonb_build_object('note', left(coalesce(p_note, ''), 1000), 'email_matches_website', matches))
  returning id into claim;

  return jsonb_build_object('claim_id', claim, 'code', code, 'email_matches_website', matches);
end;
$$;
grant execute on function public.start_business_claim(uuid, text, text, text, text, text, text) to authenticated;

-- Approving a claim: the claimant becomes owner, the place goes live (if it was waiting) and gets the badge.
create or replace function public.approve_business_claim(p_claim_id uuid, p_note text default null)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  c public.business_claims;
  b public.businesses;
begin
  if not private.is_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;

  select * into c from public.business_claims where id = p_claim_id for update;
  if not found then raise exception 'claim not found' using errcode = 'P0002'; end if;
  if c.status <> 'pending' then raise exception 'claim is %', c.status using errcode = '22023'; end if;

  update public.business_claims
     set status = 'approved', decision_note = p_note, reviewed_by = auth.uid(), reviewed_at = now()
   where id = c.id;

  update public.business_claims
     set status = 'rejected', decision_note = 'Another claim for this business was approved',
         reviewed_by = auth.uid(), reviewed_at = now()
   where business_id = c.business_id and status = 'pending' and id <> c.id;

  insert into public.business_members (business_id, user_id, role, invited_by)
  values (c.business_id, c.claimant_id, 'owner', auth.uid())
  on conflict (business_id, user_id) do update set role = 'owner';

  update public.businesses
     set is_claimed = true, approved_at = now(), status = case when status = 'pending' then 'active'::public.business_status else status end
   where id = c.business_id
  returning * into b;

  insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
  values (c.claimant_id, 'claim.approved', b.name || ' is yours', 'Your place is VYBR8 Approved. Add your menu, hours and photos.', '/venue/' || b.slug, 'claim.approved:' || c.id)
  on conflict do nothing;

  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'business_claim.approved', 'business', c.business_id,
          jsonb_build_object('claim_id', c.id, 'claimant_id', c.claimant_id, 'method', c.proof_method));
end;
$$;

-- ── Claiming a chef profile ───────────────────────────────────────────
-- Chef profiles the team (or a future import) creates start with no owner. The real chef proves it's them.
create table public.chef_claims (
  id             uuid primary key default gen_random_uuid(),
  chef_id        uuid not null references public.chef_profiles (id) on delete cascade,
  claimant_id    uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  status         public.claim_status not null default 'pending',
  proof_method   text not null check (proof_method in ('social', 'business_confirmation', 'license_or_certificate', 'document')),
  proof_code     text not null,
  links          text check (char_length(links) <= 600),
  document_path  text check (document_path is null or char_length(document_path) <= 300),
  note           text check (char_length(note) <= 1000),
  decision_note  text,
  reviewed_by    uuid references public.profiles (id) on delete set null,
  reviewed_at    timestamptz,
  created_at     timestamptz not null default now()
);
create unique index chef_claims_one_pending on public.chef_claims (chef_id, claimant_id) where status = 'pending';
alter table public.chef_claims enable row level security;
create policy "chef_claims: claimant and admins read" on public.chef_claims for select to authenticated
  using (claimant_id = (select auth.uid()) or private.is_admin());
-- Writes go through the RPCs below only.

create or replace function public.start_chef_claim(p_chef uuid, p_method text, p_links text default null, p_document_path text default null, p_note text default null)
returns jsonb
language plpgsql security definer
set search_path = ''
as $$
declare
  uid uuid := auth.uid();
  code text := private.proof_code();
  claim uuid;
begin
  if uid is null then raise exception 'sign in to claim a profile' using errcode = '42501'; end if;
  if not exists (select 1 from public.chef_profiles where id = p_chef and user_id is null) then
    raise exception 'This chef profile already has an owner.' using errcode = '22023';
  end if;
  if exists (select 1 from public.chef_profiles where user_id = uid) then
    raise exception 'You already have a chef profile. Ask the VYBR8 Team to merge them.' using errcode = '22023';
  end if;
  if p_method not in ('social', 'business_confirmation', 'license_or_certificate', 'document') then raise exception 'Pick how you''ll prove it.' using errcode = '22023'; end if;
  if p_method = 'social' and coalesce(trim(p_links), '') = '' then raise exception 'Add your Instagram, TikTok or YouTube link.' using errcode = '22023'; end if;
  if p_document_path is not null and split_part(p_document_path, '/', 1) <> uid::text then raise exception 'not your upload' using errcode = '42501'; end if;
  if exists (select 1 from public.chef_claims where chef_id = p_chef and claimant_id = uid and status = 'pending') then
    raise exception 'Your claim is already waiting for review.' using errcode = '22023';
  end if;
  insert into public.chef_claims (chef_id, claimant_id, proof_method, proof_code, links, document_path, note)
  values (p_chef, uid, p_method, code, nullif(trim(p_links), ''), p_document_path, nullif(trim(p_note), ''))
  returning id into claim;
  return jsonb_build_object('claim_id', claim, 'code', code);
end;
$$;
grant execute on function public.start_chef_claim(uuid, text, text, text, text) to authenticated;

create or replace function public.decide_chef_claim(p_claim uuid, p_approve boolean, p_note text default null)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  c public.chef_claims;
  chef public.chef_profiles;
begin
  if not private.is_admin() then raise exception 'admin only' using errcode = '42501'; end if;
  select * into c from public.chef_claims where id = p_claim for update;
  if not found then raise exception 'claim not found' using errcode = 'P0002'; end if;
  if c.status <> 'pending' then raise exception 'claim is %', c.status using errcode = '22023'; end if;
  select * into chef from public.chef_profiles where id = c.chef_id for update;

  if not p_approve then
    update public.chef_claims set status = 'rejected', decision_note = coalesce(p_note, 'Could not verify'), reviewed_by = auth.uid(), reviewed_at = now() where id = c.id;
    return;
  end if;
  if chef.user_id is not null then raise exception 'profile already has an owner' using errcode = '22023'; end if;
  if exists (select 1 from public.chef_profiles where user_id = c.claimant_id) then raise exception 'claimant already owns a chef profile' using errcode = '22023'; end if;

  update public.chef_claims set status = 'approved', decision_note = p_note, reviewed_by = auth.uid(), reviewed_at = now() where id = c.id;
  update public.chef_claims set status = 'rejected', decision_note = 'Another claim was approved', reviewed_by = auth.uid(), reviewed_at = now()
   where chef_id = c.chef_id and status = 'pending' and id <> c.id;
  update public.chef_profiles set user_id = c.claimant_id, verification = 'verified' where id = c.chef_id;

  insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
  values (c.claimant_id, 'chef_claim.approved', 'Your chef profile is yours', 'You''re verified. Update your services, menus and booking link.', '/chef/dashboard', 'chef_claim.approved:' || c.id)
  on conflict do nothing;
  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'chef_claim.approved', 'chef_profile', c.chef_id, jsonb_build_object('claim_id', c.id, 'claimant_id', c.claimant_id));
end;
$$;
grant execute on function public.decide_chef_claim(uuid, boolean, text) to authenticated;

-- ═════ 20261005000100_active_vybe.sql ═════
-- VYBR8 · Active Vybe & Vybe Plan
--
-- • Activity per day (steps, active calories, distance, minutes). Private to the person, always.
--   Today it's entered by hand; phone health apps (Apple Health, Health Connect, Samsung Health) write here
--   once the VYBR8 phone app ships, and Garmin/Fitbit through their partner APIs. Each source keeps its own row.
-- • A step goal, and "connect" requests so we know which health apps people want first.
-- • Your Vybe Plan (MAX): meals planned per day from real menu items near you, with nutrition only where it's known.
--   Wellness information, not medical advice.

create table public.activity_days (
  user_id          uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  day              date not null,
  source           text not null default 'manual' check (source in ('manual', 'apple_health', 'health_connect', 'samsung_health', 'garmin', 'fitbit')),
  steps            integer check (steps between 0 and 150000),
  active_calories  integer check (active_calories between 0 and 10000),
  distance_m       integer check (distance_m between 0 and 300000),
  active_minutes   integer check (active_minutes between 0 and 1440),
  updated_at       timestamptz not null default now(),
  primary key (user_id, day, source)
);
create index activity_days_user_day_idx on public.activity_days (user_id, day desc);

create table public.activity_goals (
  user_id     uuid primary key default auth.uid() references public.profiles (id) on delete cascade,
  step_goal   integer not null default 10000 check (step_goal between 1000 and 50000),
  updated_at  timestamptz not null default now()
);

create table public.health_connections (
  user_id     uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  provider    text not null check (provider in ('apple_health', 'health_connect', 'samsung_health', 'garmin', 'fitbit')),
  status      text not null default 'requested' check (status in ('requested', 'connected', 'disconnected')),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  primary key (user_id, provider)
);

-- One row per planned meal. MAX feature: meal_planning.
create table public.meal_plan_items (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  day              date not null,
  slot             text not null check (slot in ('breakfast', 'lunch', 'pre_workout', 'snack', 'dinner')),
  at_time          time not null,
  menu_item_id     uuid references public.menu_items (id) on delete set null,
  name             text not null check (char_length(trim(name)) between 1 and 120),
  calories         integer check (calories between 0 and 10000),
  protein_g        numeric(6,1) check (protein_g >= 0),
  carbs_g          numeric(6,1) check (carbs_g >= 0),
  fat_g            numeric(6,1) check (fat_g >= 0),
  nutrition_source public.nutrition_source not null default 'unknown',
  eaten_at         timestamptz,
  created_at       timestamptz not null default now()
);
create index meal_plan_items_user_day_idx on public.meal_plan_items (user_id, day, at_time);

create table public.day_plans (
  user_id   uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  day       date not null,
  day_type  text not null default 'custom' check (day_type in ('high_energy', 'rest', 'custom')),
  primary key (user_id, day)
);

alter table public.activity_days enable row level security;
alter table public.activity_goals enable row level security;
alter table public.health_connections enable row level security;
alter table public.meal_plan_items enable row level security;
alter table public.day_plans enable row level security;

-- Health data is owner-only. Not friends, not businesses, not the VYBR8 Team.
create policy "activity_days: owner only" on public.activity_days for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "activity_goals: owner only" on public.activity_goals for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "health_connections: owner only" on public.health_connections for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()) and status = 'requested');
create policy "meal_plan_items: owner reads and edits" on public.meal_plan_items for select to authenticated
  using (user_id = (select auth.uid()));
create policy "meal_plan_items: MAX members add" on public.meal_plan_items for insert to authenticated
  with check (user_id = (select auth.uid()) and private.viewer_can('meal_planning'));
create policy "meal_plan_items: owner updates" on public.meal_plan_items for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "meal_plan_items: owner deletes" on public.meal_plan_items for delete to authenticated
  using (user_id = (select auth.uid()));
create policy "day_plans: owner only" on public.day_plans for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- Only the phone app / partner sync (service role) can write a non-manual source.
create or replace function private.activity_days_guard()
returns trigger language plpgsql set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and new.source <> 'manual' then
    raise exception 'only manual entries can be typed in' using errcode = '42501';
  end if;
  new.updated_at := now();
  return new;
end;
$$;
create trigger activity_days_guard before insert or update on public.activity_days
  for each row execute function private.activity_days_guard();

-- ── Suggest a day of meals ────────────────────────────────────────────
-- Picks real, available, non-alcoholic menu items in the city, with calories known, sized to the person's
-- calorie target (or 2,000 kcal) and the kind of day. Replaces the day's meals that haven't been eaten yet.
create or replace function public.suggest_meal_plan(p_city text, p_day date, p_day_type text default 'custom')
returns integer
language plpgsql security definer
set search_path = ''
as $$
declare
  uid uuid := auth.uid();
  can_plus boolean := private.viewer_can('advanced_nutrition');
  target integer;
  mult numeric := case p_day_type when 'high_energy' then 1.15 when 'rest' then 0.9 else 1 end;
  s record;
  pick record;
  chosen uuid[] := '{}';
  n integer := 0;
begin
  if uid is null then raise exception 'sign in' using errcode = '42501'; end if;
  if not private.viewer_can('meal_planning') then raise exception 'Your Vybe Plan is part of VYBR8 MAX.' using errcode = '42501'; end if;
  if p_day < current_date - 1 or p_day > current_date + 14 then raise exception 'Plan up to two weeks ahead.' using errcode = '22023'; end if;
  if p_day_type not in ('high_energy', 'rest', 'custom') then raise exception 'unknown day type' using errcode = '22023'; end if;

  select coalesce((select calories from public.nutrition_targets where user_id = uid), 2000) into target;

  insert into public.day_plans (user_id, day, day_type) values (uid, p_day, p_day_type)
  on conflict (user_id, day) do update set day_type = excluded.day_type;
  delete from public.meal_plan_items where user_id = uid and day = p_day and eaten_at is null;

  for s in
    select * from (values ('breakfast', time '07:30', 0.25, false), ('lunch', time '12:30', 0.30, false),
                          ('pre_workout', time '16:30', 0.12, true), ('dinner', time '19:00', 0.33, false)) v(slot, at_time, share, light)
  loop
    select m.id, m.name, n2.calories, n2.protein_g, n2.carbs_g, n2.fat_g, n2.source into pick
      from public.menu_items m
      join public.businesses b on b.id = m.business_id and b.status = 'active' and b.deleted_at is null
      join public.menu_item_nutrition n2 on n2.menu_item_id = m.id and n2.calories is not null
      left join public.menu_item_intel i on i.menu_item_id = m.id
     where m.is_available and not m.is_alcoholic
       and (m.sold_out_until is null or m.sold_out_until < now())
       and not (m.id = any (chosen))
       and (n2.source in ('estimated', 'database_provided', 'unknown') or coalesce(i.disclose_nutrition, false))
       and exists (select 1 from public.business_locations l where l.business_id = b.id and l.city_slug = p_city)
       and (not s.light or n2.calories <= 400)
     order by abs(n2.calories - target * mult * s.share) / (target * mult * s.share)
              - least(coalesce(n2.protein_g, 0) / greatest(n2.calories, 1) * 4, 0.6)   -- more protein per calorie ranks higher
              + random() * 0.15
     limit 1;
    if pick.id is null then continue; end if;
    chosen := array_append(chosen, pick.id);
    insert into public.meal_plan_items (user_id, day, slot, at_time, menu_item_id, name, calories, protein_g, carbs_g, fat_g, nutrition_source)
    values (uid, p_day, s.slot, s.at_time, pick.id, pick.name, pick.calories, pick.protein_g,
            case when can_plus then pick.carbs_g end, case when can_plus then pick.fat_g end, pick.source);
    n := n + 1;
    pick := null;
  end loop;
  return n;
end;
$$;
grant execute on function public.suggest_meal_plan(text, date, text) to authenticated;

-- Mark a planned meal as eaten: it goes into the food log too.
create or replace function public.eat_planned_meal(p_item uuid)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  it public.meal_plan_items;
begin
  select * into it from public.meal_plan_items where id = p_item and user_id = auth.uid() for update;
  if not found then raise exception 'not found' using errcode = 'P0002'; end if;
  if it.eaten_at is not null then return; end if;
  update public.meal_plan_items set eaten_at = now() where id = it.id;
  insert into public.food_logs (user_id, menu_item_id, name, calories, protein_g, carbs_g, fat_g, nutrition_source)
  values (it.user_id, it.menu_item_id, it.name, it.calories, it.protein_g, it.carbs_g, it.fat_g, it.nutrition_source);
end;
$$;
grant execute on function public.eat_planned_meal(uuid) to authenticated;

-- ═════ 20261006000100_sleep_checkins.sql ═════
-- VYBR8 · Sleep & activity check-ins
--
-- No health apps needed. Each day a person can:
-- • log sleep: when they went to bed, when they woke up, and how rested they feel;
-- • check in how the day went: very active, active, light, mostly sitting, gaming/screen day or rest day,
--   what they did, and roughly how many steps or miles (optional).
-- Private to the person, always. Wellness information, not medical advice.

create table public.sleep_logs (
  user_id     uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  day         date not null,                        -- the morning they woke up
  bed_time    time not null,
  wake_time   time not null,
  minutes     integer not null check (minutes between 30 and 1080),   -- 30 min to 18 h
  quality     smallint check (quality between 1 and 5),
  updated_at  timestamptz not null default now(),
  primary key (user_id, day)
);

create table public.activity_checkins (
  user_id     uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  day         date not null,
  level       text not null check (level in ('very_active', 'active', 'light', 'sitting', 'gaming', 'rest')),
  activities  text[] not null default '{}' check (cardinality(activities) <= 8),
  steps_band  text check (steps_band in ('under_3k', '3k_7k', '7k_12k', '12k_plus')),
  miles       numeric(4,1) check (miles between 0 and 100),
  note        text check (char_length(note) <= 200),
  updated_at  timestamptz not null default now(),
  primary key (user_id, day)
);

alter table public.activity_goals add column sleep_goal_minutes integer not null default 480 check (sleep_goal_minutes between 240 and 720);

alter table public.sleep_logs enable row level security;
alter table public.activity_checkins enable row level security;
create policy "sleep_logs: owner only" on public.sleep_logs for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "activity_checkins: owner only" on public.activity_checkins for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- ═════ 20261007000100_miami.sql ═════
-- VYBR8 · Add Miami as the 8th launch city.
insert into public.cities (slug, name, region, timezone, center_lat, center_lng, north, south, east, west, position) values
  ('miami', 'Miami', 'FL', 'America/New_York', 25.761700, -80.191800, 25.870000, 25.700000, -80.120000, -80.320000, 8)
on conflict (slug) do update set name = excluded.name, region = excluded.region, timezone = excluded.timezone,
  center_lat = excluded.center_lat, center_lng = excluded.center_lng, north = excluded.north, south = excluded.south,
  east = excluded.east, west = excluded.west, position = excluded.position, is_active = true;

-- ═════ 20261008000100_food_journal.sql ═════
-- VYBR8 · "Have you already ate?" food & drink journal on Active Vybe
--
-- Anyone can jot down what they ate and drank today, with or without a VYBR8 dish:
-- water (ounces), any drink, any food, and when (early morning … midnight munch).
-- Rows live in food_logs, which is already owner-only (never shared).

alter table public.food_logs
  add column kind      text not null default 'food' check (kind in ('food', 'drink', 'water')),
  add column time_slot text check (time_slot in (
    'early_morning', 'before_work', 'morning', 'breakfast', 'lunch', 'happy_hour', 'dinner', 'late_night_snack', 'midnight_munch')),
  add column day       date,                                                  -- the day it counts toward (the person's local day)
  add column amount    text check (amount is null or char_length(trim(amount)) between 1 and 40),   -- "2 slices", "a big bowl"
  add column ounces    numeric(5,1) check (ounces is null or (ounces > 0 and ounces <= 200)),
  add check (kind <> 'water' or ounces is not null);

create index food_logs_user_date_idx on public.food_logs (user_id, day);

-- ═════ 20261009000100_vybe_schedule.sql ═════
-- VYBR8 · My Vybe Schedule, morning/midday/night check-ins, and check-in reminders
--
-- • A person's rhythm: when they usually wake up and go to bed. Night-shift workers get their own
--   "morning" (right after they wake), so the Health tab follows their day, not the clock on the wall.
-- • Repeating schedule blocks ("Work, Mon–Fri, 9–5, mostly sitting") count toward the day automatically.
-- • Check-ins happen up to three times a day: morning, midday and night.
-- • Reminders land in the Alerts bell for any check-in not done yet.
-- Private to the person, always. Wellness information, not medical advice.

alter table public.activity_goals
  add column usual_wake time not null default '07:00',
  add column usual_bed  time not null default '23:00',
  add column reminders  text[] not null default '{morning,midday,night}'
    check (reminders <@ array['morning', 'midday', 'night']::text[]);

create table public.vybe_schedule (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  label       text not null check (char_length(trim(label)) between 1 and 40),
  level       text not null check (level in ('very_active', 'active', 'light', 'sitting', 'gaming', 'rest')),
  days        smallint[] not null check (cardinality(days) between 1 and 7 and days <@ array[0,1,2,3,4,5,6]::smallint[]),  -- 0 = Sunday
  start_time  time not null,
  end_time    time not null check (end_time <> start_time),   -- an earlier end time means it runs overnight
  created_at  timestamptz not null default now()
);
create index vybe_schedule_user_idx on public.vybe_schedule (user_id);

create or replace function private.vybe_schedule_limit()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select count(*) from public.vybe_schedule where user_id = new.user_id) >= 20 then
    raise exception 'up to 20 schedule blocks' using errcode = '23514';
  end if;
  return new;
end;
$$;
create trigger vybe_schedule_limit before insert on public.vybe_schedule
  for each row execute function private.vybe_schedule_limit();

alter table public.vybe_schedule enable row level security;
create policy "vybe_schedule: owner only" on public.vybe_schedule for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- Check-ins: one per part of the day instead of one per day. Earlier check-ins become "midday".
alter table public.activity_checkins
  add column part text not null default 'midday' check (part in ('morning', 'midday', 'night'));
alter table public.activity_checkins drop constraint activity_checkins_pkey;
alter table public.activity_checkins add primary key (user_id, day, part);

-- A check-in reminder for the signed-in person, when they use Active Vybe, have that reminder on,
-- and haven't checked in yet. Once per day and part.
create or replace function public.checkin_reminder(p_day date, p_part text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  me uuid := (select auth.uid());
  n  integer;
begin
  if me is null or p_part not in ('morning', 'midday', 'night') or abs(p_day - current_date) > 1 then return false; end if;
  if not exists (select 1 from public.activity_goals g where g.user_id = me and p_part = any (g.reminders)) then return false; end if;
  if exists (select 1 from public.activity_checkins c where c.user_id = me and c.day = p_day and c.part = p_part) then return false; end if;

  insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
  values (me, 'health.checkin',
    case p_part when 'morning' then 'Good Morning, Let''s Vybe' when 'midday' then 'How''s the Vybe Going?' else 'Time to Let the Vybes Rest' end,
    case p_part
      when 'morning' then 'Log how you slept and set up your day.'
      when 'midday'  then 'Check in: what have you been up to, and have you already ate?'
      else 'Wrap up your day: how active was it and what did you eat and drink?' end,
    '/health', 'health.checkin.' || p_day::text || '.' || p_part)
  on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;
  get diagnostics n = row_count;
  return n > 0;
end;
$$;
revoke all on function public.checkin_reminder(date, text) from public, anon;
grant execute on function public.checkin_reminder(date, text) to authenticated;

-- ═════ 20261010000100_support.sql ═════
-- VYBR8 · Help & support: messages to the VYBR8 Team
--
-- Anyone can write in, signed in or not (people who can't sign in need help the most).
-- The sender sees their own messages; the VYBR8 Team (admins and moderators) sees and answers all of them.
-- Replies go out by email from support@vybr8.live.

create table public.support_tickets (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid default auth.uid() references public.profiles (id) on delete set null,
  email       text not null check (email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' and char_length(email) <= 254),
  name        text check (name is null or char_length(trim(name)) between 1 and 80),
  topic       text not null check (topic in ('account', 'sign_in', 'business', 'claim', 'max', 'bug', 'idea', 'privacy', 'safety', 'other')),
  message     text not null check (char_length(trim(message)) between 10 and 2000),
  page        text check (page is null or (page ~ '^/' and char_length(page) <= 200)),
  status      text not null default 'open' check (status in ('open', 'answered', 'closed')),
  staff_note  text check (staff_note is null or char_length(staff_note) <= 2000),
  handled_by  uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index support_tickets_status_idx on public.support_tickets (status, created_at);
create index support_tickets_user_idx on public.support_tickets (user_id, created_at desc);
create index support_tickets_email_idx on public.support_tickets (lower(email), created_at desc);

-- New messages: fair limits, clean fields, and a heads-up for the team.
create or replace function private.support_ticket_new()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.email := lower(trim(new.email));
  new.status := 'open';
  new.staff_note := null;
  new.handled_by := null;
  new.created_at := now();
  new.updated_at := now();
  if (select count(*) from public.support_tickets t
       where (t.email = new.email or (new.user_id is not null and t.user_id = new.user_id))
         and t.created_at > now() - interval '1 day') >= 5 then
    raise exception 'too many messages today' using errcode = '23514';
  end if;
  if (select count(*) from public.support_tickets t where t.user_id is null and t.created_at > now() - interval '1 hour') >= 60
     and new.user_id is null then
    raise exception 'too many messages right now' using errcode = '23514';
  end if;
  return new;
end;
$$;
create trigger support_ticket_new before insert on public.support_tickets
  for each row execute function private.support_ticket_new();

create or replace function private.support_ticket_notify()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
  select distinct r.user_id, 'support.new', 'New support message',
         left(format('%s: %s', replace(initcap(replace(new.topic, '_', ' ')), 'Max', 'MAX'), new.message), 200),
         '/admin/support', 'support.new.' || new.id::text
    from public.user_roles r
   where r.role in ('admin', 'moderator')
  on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;
  return null;
end;
$$;
create trigger support_ticket_notify after insert on public.support_tickets
  for each row execute function private.support_ticket_notify();

-- Only the team changes a message after it's sent, and only its status and notes.
create or replace function private.support_ticket_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select auth.uid()) is null then return new; end if;
  if new.user_id is distinct from old.user_id or new.email <> old.email or new.name is distinct from old.name
  or new.topic <> old.topic or new.message <> old.message or new.page is distinct from old.page or new.created_at <> old.created_at then
    raise exception 'only status and notes can change' using errcode = '42501';
  end if;
  new.handled_by := (select auth.uid());
  new.updated_at := now();
  return new;
end;
$$;
create trigger support_ticket_guard before update on public.support_tickets
  for each row execute function private.support_ticket_guard();

alter table public.support_tickets enable row level security;
create policy "support_tickets: anyone writes in" on public.support_tickets for insert to anon, authenticated
  with check (user_id is null and (select auth.uid()) is null or user_id = (select auth.uid()));
create policy "support_tickets: sender or team reads" on public.support_tickets for select to authenticated
  using (user_id = (select auth.uid()) or private.is_staff());
create policy "support_tickets: team updates" on public.support_tickets for update to authenticated
  using (private.is_staff()) with check (private.is_staff());
-- Nobody deletes: the history stays for the team.

-- ═════ 20261011000100_osm_import.sql ═════
-- VYBR8 · Real places from OpenStreetMap
--
-- The VYBR8 Team imports real restaurants, bars, cafes and more for each city from OpenStreetMap
-- (open data, © OpenStreetMap contributors, ODbL). Imported places are listed right away but aren't
-- "VYBR8 Approved" until the owner claims them. Places already on VYBR8 are matched, never duplicated.
-- (Google Places data can't be stored or shown on a non-Google map under Google's terms, so it isn't used here.)

alter table public.businesses drop constraint businesses_source_check;
alter table public.businesses add constraint businesses_source_check
  check (source in ('vybr8', 'community', 'owner', 'google', 'foursquare', 'osm'));
alter table public.businesses add column cuisines text[] not null default '{}' check (cardinality(cuisines) <= 8);

alter table public.place_external_ids drop constraint place_external_ids_provider_check;
alter table public.place_external_ids add constraint place_external_ids_provider_check
  check (provider in ('google', 'foursquare', 'mapbox', 'osm'));

-- Name matching ignores "and" / "&" too: "Mert's Heart and Soul" = "Merts Heart & Soul".
create or replace function private.norm_name(p text)
returns text language sql immutable set search_path = ''
as $$ select regexp_replace(regexp_replace(regexp_replace(lower(coalesce(p, '')), '^the\s+', ''), '(\mand\M|&)', '', 'g'), '[^a-z0-9]', '', 'g'); $$;

create index business_locations_city_lat_idx on public.business_locations (city_slug, latitude);
create index if not exists posts_business_idx on public.posts (business_id) where business_id is not null;

-- Import one batch of places for a city. Admin only. Rows come from the server, already cleaned:
-- [{ "ext": "node/123", "name": "...", "kind": "restaurant", "lat": 35.2, "lng": -80.8, "address": "1200 South Blvd",
--    "postal": "28203", "website": "https://...", "phone": "...", "brand": "Chick-fil-A", "cuisines": ["chicken"],
--    "hours": [{ "weekday": 1, "opens": "11:00", "closes": "22:00" }] }]
create or replace function public.import_places(p_city text, p_rows jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  c public.cities;
  r jsonb;
  h jsonb;
  v_name text; v_kind public.business_kind; v_lat numeric; v_lng numeric; v_addr text; v_brand text; v_web text;
  biz uuid; loc uuid; brand uuid; branch text; new_slug text;
  added int := 0; matched int := 0; known int := 0; skipped int := 0;
  errs text[] := '{}';
begin
  if not private.is_admin() then raise exception 'admins only' using errcode = '42501'; end if;
  select * into c from public.cities where slug = p_city;
  if not found then raise exception 'unknown city' using errcode = '22023'; end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 500 then raise exception 'send up to 500 places at a time' using errcode = '22023'; end if;

  for r in select * from jsonb_array_elements(p_rows) loop
    begin
      v_name := left(trim(coalesce(r ->> 'name', '')), 120);
      v_lat := (r ->> 'lat')::numeric; v_lng := (r ->> 'lng')::numeric;
      v_addr := nullif(left(trim(coalesce(r ->> 'address', '')), 160), '');
      v_brand := nullif(left(trim(coalesce(r ->> 'brand', '')), 120), '');
      v_web := case when r ->> 'website' ~ '^https://[^\s]+\.[^\s]+$' and char_length(r ->> 'website') <= 300 then r ->> 'website' end;
      if char_length(v_name) < 2 or v_lat is null or v_lng is null or coalesce(r ->> 'ext', '') = ''
         or v_lat not between c.south - 0.05 and c.north + 0.05 or v_lng not between c.west - 0.05 and c.east + 0.05 then
        skipped := skipped + 1; continue;
      end if;
      v_kind := (r ->> 'kind')::public.business_kind;

      -- Already imported?
      if exists (select 1 from public.place_external_ids where provider = 'osm' and external_id = r ->> 'ext') then
        known := known + 1; continue;
      end if;

      -- Already on VYBR8 (added by someone, claimed, or the same place imported under another id)?
      select b.id, l.id into biz, loc
        from public.business_locations l join public.businesses b on b.id = l.business_id
       where l.city_slug = c.slug and b.deleted_at is null
         and l.latitude between v_lat - 0.0015 and v_lat + 0.0015
         and l.longitude between v_lng - 0.002 and v_lng + 0.002
         and (private.norm_name(b.name) = private.norm_name(v_name)
              or (length(private.norm_name(v_name)) >= 4 and private.norm_name(b.name) like '%' || private.norm_name(v_name) || '%')
              or (length(private.norm_name(b.name)) >= 4 and private.norm_name(v_name) like '%' || private.norm_name(b.name) || '%'))
       limit 1;
      if biz is not null then
        insert into public.place_external_ids (provider, external_id, business_id, location_id) values ('osm', r ->> 'ext', biz, loc)
        on conflict do nothing;
        matched := matched + 1; biz := null; loc := null; continue;
      end if;

      -- Franchise brand: shared across locations, each location told apart by its street.
      brand := null;
      if v_brand is not null then
        select id into brand from public.brands where private.norm_name(name) = private.norm_name(v_brand) limit 1;
        if brand is null then
          insert into public.brands (slug, name) values (private.unique_brand_slug(v_brand)::extensions.citext, v_brand) returning id into brand;
        end if;
      end if;
      branch := case when brand is not null or exists (select 1 from public.businesses x where private.norm_name(x.name) = private.norm_name(v_name) and x.deleted_at is null)
                     then private.street_name(v_addr) end;
      new_slug := private.unique_business_slug(v_name || ' ' || coalesce(branch, '') || ' ' || c.slug);

      insert into public.businesses (slug, name, kind, website, phone, status, source, branch_name, brand_id, cuisines)
      values (new_slug::extensions.citext, v_name, v_kind, v_web, nullif(left(r ->> 'phone', 40), ''), 'active', 'osm', branch, brand,
              coalesce((select array_agg(left(x, 30)) from (select jsonb_array_elements_text(coalesce(r -> 'cuisines', '[]')) x limit 8) s), '{}'))
      returning id into biz;

      insert into public.business_locations (business_id, label, address_line1, city, region, postal_code, latitude, longitude, timezone, city_slug, is_primary)
      values (biz, branch, v_addr, split_part(c.name, ',', 1), c.region, nullif(left(r ->> 'postal', 10), ''), round(v_lat, 6), round(v_lng, 6), c.timezone, c.slug, true)
      returning id into loc;

      insert into public.place_external_ids (provider, external_id, business_id, location_id) values ('osm', r ->> 'ext', biz, loc);

      for h in select * from jsonb_array_elements(coalesce(r -> 'hours', '[]')) loop
        insert into public.business_hours (location_id, weekday, opens_at, closes_at)
        values (loc, (h ->> 'weekday')::smallint, (h ->> 'opens')::time, (h ->> 'closes')::time)
        on conflict do nothing;
      end loop;

      added := added + 1; biz := null; loc := null;
    exception when others then
      skipped := skipped + 1; biz := null; loc := null;
      if cardinality(errs) < 5 then errs := errs || left(coalesce(r ->> 'name', '?') || ': ' || sqlerrm, 200); end if;
    end;
  end loop;

  insert into public.audit_logs (actor_id, action, entity_type, metadata)
  values ((select auth.uid()), 'places.imported', 'city', jsonb_build_object('city', c.slug, 'added', added, 'matched', matched, 'known', known, 'skipped', skipped));

  return jsonb_build_object('added', added, 'matched', matched, 'known', known, 'skipped', skipped, 'errors', to_jsonb(errs));
end;
$$;
revoke all on function public.import_places(text, jsonb) from public, anon;
grant execute on function public.import_places(text, jsonb) to authenticated;

create or replace function private.unique_brand_slug(p_base text)
returns text language plpgsql stable set search_path = ''
as $$
declare
  base text := coalesce(nullif(private.slugify(p_base), ''), 'brand');
  candidate text := base;
  n int := 1;
begin
  while exists (select 1 from public.brands where slug = candidate::extensions.citext) loop
    n := n + 1;
    candidate := left(base, 70) || '-' || n;
  end loop;
  return candidate;
end;
$$;
grant execute on function private.unique_brand_slug(text) to authenticated, service_role;

-- How many places each city has, for the import page.
create or replace function public.city_place_counts()
returns table (city_slug text, places bigint, imported bigint)
language sql stable security definer
set search_path = ''
as $$
  select l.city_slug, count(distinct b.id), count(distinct b.id) filter (where b.source = 'osm')
    from public.business_locations l join public.businesses b on b.id = l.business_id
   where b.deleted_at is null and b.status = 'active' and l.city_slug is not null and private.is_admin()
   group by l.city_slug;
$$;
grant execute on function public.city_place_counts() to authenticated;

-- The Vybe Map shows the places people care about first: claimed places, then the most posted-about.
create or replace function public.map_location_ids(p_city text, p_limit int default 250)
returns setof uuid
language sql stable
set search_path = ''
as $$
  select l.id
    from public.business_locations l
    join public.businesses b on b.id = l.business_id
   where l.city_slug = p_city and l.latitude is not null and b.deleted_at is null
   order by b.is_claimed desc,
            (select count(*) from public.posts p where p.business_id = b.id) desc,
            (b.source <> 'osm') desc,
            l.id
   limit least(greatest(p_limit, 1), 400);
$$;
grant execute on function public.map_location_ids(text, int) to anon, authenticated;

-- ═════ 20261012000100_places_near.sql ═════
-- VYBR8 · "What Should I Eat?": every place near you, rated or not, with your tastes on top
--
-- Lists all active places in a city by distance from you (or from downtown), with filters for the kind of
-- place, cuisine, open now and a name search. People who saved their tastes (likes / won't eat) see what
-- matches first, but never lose the rest of the list. VYBR8 ratings show when a place has them.

create or replace function public.places_near(
  p_city     text,
  p_lat      numeric default null,
  p_lng      numeric default null,
  p_kinds    text[] default null,       -- null = every kind
  p_cuisine  text default null,
  p_q        text default null,
  p_open_now boolean default false,
  p_likes    text[] default '{}',
  p_dislikes text[] default '{}',
  p_sort     text default 'near',       -- near | for_you | top
  p_limit    int default 30,
  p_offset   int default 0
)
returns table (
  business_id uuid, slug text, name text, branch_name text, kind text, cuisines text[], price_level smallint,
  approved boolean, logo_url text, address text, lat numeric, lng numeric, meters double precision,
  open_now boolean, rating numeric, ratings int, match int
)
language sql stable
set search_path = ''
as $$
  with c as (select * from public.cities where slug = p_city),
  base as (
    select b.id, b.slug::text, b.name, b.branch_name, b.kind::text, b.cuisines, b.price_level, b.is_claimed, b.logo_url,
           l.address_line1, l.latitude, l.longitude, l.id as loc, l.timezone,
           private.meters_between(l.latitude, l.longitude, coalesce(p_lat, (select center_lat from c)), coalesce(p_lng, (select center_lng from c))) as meters,
           lower(b.name || ' ' || replace(array_to_string(b.cuisines, ' '), '_', ' ') || ' ' || replace(b.kind::text, '_', ' ')) as hay
      from public.businesses b
      join public.business_locations l on l.business_id = b.id and l.is_primary
     where l.city_slug = p_city and l.latitude is not null
       and b.status = 'active' and b.deleted_at is null
       and (p_kinds is null or b.kind::text = any (p_kinds))
       and (p_cuisine is null or p_cuisine = any (b.cuisines))
       and (p_q is null or b.name ilike '%' || p_q || '%')
  ),
  scored as (
    select base.*,
      (select case when count(*) = 0 then null else bool_or(
          (h.opens_at < h.closes_at and h.weekday = extract(dow from (now() at time zone base.timezone))::int
             and (now() at time zone base.timezone)::time >= h.opens_at and (now() at time zone base.timezone)::time < h.closes_at)
          or (h.opens_at >= h.closes_at and (
               (h.weekday = extract(dow from (now() at time zone base.timezone))::int and (now() at time zone base.timezone)::time >= h.opens_at)
            or (h.weekday = (extract(dow from (now() at time zone base.timezone))::int + 6) % 7 and (now() at time zone base.timezone)::time < h.closes_at))))
        end
         from public.business_hours h where h.location_id = base.loc) as open_now,
      (select count(*) from unnest(p_likes) x where length(x) >= 3 and position(lower(x) in base.hay) > 0)::int
        - 2 * (select count(*) from unnest(p_dislikes) x where length(x) >= 3 and position(lower(x) in base.hay) > 0)::int as match
      from base
  ),
  rated as (
    select s.*, r.rating, coalesce(r.n, 0)::int as ratings
      from scored s
      left join lateral (
        select round(avg(p.rating), 1) as rating, count(*) as n
          from public.posts p
         where p.business_id = s.id and p.rating is not null and p.deleted_at is null and p.status = 'published'
      ) r on true
     where not p_open_now or s.open_now is true
  )
  select id, slug, name, branch_name, kind, cuisines, price_level, is_claimed, logo_url, address_line1, latitude, longitude,
         round(meters::numeric)::double precision, open_now, rating, ratings, match
    from rated
   order by
     case when p_sort = 'for_you' then match end desc nulls last,
     case when p_sort = 'top' then (ratings > 0) end desc nulls last,
     case when p_sort = 'top' then rating end desc nulls last,
     meters asc, name
   limit least(greatest(p_limit, 1), 60) offset greatest(p_offset, 0);
$$;
grant execute on function public.places_near(text, numeric, numeric, text[], text, text, boolean, text[], text[], text, int, int) to anon, authenticated;

-- The cuisines in a city, most common first (for the filter chips).
create or replace function public.city_cuisines(p_city text, p_limit int default 16)
returns table (cuisine text, places bigint)
language sql stable
set search_path = ''
as $$
  select x, count(*)
    from public.businesses b
    join public.business_locations l on l.business_id = b.id and l.is_primary
    cross join lateral unnest(b.cuisines) x
   where l.city_slug = p_city and b.status = 'active' and b.deleted_at is null
   group by x
   order by count(*) desc, x
   limit least(greatest(p_limit, 1), 40);
$$;
grant execute on function public.city_cuisines(text, int) to anon, authenticated;

-- ═════ 20261013000100_closed_places.sql ═════
-- VYBR8 · Permanently closed places
--
-- • The VYBR8 Team marks a place permanently closed in one tap: it disappears from lists, the map and search.
-- • Anyone signed in can report "closed for good". Three different people within 90 days hide it automatically,
--   and it shows on the Admin page so the team can confirm or bring it back.
-- • Nothing is deleted: a place that reopens (or was reported by mistake) comes back with its history.

alter table public.businesses add column closed_at timestamptz;

create table public.place_closure_reports (
  business_id  uuid not null references public.businesses (id) on delete cascade,
  user_id      uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  created_at   timestamptz not null default now(),
  primary key (business_id, user_id)
);
alter table public.place_closure_reports enable row level security;
create policy "place_closure_reports: see your own, team sees all" on public.place_closure_reports for select to authenticated
  using (user_id = (select auth.uid()) or private.is_staff());
-- Reports are made through report_place_closed() only.

-- Trusted database functions may change a place's status on their own (the guard below lets them through).
create or replace function private.businesses_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select auth.uid()) is null or private.is_admin() or current_setting('vybr8.trusted', true) = 'on' then return new; end if;
  if new.is_claimed  is distinct from old.is_claimed
  or new.is_demo     is distinct from old.is_demo
  or new.slug        is distinct from old.slug
  or new.deleted_at  is distinct from old.deleted_at
  or new.created_by  is distinct from old.created_by
  or new.source      is distinct from old.source
  or new.approved_at is distinct from old.approved_at
  or new.closed_at   is distinct from old.closed_at then
    raise exception 'claim, approval, demo, slug, source, closure and deletion fields are admin-only' using errcode = '42501';
  end if;
  if (new.status is distinct from old.status or new.brand_id is distinct from old.brand_id) and not private.is_staff() then
    raise exception 'publishing a place and linking brands is done by the VYBR8 Team' using errcode = '42501';
  end if;
  return new;
end;
$$;

-- "Closed for good?" The team's report closes it right away; three people's reports close it too.
create or replace function public.report_place_closed(p_business uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  me uuid := (select auth.uid());
  n int;
begin
  if me is null then raise exception 'sign in to report a place' using errcode = '42501'; end if;
  if not exists (select 1 from public.businesses where id = p_business and status = 'active' and deleted_at is null) then
    return 'already_hidden';
  end if;
  if exists (select 1 from public.businesses b where b.id = p_business and b.is_claimed) and not private.is_staff() then
    -- An owner runs this listing: send it to the team instead of hiding it automatically.
    insert into public.place_closure_reports (business_id, user_id) values (p_business, me) on conflict do nothing;
    return 'reported';
  end if;
  insert into public.place_closure_reports (business_id, user_id) values (p_business, me) on conflict do nothing;
  select count(*) into n from public.place_closure_reports where business_id = p_business and created_at > now() - interval '90 days';
  if private.is_staff() or n >= 3 then
    perform set_config('vybr8.trusted', 'on', true);
    update public.businesses set status = 'hidden', closed_at = now() where id = p_business;
    perform set_config('vybr8.trusted', 'off', true);
    insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
    values (me, 'place.closed', 'business', p_business, jsonb_build_object('reports', n, 'by_team', private.is_staff()));
    return 'closed';
  end if;
  return 'reported';
end;
$$;
revoke all on function public.report_place_closed(uuid) from public, anon;
grant execute on function public.report_place_closed(uuid) to authenticated;

-- The team confirms a closure, or brings the place back (clearing the reports).
create or replace function public.review_place_closure(p_business uuid, p_closed boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.is_staff() then raise exception 'VYBR8 Team only' using errcode = '42501'; end if;
  perform set_config('vybr8.trusted', 'on', true);
  if p_closed then
    update public.businesses set status = 'hidden', closed_at = coalesce(closed_at, now()) where id = p_business;
  else
    update public.businesses set status = 'active', closed_at = null where id = p_business and deleted_at is null;
    delete from public.place_closure_reports where business_id = p_business;
  end if;
  perform set_config('vybr8.trusted', 'off', true);
  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values ((select auth.uid()), case when p_closed then 'place.closure_confirmed' else 'place.reopened' end, 'business', p_business, '{}');
end;
$$;
revoke all on function public.review_place_closure(uuid, boolean) from public, anon;
grant execute on function public.review_place_closure(uuid, boolean) to authenticated;

-- For the Admin page: places people reported, newest first.
create or replace function public.closure_report_queue()
returns table (business_id uuid, slug text, name text, branch_name text, status text, closed_at timestamptz, reports bigint, last_report timestamptz)
language sql stable security definer
set search_path = ''
as $$
  select b.id, b.slug::text, b.name, b.branch_name, b.status::text, b.closed_at, count(*), max(r.created_at)
    from public.place_closure_reports r join public.businesses b on b.id = r.business_id
   where private.is_staff() and b.deleted_at is null and r.created_at > now() - interval '90 days'
   group by b.id
   order by max(r.created_at) desc
   limit 100;
$$;
grant execute on function public.closure_report_queue() to authenticated;

-- ═════ 20261014000100_hours_editing.sql ═════
-- VYBR8 · Adding and fixing opening hours
--
-- • Owners of a claimed place and the VYBR8 Team set hours directly.
-- • Anyone signed in who knows the hours (walked by, works there, called) can suggest them.
--   Suggestions go to the Admin page; approving one puts the hours live.

create table public.hours_suggestions (
  id           uuid primary key default gen_random_uuid(),
  location_id  uuid not null references public.business_locations (id) on delete cascade,
  user_id      uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  hours        jsonb not null check (jsonb_typeof(hours) = 'array' and jsonb_array_length(hours) <= 21),
  note         text check (note is null or char_length(note) <= 200),
  status       text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  reviewed_by  uuid references public.profiles (id) on delete set null,
  created_at   timestamptz not null default now()
);
create index hours_suggestions_pending_idx on public.hours_suggestions (created_at) where status = 'pending';
alter table public.hours_suggestions enable row level security;
create policy "hours_suggestions: yours, and the team sees all" on public.hours_suggestions for select to authenticated
  using (user_id = (select auth.uid()) or private.is_staff());
-- Written through submit_place_hours() and review_hours_suggestion() only.

-- Replace a location's hours with a clean list. [{ "weekday": 1, "opens": "11:00", "closes": "22:00" }, …]
create or replace function private.apply_hours(p_location uuid, p_hours jsonb)
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  h jsonb; n int := 0;
begin
  delete from public.business_hours where location_id = p_location;
  for h in select * from jsonb_array_elements(p_hours) loop
    insert into public.business_hours (location_id, weekday, opens_at, closes_at)
    values (p_location, (h ->> 'weekday')::smallint, (h ->> 'opens')::time, (h ->> 'closes')::time)
    on conflict do nothing;
    n := n + 1;
  end loop;
  return n;
end;
$$;

-- Check the list before anything is saved: real weekdays and real times.
create or replace function private.valid_hours(p_hours jsonb)
returns boolean
language plpgsql immutable
set search_path = ''
as $$
declare h jsonb;
begin
  if jsonb_typeof(p_hours) <> 'array' or jsonb_array_length(p_hours) > 21 then return false; end if;
  for h in select * from jsonb_array_elements(p_hours) loop
    if (h ->> 'weekday')::int not between 0 and 6 then return false; end if;
    if h ->> 'opens' !~ '^([01]\d|2[0-3]):[0-5]\d$' or h ->> 'closes' !~ '^([01]\d|2[0-3]):[0-5]\d$' then return false; end if;
  end loop;
  return true;
exception when others then return false;
end;
$$;

-- Owners and the team: saved right away. Everyone else: a suggestion for the team to check.
create or replace function public.submit_place_hours(p_location uuid, p_hours jsonb, p_note text default null)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  me uuid := (select auth.uid());
  biz uuid;
begin
  if me is null then raise exception 'sign in to add hours' using errcode = '42501'; end if;
  if not private.valid_hours(p_hours) then raise exception 'Check the days and times.' using errcode = '22023'; end if;
  select l.business_id into biz from public.business_locations l join public.businesses b on b.id = l.business_id
   where l.id = p_location and b.deleted_at is null;
  if biz is null then raise exception 'place not found' using errcode = 'P0002'; end if;

  if private.is_staff() or private.can_edit_business(biz) then
    perform private.apply_hours(p_location, p_hours);
    insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
    values (me, 'place.hours_set', 'business', biz, jsonb_build_object('location', p_location));
    return 'saved';
  end if;

  if (select count(*) from public.hours_suggestions where user_id = me and created_at > now() - interval '1 day') >= 10 then
    raise exception 'You''ve sent a lot of hours today. Thanks! Try again tomorrow.' using errcode = '22023';
  end if;
  insert into public.hours_suggestions (location_id, user_id, hours, note) values (p_location, me, p_hours, nullif(trim(p_note), ''));
  return 'suggested';
end;
$$;
revoke all on function public.submit_place_hours(uuid, jsonb, text) from public, anon;
grant execute on function public.submit_place_hours(uuid, jsonb, text) to authenticated;

create or replace function public.review_hours_suggestion(p_id uuid, p_approve boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare s public.hours_suggestions;
begin
  if not private.is_staff() then raise exception 'VYBR8 Team only' using errcode = '42501'; end if;
  select * into s from public.hours_suggestions where id = p_id and status = 'pending' for update;
  if not found then return; end if;
  if p_approve then
    perform private.apply_hours(s.location_id, s.hours);
    -- Other pending suggestions for the same place are settled by this one.
    update public.hours_suggestions set status = 'rejected', reviewed_by = (select auth.uid())
     where location_id = s.location_id and status = 'pending' and id <> s.id;
  end if;
  update public.hours_suggestions set status = case when p_approve then 'approved' else 'rejected' end, reviewed_by = (select auth.uid()) where id = s.id;
end;
$$;
revoke all on function public.review_hours_suggestion(uuid, boolean) from public, anon;
grant execute on function public.review_hours_suggestion(uuid, boolean) to authenticated;

-- Can the signed-in person edit this place (owner/manager or admin)? Used to show "Edit hours" instead of "Suggest".
create or replace function public.can_edit_place(p_business uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$ select coalesce((select auth.uid()) is not null and private.can_edit_business(p_business), false); $$;
grant execute on function public.can_edit_place(uuid) to authenticated;

-- For the Admin page: pending hours with the place they're for.
create or replace function public.hours_suggestion_queue()
returns table (id uuid, slug text, name text, branch_name text, hours jsonb, note text, username text, created_at timestamptz, current jsonb)
language sql stable security definer
set search_path = ''
as $$
  select s.id, b.slug::text, b.name, b.branch_name, s.hours, s.note, p.username::text, s.created_at,
         coalesce((select jsonb_agg(jsonb_build_object('weekday', h.weekday, 'opens', to_char(h.opens_at, 'HH24:MI'), 'closes', to_char(h.closes_at, 'HH24:MI')))
                     from public.business_hours h where h.location_id = s.location_id), '[]'::jsonb)
    from public.hours_suggestions s
    join public.business_locations l on l.id = s.location_id
    join public.businesses b on b.id = l.business_id
    left join public.profiles p on p.id = s.user_id
   where s.status = 'pending' and private.is_staff()
   order by s.created_at
   limit 100;
$$;
grant execute on function public.hours_suggestion_queue() to authenticated;

-- ═════ 20261015000100_owner_badges.sql ═════
-- VYBR8 · Owner & cause badges: Black-owned, woman-owned, Latino-owned, Asian-owned, veteran-owned, LGBTQ+-owned, gives back
--
-- • Owners of a claimed place say what applies to their business. Anyone can suggest a badge for a place they know.
-- • Every badge is checked by the VYBR8 Team before it shows. Nothing is ever guessed or assumed.
-- • Verified badges show on the place, in What Should I Eat? (with a filter for each), and on the list cards.

create table public.place_badges (
  business_id   uuid not null references public.businesses (id) on delete cascade,
  badge         text not null check (badge in ('black_owned', 'woman_owned', 'latino_owned', 'asian_owned', 'veteran_owned', 'lgbtq_owned', 'good_cause')),
  status        text not null default 'pending' check (status in ('pending', 'verified', 'rejected')),
  from_owner    boolean not null default false,          -- the owner said so (vs. someone suggesting it)
  suggestions   int not null default 1 check (suggestions >= 0),
  evidence      text check (evidence is null or char_length(evidence) <= 500),   -- a link or a few words the team can check
  submitted_by  uuid references public.profiles (id) on delete set null,
  reviewed_by   uuid references public.profiles (id) on delete set null,
  created_at    timestamptz not null default now(),
  verified_at   timestamptz,
  primary key (business_id, badge)
);
create index place_badges_verified_idx on public.place_badges (badge, business_id) where status = 'verified';
alter table public.place_badges enable row level security;
create policy "place_badges: verified are public; owners and the team see the rest" on public.place_badges for select to anon, authenticated
  using (status = 'verified' or private.is_staff() or private.can_edit_business(business_id) or submitted_by = (select auth.uid()));
-- Written through claim_place_badge() and review_place_badge() only.

-- Owner or community: "this place is Black-owned" (or another badge). Always waits for the team, except the team's own.
create or replace function public.claim_place_badge(p_business uuid, p_badge text, p_evidence text default null)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  me uuid := (select auth.uid());
  owner boolean;
  cur public.place_badges;
begin
  if me is null then raise exception 'sign in first' using errcode = '42501'; end if;
  if p_badge not in ('black_owned', 'woman_owned', 'latino_owned', 'asian_owned', 'veteran_owned', 'lgbtq_owned', 'good_cause') then
    raise exception 'Pick one of the badges.' using errcode = '22023';
  end if;
  if not exists (select 1 from public.businesses where id = p_business and status = 'active' and deleted_at is null) then
    raise exception 'place not found' using errcode = 'P0002';
  end if;
  if (select count(*) from public.place_badges where submitted_by = me and created_at > now() - interval '1 day') >= 15 then
    raise exception 'That''s a lot for one day. Thanks! Try again tomorrow.' using errcode = '22023';
  end if;
  owner := coalesce(private.can_edit_business(p_business), false);
  p_evidence := nullif(left(trim(coalesce(p_evidence, '')), 500), '');

  select * into cur from public.place_badges where business_id = p_business and badge = p_badge for update;
  if found and cur.status = 'verified' then return 'already_verified'; end if;

  if private.is_staff() then
    insert into public.place_badges (business_id, badge, status, from_owner, evidence, submitted_by, reviewed_by, verified_at)
    values (p_business, p_badge, 'verified', false, p_evidence, me, me, now())
    on conflict (business_id, badge) do update set status = 'verified', reviewed_by = me, verified_at = now(),
      evidence = coalesce(excluded.evidence, public.place_badges.evidence);
    return 'verified';
  end if;

  insert into public.place_badges (business_id, badge, status, from_owner, evidence, submitted_by)
  values (p_business, p_badge, 'pending', owner, p_evidence, me)
  on conflict (business_id, badge) do update set
    status = 'pending',
    from_owner = public.place_badges.from_owner or excluded.from_owner,
    suggestions = public.place_badges.suggestions + 1,
    evidence = coalesce(excluded.evidence, public.place_badges.evidence);

  insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
  select distinct r.user_id, 'badge.pending', 'Badge to verify',
         format('%s says %s is %s.', case when owner then 'The owner' else 'Someone' end,
                (select name from public.businesses where id = p_business), replace(p_badge, '_', '-')),
         '/admin#badges', 'badge.pending.' || p_business::text || '.' || p_badge
    from public.user_roles r where r.role in ('admin', 'moderator')
  on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;
  return 'pending';
end;
$$;
revoke all on function public.claim_place_badge(uuid, text, text) from public, anon;
grant execute on function public.claim_place_badge(uuid, text, text) to authenticated;

create or replace function public.review_place_badge(p_business uuid, p_badge text, p_approve boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.is_staff() then raise exception 'VYBR8 Team only' using errcode = '42501'; end if;
  update public.place_badges
     set status = case when p_approve then 'verified' else 'rejected' end,
         reviewed_by = (select auth.uid()), verified_at = case when p_approve then now() end
   where business_id = p_business and badge = p_badge;
end;
$$;
revoke all on function public.review_place_badge(uuid, text, boolean) from public, anon;
grant execute on function public.review_place_badge(uuid, text, boolean) to authenticated;

create or replace function public.badge_queue()
returns table (business_id uuid, slug text, name text, branch_name text, badge text, from_owner boolean, suggestions int, evidence text, created_at timestamptz)
language sql stable security definer
set search_path = ''
as $$
  select pb.business_id, b.slug::text, b.name, b.branch_name, pb.badge, pb.from_owner, pb.suggestions, pb.evidence, pb.created_at
    from public.place_badges pb join public.businesses b on b.id = pb.business_id
   where pb.status = 'pending' and private.is_staff() and b.deleted_at is null
   order by pb.from_owner desc, pb.suggestions desc, pb.created_at
   limit 100;
$$;
grant execute on function public.badge_queue() to authenticated;

-- What Should I Eat?: filter by a verified badge and show each place's verified badges.
drop function if exists public.places_near(text, numeric, numeric, text[], text, text, boolean, text[], text[], text, int, int);
create or replace function public.places_near(
  p_city     text,
  p_lat      numeric default null,
  p_lng      numeric default null,
  p_kinds    text[] default null,
  p_cuisine  text default null,
  p_q        text default null,
  p_open_now boolean default false,
  p_likes    text[] default '{}',
  p_dislikes text[] default '{}',
  p_sort     text default 'near',
  p_limit    int default 30,
  p_offset   int default 0,
  p_badge    text default null
)
returns table (
  business_id uuid, slug text, name text, branch_name text, kind text, cuisines text[], price_level smallint,
  approved boolean, logo_url text, address text, lat numeric, lng numeric, meters double precision,
  open_now boolean, rating numeric, ratings int, match int, badges text[]
)
language sql stable
set search_path = ''
as $$
  with c as (select * from public.cities where slug = p_city),
  base as (
    select b.id, b.slug::text, b.name, b.branch_name, b.kind::text, b.cuisines, b.price_level, b.is_claimed, b.logo_url,
           l.address_line1, l.latitude, l.longitude, l.id as loc, l.timezone,
           private.meters_between(l.latitude, l.longitude, coalesce(p_lat, (select center_lat from c)), coalesce(p_lng, (select center_lng from c))) as meters,
           lower(b.name || ' ' || replace(array_to_string(b.cuisines, ' '), '_', ' ') || ' ' || replace(b.kind::text, '_', ' ')) as hay
      from public.businesses b
      join public.business_locations l on l.business_id = b.id and l.is_primary
     where l.city_slug = p_city and l.latitude is not null
       and b.status = 'active' and b.deleted_at is null
       and (p_kinds is null or b.kind::text = any (p_kinds))
       and (p_cuisine is null or p_cuisine = any (b.cuisines))
       and (p_q is null or b.name ilike '%' || p_q || '%')
       and (p_badge is null or exists (select 1 from public.place_badges pb where pb.business_id = b.id and pb.badge = p_badge and pb.status = 'verified'))
  ),
  scored as (
    select base.*,
      (select case when count(*) = 0 then null else bool_or(
          (h.opens_at < h.closes_at and h.weekday = extract(dow from (now() at time zone base.timezone))::int
             and (now() at time zone base.timezone)::time >= h.opens_at and (now() at time zone base.timezone)::time < h.closes_at)
          or (h.opens_at >= h.closes_at and (
               (h.weekday = extract(dow from (now() at time zone base.timezone))::int and (now() at time zone base.timezone)::time >= h.opens_at)
            or (h.weekday = (extract(dow from (now() at time zone base.timezone))::int + 6) % 7 and (now() at time zone base.timezone)::time < h.closes_at))))
        end
         from public.business_hours h where h.location_id = base.loc) as open_now,
      (select count(*) from unnest(p_likes) x where length(x) >= 3 and position(lower(x) in base.hay) > 0)::int
        - 2 * (select count(*) from unnest(p_dislikes) x where length(x) >= 3 and position(lower(x) in base.hay) > 0)::int as match
      from base
  ),
  rated as (
    select s.*, r.rating, coalesce(r.n, 0)::int as ratings
      from scored s
      left join lateral (
        select round(avg(p.rating), 1) as rating, count(*) as n
          from public.posts p
         where p.business_id = s.id and p.rating is not null and p.deleted_at is null and p.status = 'published'
      ) r on true
     where not p_open_now or s.open_now is true
  ),
  page as (
    select * from rated
     order by
       case when p_sort = 'for_you' then match end desc nulls last,
       case when p_sort = 'top' then (ratings > 0) end desc nulls last,
       case when p_sort = 'top' then rating end desc nulls last,
       meters asc, name
     limit least(greatest(p_limit, 1), 60) offset greatest(p_offset, 0)
  )
  select pg.id, pg.slug, pg.name, pg.branch_name, pg.kind, pg.cuisines, pg.price_level, pg.is_claimed, pg.logo_url, pg.address_line1, pg.latitude, pg.longitude,
         round(pg.meters::numeric)::double precision, pg.open_now, pg.rating, pg.ratings, pg.match,
         coalesce((select array_agg(pb.badge order by pb.badge) from public.place_badges pb where pb.business_id = pg.id and pb.status = 'verified'), '{}')
    from page pg
   order by
     case when p_sort = 'for_you' then pg.match end desc nulls last,
     case when p_sort = 'top' then (pg.ratings > 0) end desc nulls last,
     case when p_sort = 'top' then pg.rating end desc nulls last,
     pg.meters asc, pg.name;
$$;
grant execute on function public.places_near(text, numeric, numeric, text[], text, text, boolean, text[], text[], text, int, int, text) to anon, authenticated;

-- ═════ 20261016000100_saved_never_again.sql ═════
-- VYBR8 · Saved places and "Never again"
--
-- • Save a place to come back to. Mark a place "Never again" after a bad experience: it disappears from your
--   recommendations (What Should I Eat?, group suggestions), and when a Link Up or group plan you're in is at that
--   place, the host or group gets a heads-up that you don't want to go back.
-- • Your lists are private. The reason you give is never shown to anyone.

create table public.place_lists (
  user_id      uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  business_id  uuid not null references public.businesses (id) on delete cascade,
  list         text not null check (list in ('saved', 'never')),
  note         text check (note is null or char_length(note) <= 200),   -- private, only you see it
  created_at   timestamptz not null default now(),
  primary key (user_id, business_id)
);
create index place_lists_business_idx on public.place_lists (business_id, list);
alter table public.place_lists enable row level security;
create policy "place_lists: yours only" on public.place_lists for select to authenticated using (user_id = (select auth.uid()));
create policy "place_lists: remove yours" on public.place_lists for delete to authenticated using (user_id = (select auth.uid()));
-- Adding goes through set_place_list() so the right people hear about a "Never again".

-- Tell the host of an upcoming Link Up / the rest of a group with an upcoming plan that someone won't go back.
create or replace function private.notify_never_again(p_user uuid, p_business uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  who text := coalesce((select '@' || username from public.profiles where id = p_user), 'Someone');
  place text := (select name from public.businesses where id = p_business);
begin
  -- Link Ups this person is going to, hosted by someone else.
  insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
  select l.host_id, 'linkup.never_again', 'Heads up about your Link Up spot',
         format('%s had a bad experience at %s and doesn''t want to go back. Maybe pick another spot?', who, place),
         '/vybe/' || l.id::text, 'never.' || l.id::text || '.' || p_user::text
    from public.linkups l
    join public.linkup_members m on m.linkup_id = l.id and m.user_id = p_user and m.status = 'going'
   where l.business_id = p_business and l.host_id <> p_user and l.status = 'active' and l.ends_at > now()
  on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;

  -- Upcoming plans at this place in groups this person is in: everyone else in the group hears.
  insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
  select gm.user_id, 'group.never_again', 'Heads up about a group plan',
         format('%s had a bad experience at %s and doesn''t want to go back. Plan: %s', who, place, gp.title),
         '/groups/' || gp.group_id::text, 'never.' || gp.id::text || '.' || p_user::text
    from public.group_plans gp
    join public.group_members me on me.group_id = gp.group_id and me.user_id = p_user and me.status = 'active'
    join public.group_members gm on gm.group_id = gp.group_id and gm.status = 'active' and gm.user_id is not null and gm.user_id <> p_user
   where gp.business_id = p_business and gp.status in ('idea', 'planned') and (gp.planned_for is null or gp.planned_for > now())
  on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;
end;
$$;

-- Save, mark "Never again", or clear (p_list = null).
create or replace function public.set_place_list(p_business uuid, p_list text, p_note text default null)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  me uuid := (select auth.uid());
begin
  if me is null then raise exception 'sign in first' using errcode = '42501'; end if;
  if p_list is null then
    delete from public.place_lists where user_id = me and business_id = p_business;
    return 'cleared';
  end if;
  if p_list not in ('saved', 'never') then raise exception 'unknown list' using errcode = '22023'; end if;
  if not exists (select 1 from public.businesses where id = p_business and deleted_at is null) then
    raise exception 'place not found' using errcode = 'P0002';
  end if;
  insert into public.place_lists (user_id, business_id, list, note) values (me, p_business, p_list, nullif(left(trim(coalesce(p_note, '')), 200), ''))
  on conflict (user_id, business_id) do update set list = excluded.list, note = coalesce(excluded.note, public.place_lists.note), created_at = now();
  if p_list = 'never' then perform private.notify_never_again(me, p_business); end if;
  return p_list;
end;
$$;
revoke all on function public.set_place_list(uuid, text, text) from public, anon;
grant execute on function public.set_place_list(uuid, text, text) to authenticated;

-- A new or moved group plan at a place someone in the group won't go back to: the person who made the plan hears.
create or replace function private.group_plan_never_check()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.business_id is null or (tg_op = 'UPDATE' and new.business_id is not distinct from old.business_id) or new.created_by is null then
    return new;
  end if;
  insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
  select new.created_by, 'group.never_again', 'Heads up about your plan',
         format('%s had a bad experience at %s and doesn''t want to go back.', coalesce('@' || p.username, 'Someone in the group'), b.name),
         '/groups/' || new.group_id::text, 'never.' || new.id::text || '.' || pl.user_id::text
    from public.group_members gm
    join public.place_lists pl on pl.user_id = gm.user_id and pl.business_id = new.business_id and pl.list = 'never'
    join public.businesses b on b.id = new.business_id
    left join public.profiles p on p.id = gm.user_id
   where gm.group_id = new.group_id and gm.status = 'active' and gm.user_id <> new.created_by
  on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;
  return new;
end;
$$;
create trigger group_plan_never_check after insert or update of business_id on public.group_plans
  for each row execute function private.group_plan_never_check();

-- The same for a Link Up: when someone joins one at a place they marked "Never again", the host hears.
create or replace function private.linkup_join_never_check()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status <> 'going' then return new; end if;
  if exists (select 1 from public.linkups l join public.place_lists pl on pl.business_id = l.business_id
              where l.id = new.linkup_id and pl.user_id = new.user_id and pl.list = 'never' and l.host_id <> new.user_id) then
    perform private.notify_never_again(new.user_id, (select business_id from public.linkups where id = new.linkup_id));
  end if;
  return new;
end;
$$;
create trigger linkup_join_never_check after insert on public.linkup_members
  for each row execute function private.linkup_join_never_check();

-- Places anyone active in a group marked "Never again" (no names): group suggestions leave them out.
create or replace function public.group_never_places(p_group uuid)
returns setof uuid
language sql stable security definer
set search_path = ''
as $$
  select distinct pl.business_id
    from public.place_lists pl
    join public.group_members gm on gm.user_id = pl.user_id and gm.group_id = p_group and gm.status = 'active'
   where pl.list = 'never'
     and exists (select 1 from public.group_members me where me.group_id = p_group and me.user_id = (select auth.uid()) and me.status = 'active');
$$;
grant execute on function public.group_never_places(uuid) to authenticated;

-- What Should I Eat? now leaves out your "Never again" places, marks your saved ones, and can show only saved.
drop function if exists public.places_near(text, numeric, numeric, text[], text, text, boolean, text[], text[], text, int, int, text);
create or replace function public.places_near(
  p_city     text,
  p_lat      numeric default null,
  p_lng      numeric default null,
  p_kinds    text[] default null,
  p_cuisine  text default null,
  p_q        text default null,
  p_open_now boolean default false,
  p_likes    text[] default '{}',
  p_dislikes text[] default '{}',
  p_sort     text default 'near',
  p_limit    int default 30,
  p_offset   int default 0,
  p_badge    text default null,
  p_saved_only boolean default false
)
returns table (
  business_id uuid, slug text, name text, branch_name text, kind text, cuisines text[], price_level smallint,
  approved boolean, logo_url text, address text, lat numeric, lng numeric, meters double precision,
  open_now boolean, rating numeric, ratings int, match int, badges text[], saved boolean
)
language sql stable
set search_path = ''
as $$
  with c as (select * from public.cities where slug = p_city),
  base as (
    select b.id, b.slug::text, b.name, b.branch_name, b.kind::text, b.cuisines, b.price_level, b.is_claimed, b.logo_url,
           l.address_line1, l.latitude, l.longitude, l.id as loc, l.timezone,
           private.meters_between(l.latitude, l.longitude, coalesce(p_lat, (select center_lat from c)), coalesce(p_lng, (select center_lng from c))) as meters,
           lower(b.name || ' ' || replace(array_to_string(b.cuisines, ' '), '_', ' ') || ' ' || replace(b.kind::text, '_', ' ')) as hay
      from public.businesses b
      join public.business_locations l on l.business_id = b.id and l.is_primary
     where l.city_slug = p_city and l.latitude is not null
       and b.status = 'active' and b.deleted_at is null
       and (p_kinds is null or b.kind::text = any (p_kinds))
       and (p_cuisine is null or p_cuisine = any (b.cuisines))
       and (p_q is null or b.name ilike '%' || p_q || '%')
       and not exists (select 1 from public.place_lists pl where pl.user_id = (select auth.uid()) and pl.business_id = b.id and pl.list = 'never')
       and (not p_saved_only or exists (select 1 from public.place_lists pl where pl.user_id = (select auth.uid()) and pl.business_id = b.id and pl.list = 'saved'))
       and (p_badge is null or exists (select 1 from public.place_badges pb where pb.business_id = b.id and pb.badge = p_badge and pb.status = 'verified'))
  ),
  scored as (
    select base.*,
      (select case when count(*) = 0 then null else bool_or(
          (h.opens_at < h.closes_at and h.weekday = extract(dow from (now() at time zone base.timezone))::int
             and (now() at time zone base.timezone)::time >= h.opens_at and (now() at time zone base.timezone)::time < h.closes_at)
          or (h.opens_at >= h.closes_at and (
               (h.weekday = extract(dow from (now() at time zone base.timezone))::int and (now() at time zone base.timezone)::time >= h.opens_at)
            or (h.weekday = (extract(dow from (now() at time zone base.timezone))::int + 6) % 7 and (now() at time zone base.timezone)::time < h.closes_at))))
        end
         from public.business_hours h where h.location_id = base.loc) as open_now,
      (select count(*) from unnest(p_likes) x where length(x) >= 3 and position(lower(x) in base.hay) > 0)::int
        - 2 * (select count(*) from unnest(p_dislikes) x where length(x) >= 3 and position(lower(x) in base.hay) > 0)::int as match
      from base
  ),
  rated as (
    select s.*, r.rating, coalesce(r.n, 0)::int as ratings
      from scored s
      left join lateral (
        select round(avg(p.rating), 1) as rating, count(*) as n
          from public.posts p
         where p.business_id = s.id and p.rating is not null and p.deleted_at is null and p.status = 'published'
      ) r on true
     where not p_open_now or s.open_now is true
  ),
  page as (
    select * from rated
     order by
       case when p_sort = 'for_you' then match end desc nulls last,
       case when p_sort = 'top' then (ratings > 0) end desc nulls last,
       case when p_sort = 'top' then rating end desc nulls last,
       meters asc, name
     limit least(greatest(p_limit, 1), 60) offset greatest(p_offset, 0)
  )
  select pg.id, pg.slug, pg.name, pg.branch_name, pg.kind, pg.cuisines, pg.price_level, pg.is_claimed, pg.logo_url, pg.address_line1, pg.latitude, pg.longitude,
         round(pg.meters::numeric)::double precision, pg.open_now, pg.rating, pg.ratings, pg.match,
         coalesce((select array_agg(pb.badge order by pb.badge) from public.place_badges pb where pb.business_id = pg.id and pb.status = 'verified'), '{}'),
         exists (select 1 from public.place_lists pl where pl.user_id = (select auth.uid()) and pl.business_id = pg.id and pl.list = 'saved')
    from page pg
   order by
     case when p_sort = 'for_you' then pg.match end desc nulls last,
     case when p_sort = 'top' then (pg.ratings > 0) end desc nulls last,
     case when p_sort = 'top' then pg.rating end desc nulls last,
     pg.meters asc, pg.name;
$$;
grant execute on function public.places_near(text, numeric, numeric, text[], text, text, boolean, text[], text[], text, int, int, text, boolean) to anon, authenticated;

-- ═════ 20261017000100_team_manager.sql ═════
-- VYBR8 · Team manager
--
-- The founder adds people to the VYBR8 Team from the app: they sign up like anyone else, then the founder adds them
-- by username with a role (Moderator or Admin) and a title for their badge. The founder can change or remove them.
-- People can also ask to join from Help & Support ("I want to join the VYBR8 Team").

-- Help & Support: a topic for people who want to join the team.
alter table public.support_tickets drop constraint support_tickets_topic_check;
alter table public.support_tickets add constraint support_tickets_topic_check
  check (topic in ('account', 'sign_in', 'business', 'claim', 'max', 'bug', 'idea', 'privacy', 'safety', 'team', 'other'));

-- Add someone (or update their role/title). Founder only.
create or replace function public.team_set_member(p_username text, p_role public.platform_role, p_title text, p_bio text default null)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  me uuid := (select auth.uid());
  who uuid;
  was_new boolean;
begin
  if not private.is_founder() then raise exception 'only the founder manages the VYBR8 Team' using errcode = '42501'; end if;
  select id into who from public.profiles where lower(username) = lower(trim(both '@ ' from coalesce(p_username, ''))) and not is_demo;
  if who is null then raise exception 'No one on VYBR8 has that username. Ask them to sign up first.' using errcode = 'P0002'; end if;
  if who = me then raise exception 'You''re already the founder.' using errcode = '22023'; end if;
  p_title := nullif(left(trim(coalesce(p_title, '')), 60), '');
  if p_title is null then raise exception 'Give them a title, like Community Team or Head of Partnerships.' using errcode = '22023'; end if;

  was_new := not exists (select 1 from public.team_members where user_id = who);
  insert into public.team_members (user_id, title, bio, position, is_public)
  values (who, p_title, nullif(left(trim(coalesce(p_bio, '')), 280), ''), 100, true)
  on conflict (user_id) do update set title = excluded.title, bio = coalesce(excluded.bio, public.team_members.bio);

  delete from public.user_roles where user_id = who and role <> p_role;
  insert into public.user_roles (user_id, role, granted_by) values (who, p_role, me) on conflict do nothing;

  insert into public.notifications (user_id, kind, title, body, link)
  values (who, 'team.added',
          case when was_new then 'Welcome to the VYBR8 Team' else 'Your VYBR8 Team role changed' end,
          format('You''re %s (%s). Your team tools are on your profile.', p_title, case p_role when 'admin' then 'Admin' else 'Moderator' end),
          '/profile');
  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values (me, 'team.member_set', 'profile', who, jsonb_build_object('role', p_role, 'title', p_title));
  return who;
end;
$$;
revoke all on function public.team_set_member(text, public.platform_role, text, text) from public, anon;
grant execute on function public.team_set_member(text, public.platform_role, text, text) to authenticated;

-- Take someone off the team: their badge and team access go away. Founder only; the founder can't remove themselves.
create or replace function public.team_remove_member(p_user uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.is_founder() then raise exception 'only the founder manages the VYBR8 Team' using errcode = '42501'; end if;
  if p_user = (select auth.uid()) then raise exception 'The founder stays on the team.' using errcode = '22023'; end if;
  delete from public.user_roles where user_id = p_user;
  delete from public.team_members where user_id = p_user;
  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values ((select auth.uid()), 'team.member_removed', 'profile', p_user, '{}');
end;
$$;
revoke all on function public.team_remove_member(uuid) from public, anon;
grant execute on function public.team_remove_member(uuid) to authenticated;

-- The roster with roles, for the founder's Team manager.
create or replace function public.team_roster()
returns table (user_id uuid, username text, display_name text, title text, role text, is_founder boolean, joined timestamptz)
language sql stable security definer
set search_path = ''
as $$
  select t.user_id, p.username::text, p.display_name, t.title,
         (select string_agg(r.role::text, ', ' order by r.role) from public.user_roles r where r.user_id = t.user_id),
         t.is_founder, t.created_at
    from public.team_members t join public.profiles p on p.id = t.user_id
   where private.is_founder()
   order by t.is_founder desc, t.position, t.created_at;
$$;
grant execute on function public.team_roster() to authenticated;

-- ═════ 20261017500100_payments.sql ═════
-- VYBR8 · Payments (Stripe)
--
-- People upgrade to VYBR8+ or MAX through Stripe Checkout. Stripe tells us what happened through a signed webhook;
-- only the server (service role) writes subscriptions. The app never trusts the browser about payment.

-- One Stripe customer per VYBR8 account (so upgrades, downgrades and receipts stay in one place).
create table public.stripe_customers (
  user_id      uuid primary key references public.profiles (id) on delete cascade,
  customer_id  text not null unique check (customer_id ~ '^cus_[A-Za-z0-9]+$'),
  created_at   timestamptz not null default now()
);
alter table public.stripe_customers enable row level security;
create policy "stripe_customers: owner reads" on public.stripe_customers for select to authenticated
  using (user_id = (select auth.uid()));
-- Writes: service role only.

-- One row per Stripe subscription.
create unique index user_subscriptions_stripe_ref_idx on public.user_subscriptions (provider_ref) where source = 'stripe';

-- Called by the Stripe webhook with the subscription's CURRENT state (fetched fresh from Stripe, so event order doesn't matter).
create or replace function public.billing_apply_stripe_subscription(
  p_user uuid, p_plan text, p_status text, p_ref text, p_period_end timestamptz)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  v_status public.subscription_status;
  v_prev   text;
begin
  if p_ref is null or p_ref !~ '^sub_[A-Za-z0-9]+$' then raise exception 'bad subscription id' using errcode = '22023'; end if;
  if not exists (select 1 from public.plans where code = p_plan and audience = 'consumer' and code <> 'free') then
    raise exception 'unknown plan' using errcode = '22023';
  end if;
  v_status := case p_status
    when 'active' then 'active' when 'trialing' then 'trialing' when 'past_due' then 'past_due'
    else 'canceled' end::public.subscription_status;

  select plan_code || ':' || status into v_prev from public.user_subscriptions where source = 'stripe' and provider_ref = p_ref;

  if v_prev is null then
    if p_status = 'incomplete' then return; end if;        -- checkout not finished yet; wait for the next event
    if not exists (select 1 from public.profiles where id = p_user) then raise exception 'unknown user' using errcode = '22023'; end if;
    insert into public.user_subscriptions (user_id, plan_code, status, source, provider_ref, current_period_end)
    values (p_user, p_plan, v_status, 'stripe', p_ref, p_period_end);
  else
    update public.user_subscriptions
       set plan_code = p_plan, status = v_status, current_period_end = p_period_end, updated_at = now()
     where source = 'stripe' and provider_ref = p_ref;
  end if;

  -- Tell them once when they're in, and once if it ends.
  if v_status in ('active', 'trialing') and (v_prev is null or v_prev <> p_plan || ':' || v_status) then
    insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
    select (select user_id from public.user_subscriptions where source = 'stripe' and provider_ref = p_ref),
           'billing.active', 'You''re on ' || p.name, 'Thanks for supporting VYBR8. Your new features are on.', '/pricing',
           'billing:' || p_ref || ':' || p_plan
      from public.plans p where p.code = p_plan
    on conflict do nothing;
  elsif v_status = 'canceled' and v_prev is not null and v_prev not like '%:canceled' then
    insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
    select user_id, 'billing.ended', 'Your plan ended', 'You''re back on VYBR8 Free. Rating is always free. Upgrade again anytime.', '/pricing',
           'billing:' || p_ref || ':ended'
      from public.user_subscriptions where source = 'stripe' and provider_ref = p_ref
    on conflict do nothing;
  end if;

  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  select null, 'billing.stripe_sync', 'profile', user_id, jsonb_build_object('plan', p_plan, 'status', p_status, 'ref', p_ref)
    from public.user_subscriptions where source = 'stripe' and provider_ref = p_ref;
end;
$$;
revoke execute on function public.billing_apply_stripe_subscription(uuid, text, text, text, timestamptz) from public, anon, authenticated;
grant execute on function public.billing_apply_stripe_subscription(uuid, text, text, text, timestamptz) to service_role;

-- What the pricing page needs: is this person paying through Stripe right now?
create or replace function public.my_billing()
returns jsonb
language sql stable security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'has_customer', exists (select 1 from public.stripe_customers where user_id = (select auth.uid())),
    'stripe_plan', (select s.plan_code from public.user_subscriptions s
                     where s.user_id = (select auth.uid()) and s.source = 'stripe' and s.status in ('active', 'trialing', 'past_due')
                     order by s.updated_at desc limit 1),
    'past_due', exists (select 1 from public.user_subscriptions s
                     where s.user_id = (select auth.uid()) and s.source = 'stripe' and s.status = 'past_due'),
    'renews', (select s.current_period_end from public.user_subscriptions s
                     where s.user_id = (select auth.uid()) and s.source = 'stripe' and s.status in ('active', 'trialing')
                     order by s.updated_at desc limit 1));
$$;
revoke execute on function public.my_billing() from public, anon;
grant execute on function public.my_billing() to authenticated;

-- ═════ 20261017600100_followers_team_requests.sql ═════
-- VYBR8 · Followers, following & mutuals · Team join requests
--
-- 1. Anyone can open a profile's Followers and Following lists, and see "Mutuals": people YOU follow who also follow them.
--    Privacy rules still apply (hidden or blocked profiles never show up), because this runs as the viewer.
-- 2. People get a heads-up when someone follows them.
-- 3. The founder answers "I want to join the VYBR8 Team" requests from the Team manager: accept (pick role and title) or decline.

-- ── Followers / following / mutuals ────────────────────────────────────
create or replace function public.profile_connections(p_user uuid, p_tab text, p_limit integer default 50, p_offset integer default 0)
returns table (id uuid, username text, display_name text, avatar_url text, i_follow boolean, follows_me boolean, since timestamptz, total bigint)
language sql stable security invoker
set search_path = ''
as $$
  with base as (
    select f.follower_id as pid, f.created_at from public.follows f
     where p_tab = 'followers' and f.followee_id = p_user
    union all
    select f.followee_id, f.created_at from public.follows f
     where p_tab = 'following' and f.follower_id = p_user
    union all
    select f.follower_id, f.created_at from public.follows f
     where p_tab = 'mutual' and f.followee_id = p_user and f.follower_id <> (select auth.uid())
       and exists (select 1 from public.follows m where m.follower_id = (select auth.uid()) and m.followee_id = f.follower_id)
  ), visible as (
    select p.id, p.username::text as username, p.display_name, p.avatar_url, b.created_at
      from base b join public.profiles p on p.id = b.pid        -- profiles RLS hides private/blocked people
  )
  select v.id, v.username, v.display_name, v.avatar_url,
         exists (select 1 from public.follows x where x.follower_id = (select auth.uid()) and x.followee_id = v.id),
         exists (select 1 from public.follows x where x.followee_id = (select auth.uid()) and x.follower_id = v.id),
         v.created_at, count(*) over ()
    from visible v
   where p_tab in ('followers', 'following', 'mutual')
   order by v.created_at desc
   limit least(greatest(coalesce(p_limit, 50), 1), 100) offset greatest(coalesce(p_offset, 0), 0);
$$;
grant execute on function public.profile_connections(uuid, text, integer, integer) to anon, authenticated;

-- "New follower" alert (one per person, even if they unfollow and follow again).
create or replace function private.follow_notify()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
  select new.followee_id, 'follow.new',
         coalesce(p.display_name, '@' || p.username::text) || ' followed you', null,
         '/profile/' || p.username::text, 'follow.' || new.follower_id::text
    from public.profiles p where p.id = new.follower_id and not p.is_demo
  on conflict do nothing;
  return new;
end;
$$;
create trigger follows_notify after insert on public.follows for each row execute function private.follow_notify();

-- ── Team join requests (support messages with the "team" topic) ────────
create or replace function public.team_join_requests()
returns table (ticket_id uuid, user_id uuid, username text, display_name text, avatar_url text, email text, message text,
               created_at timestamptz, on_team boolean)
language sql stable security definer
set search_path = ''
as $$
  select t.id, t.user_id, p.username::text, p.display_name, p.avatar_url, t.email, t.message, t.created_at,
         exists (select 1 from public.team_members m where m.user_id = t.user_id)
    from public.support_tickets t left join public.profiles p on p.id = t.user_id
   where private.is_founder() and t.topic = 'team' and t.status = 'open'
   order by t.created_at;
$$;
revoke execute on function public.team_join_requests() from public, anon;
grant execute on function public.team_join_requests() to authenticated;

create or replace function public.team_answer_request(p_ticket uuid, p_accept boolean, p_role public.platform_role default 'moderator',
                                                     p_title text default null)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  t public.support_tickets;
  uname text;
begin
  if not private.is_founder() then raise exception 'only the founder manages the VYBR8 Team' using errcode = '42501'; end if;
  select * into t from public.support_tickets where id = p_ticket and topic = 'team';
  if t.id is null then raise exception 'That request is gone.' using errcode = 'P0002'; end if;
  if t.status <> 'open' then raise exception 'That request was already answered.' using errcode = '22023'; end if;

  if p_accept then
    select username::text into uname from public.profiles where id = t.user_id;
    if uname is null then raise exception 'They wrote in without an account. Ask them to sign up, then add them by username.' using errcode = '22023'; end if;
    perform public.team_set_member(uname, p_role, coalesce(nullif(trim(p_title), ''), 'VYBR8 Team'), null);
    update public.support_tickets set status = 'answered',
           staff_note = format('Welcome aboard! You''re on the VYBR8 Team as %s.', case p_role when 'admin' then 'an Admin' else 'a Moderator' end)
     where id = t.id;
  else
    update public.support_tickets set status = 'closed',
           staff_note = 'Thank you for offering to help. We''re not adding anyone right now, but we''ll keep you in mind.'
     where id = t.id;
    if t.user_id is not null then
      insert into public.notifications (user_id, kind, title, body, link, dedupe_key)
      values (t.user_id, 'team.request', 'About joining the VYBR8 Team',
              'Thank you for offering to help. We''re not adding anyone right now, but we''ll keep you in mind.', '/help',
              'team.request.' || t.id::text)
      on conflict do nothing;
    end if;
  end if;
  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values ((select auth.uid()), case when p_accept then 'team.request_accepted' else 'team.request_declined' end, 'profile', t.user_id,
          jsonb_build_object('ticket', t.id));
end;
$$;
revoke execute on function public.team_answer_request(uuid, boolean, public.platform_role, text) from public, anon;
grant execute on function public.team_answer_request(uuid, boolean, public.platform_role, text) to authenticated;

-- ═════ 20261017700100_change_username.sql ═════
-- VYBR8 · Change your @username
--
-- People change their @ from Edit profile. Rules: 3-30 letters, numbers, _ or .; not taken; not a reserved name
-- (vybr8, admin, support…); once every 30 days (the VYBR8 Team isn't limited). Old links keep working: visiting
-- /profile/<old name> forwards to the new one, and nobody else can grab someone's old name for 90 days.

alter table public.profiles add column if not exists username_changed_at timestamptz;

create table public.username_history (
  old_username  extensions.citext primary key,
  user_id       uuid not null references public.profiles (id) on delete cascade,
  changed_at    timestamptz not null default now()
);
create index username_history_user_idx on public.username_history (user_id);
alter table public.username_history enable row level security;
-- No policies: read through username_redirect() only.

-- Usernames only change through change_username() (or by an admin).
create or replace function private.profiles_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and not private.is_admin()
     and new.is_demo is distinct from old.is_demo then
    raise exception 'is_demo can only be changed by an admin' using errcode = '42501';
  end if;
  if (select auth.uid()) is not null and not private.is_admin()
     and new.username is distinct from old.username
     and coalesce(current_setting('vybr8.username_change', true), '') <> 'on' then
    raise exception 'Change your @username from Edit profile.' using errcode = '42501';
  end if;
  return new;
end;
$$;

create or replace function public.change_username(p_new text)
returns text
language plpgsql security definer
set search_path = ''
as $$
declare
  me     uuid := (select auth.uid());
  wanted text := lower(trim(both '@ ' from coalesce(p_new, '')));
  cur    public.profiles;
  staff  boolean := private.is_staff();
begin
  if me is null then raise exception 'Sign in first.' using errcode = '42501'; end if;
  select * into cur from public.profiles where id = me;
  if wanted = lower(cur.username::text) then
    -- Same name, maybe different capitals: allowed any time.
    perform set_config('vybr8.username_change', 'on', true);
    update public.profiles set username = trim(both '@ ' from p_new) where id = me;
    return trim(both '@ ' from p_new);
  end if;
  if wanted !~ '^[a-z0-9_.]{3,30}$' then
    raise exception 'Use 3 to 30 letters, numbers, underscores or periods.' using errcode = '22023';
  end if;
  if wanted ~ '^[._]|[._]$' or wanted ~ '\.\.' then
    raise exception 'Your @ can''t start or end with a period or underscore, or have two periods in a row.' using errcode = '22023';
  end if;
  if not staff and (wanted ~ '(vybr8|vybe8|admin|moderator|support|official|staff)'
     or wanted in ('help', 'team', 'founder', 'settings', 'profile', 'explore', 'pricing', 'eat', 'events', 'orgs', 'root', 'null', 'undefined')) then
    raise exception 'That @ is reserved. Try another.' using errcode = '22023';
  end if;
  if not staff and cur.username_changed_at is not null and cur.username_changed_at > now() - interval '30 days' then
    raise exception 'You can change your @ again on %.', to_char(cur.username_changed_at + interval '30 days', 'FMMonth FMDD') using errcode = '22023';
  end if;
  if exists (select 1 from public.profiles where username = wanted::extensions.citext and id <> me) then
    raise exception 'That @ is taken. Try another.' using errcode = '23505';
  end if;
  if exists (select 1 from public.username_history h where h.old_username = wanted::extensions.citext and h.user_id <> me
             and h.changed_at > now() - interval '90 days') then
    raise exception 'That @ was used recently. Try another.' using errcode = '23505';
  end if;

  delete from public.username_history where old_username = wanted::extensions.citext;   -- taking back your own old name, or an expired one
  insert into public.username_history (old_username, user_id) values (cur.username, me)
    on conflict (old_username) do update set user_id = excluded.user_id, changed_at = now();
  perform set_config('vybr8.username_change', 'on', true);
  update public.profiles set username = trim(both '@ ' from p_new), username_changed_at = now() where id = me;
  perform set_config('vybr8.username_change', '', true);
  insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  values (me, 'profile.username_changed', 'profile', me, jsonb_build_object('from', cur.username::text, 'to', trim(both '@ ' from p_new)));
  return trim(both '@ ' from p_new);
end;
$$;
revoke execute on function public.change_username(text) from public, anon;
grant execute on function public.change_username(text) to authenticated;

-- Old profile links: /profile/<old name> → the person's current @ (if you can see their profile).
create or replace function public.username_redirect(p_old text)
returns text
language sql stable security definer
set search_path = ''
as $$
  select p.username::text
    from public.username_history h join public.profiles p on p.id = h.user_id
   where h.old_username = trim(both '@ ' from coalesce(p_old, ''))::extensions.citext
     and private.can_view(p.id, 'profile');
$$;
grant execute on function public.username_redirect(text) to anon, authenticated;

-- ═════ 20261017800100_cravezone.sql ═════
-- VYBR8 · CraveZone · Phase CZ-1 (taxonomy, item tags, search, results, map)
--
-- "I know what kind of thing I want, but not where to get it." CraveZone finds ITEMS that hit a craving,
-- then places that can hit it when no menu is on VYBR8 yet. Everything here works without AI.
-- The craving taxonomy lives in the database (craving_categories), never hard-coded in React.
-- See CRAVEZONE.md for the full design, privacy rules and later phases.

-- ── Taxonomy ───────────────────────────────────────────────────────────
create table public.craving_categories (
  id              smallint generated always as identity primary key,
  slug            text not null unique check (slug ~ '^[a-z][a-z0-9_]{1,30}$'),
  name            text not null check (char_length(name) between 2 and 40),
  emoji           text not null check (char_length(emoji) <= 8),
  tone            text not null default 'coral' check (tone in ('orange', 'coral', 'pink', 'mint', 'sky', 'lavender', 'gold')),
  sort_order      smallint not null default 100,
  active          boolean not null default true,
  indulgent       boolean not null default false,          -- Big Back Mode leans into these
  light           boolean not null default false,          -- "not too heavy" leans into these
  item_keywords   text[] not null default '{}',            -- whole words/phrases matched in item name, description, dish type
  exclude_keywords text[] not null default '{}',           -- "hot dog" is not spicy
  search_terms    text[] not null default '{}',            -- extra words people type ("sweet tooth")
  place_cuisines  text[] not null default '{}',            -- OpenStreetMap / VYBR8 cuisine tags
  place_kinds     text[] not null default '{}',            -- business kinds that always fit (bakery → bakery)
  place_name_keywords text[] not null default '{}',        -- "creamery", "donut"
  created_at      timestamptz not null default now()
);
alter table public.craving_categories enable row level security;
create policy "craving_categories: everyone reads active" on public.craving_categories for select to anon, authenticated
  using (active or private.is_staff());
create policy "craving_categories: team edits" on public.craving_categories for all to authenticated
  using (private.is_admin()) with check (private.is_admin());

